thread_local! {
    static NCC_OUTPUT_QUIET_OVERRIDE: Cell<bool> = const { Cell::new(false) };
}

pub(crate) struct NccOutputQuietGuard {
    previous: bool,
}

impl NccOutputQuietGuard {
    pub(crate) fn activate() -> Self {
        let previous = NCC_OUTPUT_QUIET_OVERRIDE.replace(true);
        Self { previous }
    }
}

impl Drop for NccOutputQuietGuard {
    fn drop(&mut self) {
        NCC_OUTPUT_QUIET_OVERRIDE.set(self.previous);
    }
}

pub(crate) fn ncc_child_output_quiet() -> bool {
    NCC_OUTPUT_QUIET_OVERRIDE.get()
        || matches!(
            std::env::var("NCC_CHILD_QUIET").as_deref(),
            Ok("1") | Ok("true") | Ok("yes")
        )
}

