    use super::*;

    fn parse_program(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_compact_pointer_index_write_reads_real_stride() {
        let ast = parse_program(
            r#"
use::stoud::memory::<ptr, heap>;

compactPointerBytes[@runtime] {
    stc:
        data: array<int, 4>;
        p: ptr<int>;
        cur: ptr<int>;
        i >> int = 0;
        read >> int = 0;
    fn:
        run() -> bool {
            public:
                p = alloc(4)!;
                cur = p;
                i = 0;

                while (i < 4) {
                    data[i] = i + 10;
                    *cur = i + 10;
                    cur++;
                    i++;
                }

                read = *(p + 2);
                free(p);
                return read == 12;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
        );
        let out = run_main(&ast).expect("compact pointer byte program should execute");
        assert_eq!(render_value(&out), "true");
    }

    #[test]
    fn runtime_type_contract_move_marks_drop_and_blocks_read_until_reinit() {
        let ast = parse_program(
            r#"
entry[@] {
    type:
        Token {
            public:
                id: int;
            drop:
                audit;
        }
    stc:
        t: Token;
        moved: Token;
        x: int;
    fn:
        run() -> bool {
            public:
                @t.id >> int : 1;
                @moved >> Token : move(@t);
                @x >> int : @t.id;
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
        );
        let err = run_main(&ast).expect_err("read after drop/move must fail");
        assert!(
            err.to_string().contains("E_TYPE_DROP_MOVED_001"),
            "unexpected error: {err}"
        );
    }

