    #[test]
    fn runtime_type_contracts_are_materialized_from_backend_opcodes() {
        let ast = parse_program(
            r#"
entry[@] {
    type:
        Ledger {
            public:
                id: int;
                owner: ptr<byte> | null;
            bounds:
                id: range(1..99);
            nullability:
                owner: nullable;
            ownership:
                owner: borrowed;
            invariant:
                @id >= 1;
            drop:
                release(owner);
        }
    stc:
        x: int;
    fn:
        run() -> bool {
            public:
                @x >> int : 1;
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
        );

        let contracts =
            runtime_collect_type_contracts_backend_first(&ast).expect("backend contract map");
        let ledger = contracts.get("ledger").expect("ledger contract");
        assert!(ledger.fields.contains_key("id"));
        assert!(ledger.fields.contains_key("owner"));
        assert!(ledger.bounds.contains_key("id"));
        assert!(ledger.nullability.contains_key("owner"));
        assert!(ledger.ownership.contains_key("owner"));
        assert_eq!(ledger.invariants.len(), 1);
        assert!(ledger.has_drop_contract);
    }

