    #[test]
    fn runtime_type_contract_interprocedural_move_denied_is_enforced() {
        let ast = parse_program(
            r#"
entry[@] {
    type:
        VaultMoveDenied {
            public:
                id: int;
            move:
                denied;
        }
    stc:
        v: VaultMoveDenied;
        outv: VaultMoveDenied;
        tmp: VaultMoveDenied;
    fn:
        inner(v: VaultMoveDenied) -> VaultMoveDenied {
            public:
                @tmp >> VaultMoveDenied : move(@v);
                return @tmp;
        }
        mid(v: VaultMoveDenied) -> VaultMoveDenied {
            public:
                return inner(copy.value(@v));
        }
        run() -> bool {
            public:
                @v.id >> int : 7;
                @outv >> VaultMoveDenied : mid(@v);
                return true;
        }
    ref main ->> @fn(run);
    fa:
        return true;
}
"#,
        );
        let err = run_main(&ast).expect_err("move denied must fail across nested calls");
        assert!(
            err.to_string().contains("E_TYPE_MOVE_DENIED_001"),
            "unexpected error: {err}"
        );
    }

