fn runtime_base_fn_name(name: &str) -> &str {
    name.split('<').next().unwrap_or(name)
}

fn runtime_fn_name_matches(spec_name: &str, requested_name: &str) -> bool {
    spec_name.eq_ignore_ascii_case(requested_name)
        || runtime_base_fn_name(spec_name)
            .eq_ignore_ascii_case(runtime_base_fn_name(requested_name))
}

fn runtime_implicit_kernel_call_path(fn_name: &str) -> Option<Vec<String>> {
    let base = runtime_base_fn_name(fn_name).trim().to_ascii_lowercase();
    let (module, name): (&[&str], &str) = match base.as_str() {
        "register" | "taskregister" => (&["kernel", "task", "core"], "register"),
        "taskspawn" => (&["kernel", "task", "core"], "spawn"),
        "taskblock" => (&["kernel", "task", "core"], "block"),
        "taskwake" => (&["kernel", "task", "core"], "wake"),
        "taskexit" => (&["kernel", "task", "core"], "exit"),
        "taskstate" => (&["kernel", "task", "core"], "state"),
        "taskcurrent" => (&["kernel", "task", "core"], "current"),
        "open" | "scheduleropen" => (&["kernel", "schedule", "core"], "open"),
        "schedulerclose" => (&["kernel", "schedule", "core"], "close"),
        "next" | "schedulernext" => (&["kernel", "schedule", "core"], "next"),
        "schedulertick" => (&["kernel", "schedule", "core"], "tick"),
        "scheduleryield" => (&["kernel", "schedule", "core"], "yieldNow"),
        "schedulerbind" => (&["kernel", "schedule", "core"], "bind"),
        "schedulernexton" => (&["kernel", "schedule", "core"], "nextOn"),
        "schedulercurrenton" => (&["kernel", "schedule", "core"], "currentOn"),
        "cpuregister" => (&["kernel", "cpu", "core"], "register"),
        "cpustart" => (&["kernel", "cpu", "core"], "start"),
        "cpuonline" => (&["kernel", "cpu", "core"], "online"),
        "cpucurrent" => (&["kernel", "cpu", "core"], "current"),
        "cpucount" => (&["kernel", "cpu", "core"], "count"),
        "cpuonlinecount" => (&["kernel", "cpu", "core"], "onlineCount"),
        "cpusetcurrent" => (&["kernel", "cpu", "core"], "setCurrent"),
        "cpulocalset" => (&["kernel", "cpu", "core"], "localSet"),
        "cpulocalget" => (&["kernel", "cpu", "core"], "localGet"),
        "cpustack" => (&["kernel", "cpu", "core"], "stack"),
        "ipisend" => (&["kernel", "ipi", "core"], "send"),
        "ipibroadcast" => (&["kernel", "ipi", "core"], "broadcast"),
        "ipipending" => (&["kernel", "ipi", "core"], "pending"),
        "ipipeek" => (&["kernel", "ipi", "core"], "peek"),
        "ipiack" => (&["kernel", "ipi", "core"], "ack"),
        "quarantine" | "kernelquarantine" => (&["kernel", "control", "core"], "quarantine"),
        "panic" | "kernelpanic" => (&["kernel", "control", "core"], "panic"),
        "kernelhalt" => (&["kernel", "control", "core"], "halt"),
        "kernelpanicstate" => (&["kernel", "control", "core"], "panicState"),
        "frameinit" => (&["kernel", "memory", "core"], "frameInit"),
        "framealloc" => (&["kernel", "memory", "core"], "frameAlloc"),
        "framefree" => (&["kernel", "memory", "core"], "frameFree"),
        "pagemap" => (&["kernel", "memory", "core"], "pageMap"),
        "pageunmap" => (&["kernel", "memory", "core"], "pageUnmap"),
        "pageprotect" => (&["kernel", "memory", "core"], "pageProtect"),
        "pagetranslate" => (&["kernel", "memory", "core"], "pageTranslate"),
        "irqregister" => (&["kernel", "interrupt", "core"], "register"),
        "irqenable" => (&["kernel", "interrupt", "core"], "enable"),
        "irqdisable" => (&["kernel", "interrupt", "core"], "disable"),
        "irqisenabled" => (&["kernel", "interrupt", "core"], "isEnabled"),
        "irqdispatch" => (&["kernel", "interrupt", "core"], "dispatch"),
        "irqeoi" => (&["kernel", "interrupt", "core"], "eoi"),
        "syscallregister" => (&["kernel", "syscall", "core"], "register"),
        "syscallavailable" => (&["kernel", "syscall", "core"], "available"),
        "syscallinvoke" => (&["kernel", "syscall", "core"], "invoke"),
        "driverregister" => (&["kernel", "driver", "core"], "register"),
        "driverstart" => (&["kernel", "driver", "core"], "start"),
        "driverstop" => (&["kernel", "driver", "core"], "stop"),
        "driverread" => (&["kernel", "driver", "core"], "read"),
        "driverwrite" => (&["kernel", "driver", "core"], "write"),
        "driverstatus" => (&["kernel", "driver", "core"], "status"),
        "copyfromuser" => (&["kernel", "user", "core"], "copyFromUser"),
        "copytouser" => (&["kernel", "user", "core"], "copyToUser"),
        "kernelbootinfo" => (&["kernel", "boot", "core"], "info"),
        _ => return None,
    };
    let mut path: Vec<String> = module
        .iter()
        .map(|segment| (*segment).to_string())
        .collect();
    path.push(name.to_string());
    Some(path)
}

fn use_path_targets_list_family(path: &[String]) -> bool {
    (path.len() >= 3
        && path[0].eq_ignore_ascii_case("nC")
        && path[1].eq_ignore_ascii_case("runtime")
        && (path[2].eq_ignore_ascii_case("list") || path[2].eq_ignore_ascii_case("queue")))
        || (path.len() >= 2
            && path[0].eq_ignore_ascii_case("runtime")
            && (path[1].eq_ignore_ascii_case("list") || path[1].eq_ignore_ascii_case("queue")))
        || (path.len() >= 2
            && path[0].eq_ignore_ascii_case("nC")
            && path[1].eq_ignore_ascii_case("list"))
        || (!path.is_empty() && path[0].eq_ignore_ascii_case("list"))
}

fn runtime_family_suffix_from_use_path(path: &[String]) -> Option<String> {
    if path.len() == 3
        && path[0].eq_ignore_ascii_case("nC")
        && path[1].eq_ignore_ascii_case("runtime")
    {
        Some(path[2].to_ascii_lowercase())
    } else if path.len() == 2 && path[0].eq_ignore_ascii_case("runtime") {
        Some(path[1].to_ascii_lowercase())
    } else {
        None
    }
}

fn runtime_family_module_path_from_use_path(path: &[String]) -> Option<Vec<String>> {
    if use_path_targets_list_family(path) {
        return Some(vec!["runtime".to_string(), "queue".to_string()]);
    }
    let suffix = runtime_family_suffix_from_use_path(path)?;
    if suffix.eq_ignore_ascii_case("list") {
        return Some(vec!["runtime".to_string(), "queue".to_string()]);
    }
    Some(vec!["runtime".to_string(), suffix])
}

fn runtime_api_function_specs_for_module(
    path: &[String],
) -> Option<Vec<(String, usize, bool, String)>> {
    let fam = ncc_parser::runtime_api_find_family_by_module_path(path)?;
    Some(
        fam.functions
            .iter()
            .map(|f| {
                (
                    f.name.to_string(),
                    f.arity_min,
                    f.variadic,
                    f.return_ty.to_string(),
                )
            })
            .collect(),
    )
}

fn runtime_list_alias_specs() -> Vec<(String, usize, bool, String)> {
    vec![
        ("listCreate<T>".to_string(), 0, false, "list<T>".to_string()),
        (
            "listCreateWithCapacity<T>".to_string(),
            1,
            false,
            "list<T>".to_string(),
        ),
        (
            "listFromArray<T>".to_string(),
            1,
            false,
            "list<T>".to_string(),
        ),
        ("listLen".to_string(), 1, false, "int".to_string()),
        ("listCapacity".to_string(), 1, false, "int".to_string()),
        ("listIsEmpty".to_string(), 1, false, "bool".to_string()),
        ("listAdd".to_string(), 2, false, "bool".to_string()),
        ("listPush".to_string(), 2, false, "bool".to_string()),
        ("listPop".to_string(), 1, false, "Option<T>".to_string()),
        ("listGet".to_string(), 2, false, "T".to_string()),
        ("listSet".to_string(), 3, false, "bool".to_string()),
        ("listInsert".to_string(), 3, false, "bool".to_string()),
        ("listRemoveAt".to_string(), 2, false, "T".to_string()),
        ("listClear".to_string(), 1, false, "bool".to_string()),
        ("listContains".to_string(), 2, false, "bool".to_string()),
        ("listIndexOf".to_string(), 2, false, "int".to_string()),
        ("listSlice".to_string(), 3, false, "list<T>".to_string()),
        ("listAsArray".to_string(), 1, false, "array<T>".to_string()),
        (
            "listAsRegion".to_string(),
            1,
            false,
            "memRegion<T>".to_string(),
        ),
        ("listClone".to_string(), 1, false, "list<T>".to_string()),
        ("listCopy".to_string(), 1, false, "list<T>".to_string()),
        ("listMove".to_string(), 3, false, "bool".to_string()),
        ("listSwap".to_string(), 3, false, "bool".to_string()),
    ]
}

fn runtime_api_function_specs_for_any_path(
    path: &[String],
) -> Option<Vec<(String, usize, bool, String)>> {
    let mut specs = runtime_api_function_specs_for_module(path).or_else(|| {
        let resolved = runtime_family_module_path_from_use_path(path)?;
        runtime_api_function_specs_for_module(&resolved)
    })?;

    let resolved = runtime_family_module_path_from_use_path(path).unwrap_or_else(|| path.to_vec());
    if path_equals(&resolved, &["runtime", "queue"]) || path_equals(&resolved, &["runtime", "list"])
    {
        for (name, arity, variadic, ret) in runtime_list_alias_specs() {
            if !specs
                .iter()
                .any(|(existing, _, _, _)| runtime_fn_name_matches(existing, &name))
            {
                specs.push((name, arity, variadic, ret));
            }
        }
    }

    Some(specs)
}

fn resolve_static_import_runtime_spec(
    path: &[String],
) -> Option<(Vec<String>, ResolvedImportRuntimeSpec)> {
    if path.len() < 2 {
        return None;
    }

    let module_path = path[..path.len() - 1].to_vec();
    let fn_name = path.last()?;
    let specs = import_runtime_specs_for_module(&module_path)?;
    let spec = specs
        .iter()
        .copied()
        .find(|spec| runtime_fn_name_matches(spec.name, fn_name))?;
    Some((
        module_path,
        ResolvedImportRuntimeSpec {
            name: spec.name.to_string(),
            return_ty: spec.return_ty.to_string(),
            arity_min: spec.arity,
            variadic: false,
            value_kind: spec.value_kind,
        },
    ))
}

fn resolve_dynamic_import_runtime_spec(
    path: &[String],
) -> Option<(Vec<String>, ResolvedImportRuntimeSpec)> {
    if path.len() < 2 {
        return None;
    }

    let module_path = path[..path.len() - 1].to_vec();
    let fn_name = path.last()?;
    let resolved_module_path =
        if let Some(suffix) = runtime_family_suffix_from_use_path(&module_path) {
            vec!["runtime".to_string(), suffix]
        } else {
            module_path.clone()
        };
    let specs = runtime_api_function_specs_for_module(&resolved_module_path)?;
    let (name, arity_min, variadic, return_ty) = specs
        .into_iter()
        .find(|(name, _, _, _)| runtime_fn_name_matches(name, fn_name))?;
    let value_kind =
        dynamic_import_runtime_value_kind(&resolved_module_path, &name, return_ty.as_str());
    Some((
        resolved_module_path,
        ResolvedImportRuntimeSpec {
            name,
            return_ty,
            arity_min,
            variadic,
            value_kind,
        },
    ))
}

fn find_import_runtime_spec(path: &[String]) -> Option<(Vec<String>, ResolvedImportRuntimeSpec)> {
    resolve_static_import_runtime_spec(path).or_else(|| resolve_dynamic_import_runtime_spec(path))
}

fn find_import_runtime_overload_for_arity(
    module_path: &[String],
    fn_name: &str,
    argc: usize,
) -> Option<ResolvedImportRuntimeSpec> {
    let mut candidates: Vec<ResolvedImportRuntimeSpec> = Vec::new();

    if let Some(static_specs) = import_runtime_specs_for_module(module_path) {
        for spec in static_specs {
            if runtime_fn_name_matches(spec.name, fn_name) {
                candidates.push(ResolvedImportRuntimeSpec {
                    name: spec.name.to_string(),
                    return_ty: spec.return_ty.to_string(),
                    arity_min: spec.arity,
                    variadic: false,
                    value_kind: spec.value_kind,
                });
            }
        }
    }

    if let Some(dynamic_specs) = runtime_api_function_specs_for_any_path(module_path) {
        for (name, arity_min, variadic, return_ty) in dynamic_specs {
            if runtime_fn_name_matches(&name, fn_name) {
                let value_kind =
                    dynamic_import_runtime_value_kind(module_path, &name, return_ty.as_str());
                candidates.push(ResolvedImportRuntimeSpec {
                    name,
                    return_ty,
                    arity_min,
                    variadic,
                    value_kind,
                });
            }
        }
    }

    candidates.into_iter().find(|spec| {
        (!spec.variadic && spec.arity_min == argc) || (spec.variadic && argc >= spec.arity_min)
    })
}

fn dynamic_import_runtime_value_kind(
    module_path: &[String],
    fn_name: &str,
    return_ty: &str,
) -> ImportRuntimeValueKind {
    if path_equals(module_path, &["runtime", "random"])
        && runtime_fn_name_matches(fn_name, "randomInt")
        && return_ty.eq_ignore_ascii_case("int")
    {
        return ImportRuntimeValueKind::RandomInt;
    }
    if path_equals(module_path, &["runtime", "random"])
        && runtime_fn_name_matches(fn_name, "randomBool")
        && return_ty.eq_ignore_ascii_case("bool")
    {
        return ImportRuntimeValueKind::RandomBool;
    }
    if path_equals(module_path, &["runtime", "random"])
        && runtime_fn_name_matches(fn_name, "randomFloat")
        && (return_ty.eq_ignore_ascii_case("ft") || return_ty.eq_ignore_ascii_case("ft64"))
    {
        return ImportRuntimeValueKind::RandomFloat;
    }
    if path_equals(module_path, &["runtime", "random"])
        && (runtime_fn_name_matches(fn_name, "randomRange")
            || runtime_fn_name_matches(fn_name, "randInt"))
        && return_ty.eq_ignore_ascii_case("int")
    {
        return ImportRuntimeValueKind::RandomRange;
    }
    if path_equals(module_path, &["runtime", "random"])
        && runtime_fn_name_matches(fn_name, "seed")
        && return_ty.eq_ignore_ascii_case("bool")
    {
        return ImportRuntimeValueKind::RandomSeed;
    }
    if path_equals(module_path, &["runtime", "std"]) && runtime_fn_name_matches(fn_name, "stdIn") {
        return ImportRuntimeValueKind::StdIn;
    }
    if path_equals(module_path, &["runtime", "std"]) && runtime_fn_name_matches(fn_name, "stdOut") {
        return ImportRuntimeValueKind::StdOut;
    }
    if path_equals(module_path, &["runtime", "std"]) && runtime_fn_name_matches(fn_name, "stdErr") {
        return ImportRuntimeValueKind::StdErr;
    }
    if path_equals(module_path, &["runtime", "std"])
        && runtime_fn_name_matches(fn_name, "isInteractive")
    {
        return ImportRuntimeValueKind::StdInteractive;
    }
    if path_equals(module_path, &["runtime", "fs"]) && runtime_fn_name_matches(fn_name, "writeFile")
    {
        return ImportRuntimeValueKind::FsWriteFile;
    }

    ImportRuntimeValueKind::BoolTrue
}

fn runtime_random_next(state: &mut ExecState) -> u64 {
    let mut value = state.runtime_random_state.unwrap_or(0x9e37_79b9_7f4a_7c15);
    value ^= value << 13;
    value ^= value >> 7;
    value ^= value << 17;
    if value == 0 {
        value = 0x9e37_79b9_7f4a_7c15;
    }
    state.runtime_random_state = Some(value);
    value
}

fn import_runtime_type_from_string(s: &str) -> Option<String> {
    let inner = s.strip_prefix("<import-call:")?.strip_suffix('>')?;
    let parts: Vec<String> = inner.split('.').map(|x| x.to_string()).collect();
    let (_module_path, spec) = find_import_runtime_spec(&parts)?;
    Some(spec.return_ty)
}

fn import_exported_functions(path: &[String]) -> Option<&'static [&'static str]> {
    if path_equals(path, &["system", "net", "core"]) || path_equals(path, &["alt", "net", "core"]) {
        Some(&["connect", "listen", "accept", "send", "recv", "disconnect"])
    } else if path_equals(path, &["memory", "heap", "manager"]) {
        Some(&["alloc", "free", "realloc", "zero"])
    } else if path_equals(path, &["runtime", "trace"]) || path_equals(path, &["runtime", "alias"]) {
        Some(&["mark"])
    } else if path_equals(path, &["runtime", "time"]) {
        Some(&[
            "now",
            "nowMs",
            "monotonic",
            "monotonicMs",
            "monotonicNs",
            "sleep",
            "sleepUntilMs",
        ])
    } else if path_equals(path, &["runtime", "terminal"]) {
        Some(&[
            "clear",
            "moveCursor",
            "hideCursor",
            "showCursor",
            "enterRawMode",
            "exitRawMode",
            "readKeyNonBlocking",
            "windowOpen",
            "windowShow",
            "windowHide",
            "windowPoll",
            "windowWaitEvent",
            "windowClose",
            "windowIsOpen",
            "windowIsFocused",
            "windowSetTitle",
            "windowSetSize",
            "windowWidth",
            "windowHeight",
            "windowDpi",
            "windowRefreshHz",
            "windowState",
            "windowSetState",
            "windowFocus",
        ])
    } else if path_equals(path, &["security", "policy", "strict"]) {
        Some(&["evaluate"])
    } else if path_equals(path, &["security", "intel", "attack"]) {
        Some(&["simulate"])
    } else if path_equals(path, &["system", "proc", "core"]) {
        Some(&["spawn", "wait"])
    } else if path_equals(path, &["system", "io", "core"]) {
        Some(&["write"])
    } else if path_equals(path, &["system", "service", "core"]) {
        Some(&["register", "open", "degrade", "recover", "reconcile"])
    } else if path_equals(path, &["tooling", "build", "core"]) {
        Some(&["plan", "apply"])
    } else if path_equals(path, &["tooling", "lint", "core"])
        || path_equals(path, &["tooling", "fmt", "core"])
    {
        Some(&["run"])
    } else if path_equals(path, &["tooling", "pkg", "core"]) {
        Some(&["pack", "publish"])
    } else if path_equals(path, &["compiler", "parse", "ast"]) {
        Some(&["load"])
    } else if path_equals(path, &["compiler", "semantic", "core"]) {
        Some(&["check"])
    } else if path_equals(path, &["compiler", "backend", "machine"]) {
        Some(&["materialize"])
    } else if path_equals(path, &["kernel", "task", "core"]) {
        Some(&[
            "register", "spawn", "block", "wake", "exit", "state", "current",
        ])
    } else if path_equals(path, &["kernel", "schedule", "core"]) {
        Some(&["open", "close", "next", "tick", "yieldNow"])
    } else if path_equals(path, &["kernel", "control", "core"]) {
        Some(&["quarantine", "panic", "halt", "panicState"])
    } else if path_equals(path, &["kernel", "memory", "core"]) {
        Some(&[
            "frameInit",
            "frameAlloc",
            "frameFree",
            "pageMap",
            "pageUnmap",
            "pageProtect",
            "pageTranslate",
        ])
    } else if path_equals(path, &["kernel", "interrupt", "core"]) {
        Some(&[
            "register",
            "enable",
            "disable",
            "isEnabled",
            "dispatch",
            "eoi",
        ])
    } else if path_equals(path, &["kernel", "syscall", "core"]) {
        Some(&["register", "available", "invoke"])
    } else if path_equals(path, &["kernel", "driver", "core"]) {
        Some(&["register", "start", "stop", "read", "write", "status"])
    } else if path_equals(path, &["kernel", "user", "core"]) {
        Some(&["copyFromUser", "copyToUser"])
    } else if path_equals(path, &["kernel", "boot", "core"]) {
        Some(&["info"])
    } else if path_equals(path, &["ai", "session", "core"]) {
        Some(&["open", "close"])
    } else if path_equals(path, &["ai", "model", "core"]) {
        Some(&["select"])
    } else if path_equals(path, &["ai", "agent", "core"]) {
        Some(&["plan", "critique", "execute"])
    } else if path_equals(path, &["ai", "chat", "core"]) {
        Some(&["complete"])
    } else if path_equals(path, &["ai", "memory", "core"]) {
        Some(&["remember", "recall"])
    } else {
        None
    }
}

fn import_exported_functions_any(path: &[String]) -> Option<Vec<String>> {
    let mut names: Vec<String> = Vec::new();

    if let Some(static_exports) = import_exported_functions(path) {
        for name in static_exports {
            if !names
                .iter()
                .any(|existing| existing.eq_ignore_ascii_case(name))
            {
                names.push((*name).to_string());
            }
        }
    }

    if let Some(dynamic_specs) = runtime_api_function_specs_for_any_path(path) {
        for (name, _arity_min, _variadic, _return_ty) in dynamic_specs {
            if !names
                .iter()
                .any(|existing| runtime_fn_name_matches(existing.as_str(), &name))
            {
                names.push(name);
            }
        }
    }

    if names.is_empty() {
        None
    } else {
        Some(names)
    }
}

