fn runtime_known_import_modules() -> Vec<Vec<String>> {
    let mut out = vec![
        vec!["system".into(), "net".into(), "core".into()],
        vec!["alt".into(), "net".into(), "core".into()],
        vec!["memory".into(), "heap".into(), "manager".into()],
        vec!["runtime".into(), "trace".into()],
        vec!["runtime".into(), "alias".into()],
        vec!["runtime".into(), "time".into()],
        vec!["security".into(), "policy".into(), "strict".into()],
        vec!["security".into(), "intel".into(), "attack".into()],
        vec!["system".into(), "proc".into(), "core".into()],
        vec!["system".into(), "io".into(), "core".into()],
        vec!["system".into(), "service".into(), "core".into()],
        vec!["tooling".into(), "build".into(), "core".into()],
        vec!["tooling".into(), "lint".into(), "core".into()],
        vec!["tooling".into(), "fmt".into(), "core".into()],
        vec!["tooling".into(), "pkg".into(), "core".into()],
        vec!["compiler".into(), "parse".into(), "ast".into()],
        vec!["compiler".into(), "semantic".into(), "core".into()],
        vec!["compiler".into(), "backend".into(), "machine".into()],
        vec!["kernel".into(), "task".into(), "core".into()],
        vec!["kernel".into(), "schedule".into(), "core".into()],
        vec!["kernel".into(), "control".into(), "core".into()],
        vec!["kernel".into(), "memory".into(), "core".into()],
        vec!["kernel".into(), "interrupt".into(), "core".into()],
        vec!["kernel".into(), "syscall".into(), "core".into()],
        vec!["kernel".into(), "driver".into(), "core".into()],
        vec!["kernel".into(), "user".into(), "core".into()],
        vec!["kernel".into(), "boot".into(), "core".into()],
        vec!["ai".into(), "session".into(), "core".into()],
        vec!["ai".into(), "model".into(), "core".into()],
        vec!["ai".into(), "agent".into(), "core".into()],
        vec!["ai".into(), "chat".into(), "core".into()],
        vec!["ai".into(), "memory".into(), "core".into()],
    ];

    for fam in ncc_parser::runtime_api_family_specs() {
        let module: Vec<String> = fam
            .module_path
            .split('.')
            .filter(|segment| !segment.is_empty())
            .map(|segment| segment.to_string())
            .collect();
        if module.is_empty() {
            continue;
        }
        if !out.iter().any(|existing| {
            ncc_ast::import_path_matches(
                existing,
                &module.iter().map(String::as_str).collect::<Vec<_>>(),
            )
        }) {
            out.push(module);
        }
    }

    out
}

fn resolve_unqualified_import_runtime_call_paths(
    ast: &ncc_ast::Program,
    fn_name: &str,
) -> Vec<Vec<String>> {
    let mut out: Vec<Vec<String>> = Vec::new();

    for use_decl in &ast.uses {
        let mut module_candidates: Vec<Vec<String>> = Vec::new();

        if use_decl.wildcard {
            for known in runtime_known_import_modules() {
                if ncc_ast::import_path_starts_with(&known, &use_decl.path)
                    || wildcard_runtime_prefix_matches(&use_decl.path, &known)
                {
                    module_candidates.push(known);
                }
            }
            module_candidates.extend(runtime_alias_module_paths_for_use(&use_decl.path));
        } else {
            if use_decl
                .path
                .last()
                .map(|segment| segment.eq_ignore_ascii_case(fn_name))
                .unwrap_or(false)
                && use_decl.path.len() > 1
            {
                module_candidates.push(use_decl.path[..use_decl.path.len() - 1].to_vec());
            }
            module_candidates.push(use_decl.path.clone());
            module_candidates.extend(runtime_alias_module_paths_for_use(&use_decl.path));
        }

        for module_path in module_candidates {
            let Some(exports) = import_exported_functions_any(&module_path) else {
                continue;
            };
            if !exports
                .iter()
                .any(|exported| runtime_fn_name_matches(exported.as_str(), fn_name))
            {
                continue;
            }
            let mut full = runtime_family_module_path_from_use_path(&module_path)
                .unwrap_or_else(|| module_path.clone());
            full.push(fn_name.to_string());
            if !out.iter().any(|existing| existing == &full) {
                out.push(full);
            }
        }
    }

    if out.is_empty() {
        if let Some(path) = runtime_implicit_kernel_call_path(fn_name) {
            out.push(path);
        }
    }

    out
}

fn has_visible_import_for_module(uses: &[ncc_ast::UseDecl], module_path: &[String]) -> bool {
    uses.iter().any(|u| {
        if u.wildcard {
            ncc_ast::import_path_starts_with(module_path, &u.path)
                || wildcard_runtime_prefix_matches(&u.path, module_path)
        } else {
            (u.path.len() == module_path.len()
                && ncc_ast::import_path_starts_with(&u.path, module_path))
                || use_decl_alias_matches_module(&u.path, module_path)
        }
    })
}

fn runtime_resolve_qualified_call_precheck(
    ast: &ncc_ast::Program,
    path: &[String],
) -> Result<(), Box<dyn std::error::Error>> {
    if path.len() < 2 {
        return Err(format!("qualified call path not supported: {:?}", path).into());
    }

    if path.len() == 2 {
        if runtime_is_data_motion_qualified_call(path) {
            return Ok(());
        }
        let container_name = &path[0];
        let fn_name = &path[1];

        let Some(container) = ast.containers.iter().find(|c| &c.name == container_name) else {
            return Err(format!("container '{}' not found", container_name).into());
        };

        let found = container.sections.iter().any(|section| match section {
            ncc_ast::Section::Fn(funcs) | ncc_ast::Section::MoveFn(funcs) => {
                funcs.iter().any(|f| &f.name == fn_name)
            }
            _ => false,
        });

        if !found {
            return Err(format!("function '{}.{}' not found", container_name, fn_name).into());
        }

        return Ok(());
    }

    let fn_name = path
        .last()
        .expect("qualified call path len already checked");
    let module_path = &path[..path.len() - 1];

    let kernel_profile_module = module_path.len() == 3
        && module_path[0].eq_ignore_ascii_case("kernel")
        && module_path[2].eq_ignore_ascii_case("core")
        && [
            "task",
            "schedule",
            "control",
            "memory",
            "interrupt",
            "syscall",
            "driver",
            "user",
            "boot",
        ]
        .iter()
        .any(|family| module_path[1].eq_ignore_ascii_case(family));
    if kernel_profile_module {
        if import_exported_functions_any(module_path).is_some_and(|exports| {
            exports
                .iter()
                .any(|function| runtime_fn_name_matches(function, fn_name))
        }) {
            return Ok(());
        }
    }

    if !has_visible_import_for_module(&ast.uses, module_path) {
        return Err(format!("unresolved function path '{}'", path.join(".")).into());
    }

    if let Some(exports) = import_exported_functions_any(module_path) {
        if !exports
            .iter()
            .any(|f| runtime_fn_name_matches(f.as_str(), fn_name))
        {
            return Err(format!(
                "function '{}' not found in import '{}'",
                fn_name,
                module_path.join(".")
            )
            .into());
        }
        return Ok(());
    }

    Err(format!(
        "function '{}' not found in import '{}'",
        fn_name,
        module_path.join(".")
    )
    .into())
}

fn runtime_option_payload_from_argument(
    arg_values: &[RuntimeValue],
    call_name: &str,
) -> Result<RuntimeOptionPayload, Box<dyn std::error::Error>> {
    let Some(value) = arg_values.first() else {
        return Err(format!("{call_name} expects option argument").into());
    };
    runtime_option_payload(value)
        .ok_or_else(|| format!("{call_name} expects option argument").into())
}

fn runtime_result_payload_from_argument(
    arg_values: &[RuntimeValue],
    call_name: &str,
) -> Result<RuntimeResultPayload, Box<dyn std::error::Error>> {
    let Some(value) = arg_values.first() else {
        return Err(format!("{call_name} expects result argument").into());
    };
    runtime_result_payload(value).ok_or_else(|| {
        format!(
            "{call_name} expects result argument, got {} ({})",
            render_value(value),
            runtime_type_from_value(value)
        )
        .into()
    })
}

fn runtime_eval_option_result_family_call(
    full_path: &str,
    arg_values: &[RuntimeValue],
) -> Option<Result<RuntimeValue, Box<dyn std::error::Error>>> {
    match full_path {
        "runtime.option.some" => {
            if arg_values.len() != 1 {
                return Some(Err("runtime.option.some expects exactly 1 argument".into()));
            }
            Some(Ok(runtime_make_option_some(arg_values[0].clone())))
        }
        "runtime.option.none" => {
            if !arg_values.is_empty() {
                return Some(Err("runtime.option.none expects 0 arguments".into()));
            }
            Some(Ok(runtime_make_option_none()))
        }
        "runtime.option.issome" => {
            if arg_values.len() != 1 {
                return Some(Err(
                    "runtime.option.isSome expects exactly 1 argument".into()
                ));
            }
            let payload = runtime_option_payload_from_argument(arg_values, "runtime.option.isSome");
            Some(
                payload.map(|value| {
                    RuntimeValue::Bool(matches!(value, RuntimeOptionPayload::Some(_)))
                }),
            )
        }
        "runtime.option.isnone" => {
            if arg_values.len() != 1 {
                return Some(Err(
                    "runtime.option.isNone expects exactly 1 argument".into()
                ));
            }
            let payload = runtime_option_payload_from_argument(arg_values, "runtime.option.isNone");
            Some(
                payload
                    .map(|value| RuntimeValue::Bool(matches!(value, RuntimeOptionPayload::None))),
            )
        }
        "runtime.option.unwrapoption" => {
            if arg_values.len() != 1 {
                return Some(Err(
                    "runtime.option.unwrapOption expects exactly 1 argument".into(),
                ));
            }
            let payload =
                runtime_option_payload_from_argument(arg_values, "runtime.option.unwrapOption");
            Some(payload.and_then(|value| match value {
                RuntimeOptionPayload::Some(inner) => Ok(inner),
                RuntimeOptionPayload::None => {
                    Err("RuntimeOptionUnwrapNone: attempted to unwrap none option value".into())
                }
            }))
        }
        "runtime.option.unwrapoptionor" => {
            if arg_values.len() != 2 {
                return Some(Err(
                    "runtime.option.unwrapOptionOr expects exactly 2 arguments".into(),
                ));
            }
            let payload =
                runtime_option_payload_from_argument(arg_values, "runtime.option.unwrapOptionOr");
            Some(payload.map(|value| match value {
                RuntimeOptionPayload::Some(inner) => inner,
                RuntimeOptionPayload::None => arg_values[1].clone(),
            }))
        }
        "runtime.result.ok" => {
            if arg_values.len() != 1 {
                return Some(Err("runtime.result.ok expects exactly 1 argument".into()));
            }
            Some(Ok(runtime_make_result_ok(arg_values[0].clone())))
        }
        "runtime.result.err" => {
            if arg_values.len() != 1 {
                return Some(Err("runtime.result.err expects exactly 1 argument".into()));
            }
            Some(Ok(runtime_make_result_err(arg_values[0].clone())))
        }
        "runtime.result.isok" => {
            if arg_values.len() != 1 {
                return Some(Err("runtime.result.isOk expects exactly 1 argument".into()));
            }
            let payload = runtime_result_payload_from_argument(arg_values, "runtime.result.isOk");
            Some(
                payload
                    .map(|value| RuntimeValue::Bool(matches!(value, RuntimeResultPayload::Ok(_)))),
            )
        }
        "runtime.result.iserr" => {
            if arg_values.len() != 1 {
                return Some(Err("runtime.result.isErr expects exactly 1 argument".into()));
            }
            let payload = runtime_result_payload_from_argument(arg_values, "runtime.result.isErr");
            Some(
                payload
                    .map(|value| RuntimeValue::Bool(matches!(value, RuntimeResultPayload::Err(_)))),
            )
        }
        "runtime.result.unwrap" => {
            if arg_values.len() != 1 {
                return Some(Err(
                    "runtime.result.unwrap expects exactly 1 argument".into()
                ));
            }
            let payload = runtime_result_payload_from_argument(arg_values, "runtime.result.unwrap");
            Some(payload.and_then(|value| match value {
                RuntimeResultPayload::Ok(inner) => Ok(inner),
                RuntimeResultPayload::Err(_) => {
                    Err("RuntimeResultUnwrapError: attempted to unwrap err result value".into())
                }
            }))
        }
        "runtime.result.unwrapor" => {
            if arg_values.len() != 2 {
                return Some(Err(
                    "runtime.result.unwrapOr expects exactly 2 arguments".into()
                ));
            }
            let payload =
                runtime_result_payload_from_argument(arg_values, "runtime.result.unwrapOr");
            Some(payload.map(|value| match value {
                RuntimeResultPayload::Ok(inner) => inner,
                RuntimeResultPayload::Err(_) => arg_values[1].clone(),
            }))
        }
        "runtime.result.errorof" => {
            if arg_values.len() != 1 {
                return Some(Err(
                    "runtime.result.errorOf expects exactly 1 argument".into()
                ));
            }
            let payload =
                runtime_result_payload_from_argument(arg_values, "runtime.result.errorOf");
            Some(payload.and_then(|value| {
                match value {
                    RuntimeResultPayload::Ok(_) => Err(
                        "RuntimeResultExpectedError: attempted to extract an error from ok result"
                            .into(),
                    ),
                    RuntimeResultPayload::Err(err) => Ok(err),
                }
            }))
        }
        _ => None,
    }
}

fn runtime_eval_option_result_method_call(
    receiver: &RuntimeValue,
    method: &str,
    arg_values: &[RuntimeValue],
) -> Option<Result<RuntimeValue, Box<dyn std::error::Error>>> {
    if let Some(payload) = runtime_option_payload(receiver) {
        return Some(match method {
            "isSome" => {
                if !arg_values.is_empty() {
                    Err("Option.isSome expects 0 arguments".into())
                } else {
                    Ok(RuntimeValue::Bool(matches!(
                        payload,
                        RuntimeOptionPayload::Some(_)
                    )))
                }
            }
            "isNone" => {
                if !arg_values.is_empty() {
                    Err("Option.isNone expects 0 arguments".into())
                } else {
                    Ok(RuntimeValue::Bool(matches!(
                        payload,
                        RuntimeOptionPayload::None
                    )))
                }
            }
            "unwrap" | "unwrapOption" => {
                if !arg_values.is_empty() {
                    Err(format!("Option.{method} expects 0 arguments").into())
                } else {
                    match payload {
                        RuntimeOptionPayload::Some(value) => Ok(value),
                        RuntimeOptionPayload::None => Err(
                            "RuntimeOptionUnwrapNone: attempted to unwrap none option value".into(),
                        ),
                    }
                }
            }
            "unwrapOr" | "unwrapOptionOr" => {
                if arg_values.len() != 1 {
                    Err(format!("Option.{method} expects exactly 1 argument").into())
                } else {
                    Ok(match payload {
                        RuntimeOptionPayload::Some(value) => value,
                        RuntimeOptionPayload::None => arg_values[0].clone(),
                    })
                }
            }
            _ => return None,
        });
    }

    if let Some(payload) = runtime_result_payload(receiver) {
        return Some(match method {
            "isOk" => {
                if !arg_values.is_empty() {
                    Err("Result.isOk expects 0 arguments".into())
                } else {
                    Ok(RuntimeValue::Bool(matches!(
                        payload,
                        RuntimeResultPayload::Ok(_)
                    )))
                }
            }
            "isErr" => {
                if !arg_values.is_empty() {
                    Err("Result.isErr expects 0 arguments".into())
                } else {
                    Ok(RuntimeValue::Bool(matches!(
                        payload,
                        RuntimeResultPayload::Err(_)
                    )))
                }
            }
            "unwrap" => {
                if !arg_values.is_empty() {
                    Err("Result.unwrap expects 0 arguments".into())
                } else {
                    match payload {
                        RuntimeResultPayload::Ok(value) => Ok(value),
                        RuntimeResultPayload::Err(_) => Err(
                            "RuntimeResultUnwrapError: attempted to unwrap err result value".into(),
                        ),
                    }
                }
            }
            "unwrapOr" => {
                if arg_values.len() != 1 {
                    Err("Result.unwrapOr expects exactly 1 argument".into())
                } else {
                    Ok(match payload {
                        RuntimeResultPayload::Ok(value) => value,
                        RuntimeResultPayload::Err(_) => arg_values[0].clone(),
                    })
                }
            }
            "errorOf" => {
                if !arg_values.is_empty() {
                    Err("Result.errorOf expects 0 arguments".into())
                } else {
                    match payload {
                        RuntimeResultPayload::Ok(_) => Err(
                            "RuntimeResultExpectedError: attempted to extract an error from ok result"
                                .into(),
                        ),
                        RuntimeResultPayload::Err(err) => Ok(err),
                    }
                }
            }
            _ => return None,
        });
    }

    None
}

