fn build_backend_atomic_host_smoke_plan_manifest() -> serde_json::Value {
    let rows = backend_atomic_host_smoke_rows()
        .into_iter()
        .map(|row| {
            serde_json::json!({
                "row_id": backend_atomic_host_smoke_row_id(&row),
                "target": row.target,
                "op": ncc_ir::render_backend_atomic_rmw_op(row.op),
                "width": ncc_ir::render_backend_scalar_mem_width_public(row.width),
                "ordering": ncc_ir::render_backend_atomic_ordering(row.ordering),
                "mnemonic": row.mnemonic,
                "bytes_hex": backend_host_smoke_bytes_hex(&row.bytes),
                "external_checks": ["assembler", "object_bytes", "objdump", "linker"]
            })
        })
        .collect::<Vec<_>>();
    serde_json::json!({
        "schema": "nc.backend.atomic.host_smoke.plan.v1",
        "status": "planned",
        "targets": ["x86_64-pc-windows-msvc", "aarch64"],
        "rows_total": rows.len(),
        "rows": rows,
        "artifact_dir": "target/tmp/backend-atomic-host-smoke"
    })
}

fn build_backend_atomic_host_smoke_report() -> serde_json::Value {
    let artifact_dir = PathBuf::from("target/tmp/backend-atomic-host-smoke");
    let mut setup_diagnostics = Vec::new();
    if let Err(err) = fs::create_dir_all(&artifact_dir) {
        setup_diagnostics.push(format!(
            "failed to create artifact dir '{}': {err}",
            artifact_dir.display()
        ));
    }

    let rows = backend_atomic_host_smoke_rows();
    let mut results = Vec::new();
    for (index, row) in rows.iter().enumerate() {
        results.push(run_backend_atomic_host_smoke_row(
            row,
            index,
            &artifact_dir,
            setup_diagnostics.is_empty(),
        ));
    }

    let rows_total = results.len();
    let rows_passed = results
        .iter()
        .filter(|row| row.get("status").and_then(|v| v.as_str()) == Some("passed"))
        .count();
    let rows_missing_environment = results
        .iter()
        .filter(|row| row.get("status").and_then(|v| v.as_str()) == Some("missing_environment"))
        .count();
    let rows_failed = rows_total
        .saturating_sub(rows_passed)
        .saturating_sub(rows_missing_environment);
    let status = if !setup_diagnostics.is_empty() || rows_failed > 0 {
        "failed"
    } else if rows_missing_environment > 0 {
        "missing_environment"
    } else {
        "passed"
    };

    serde_json::json!({
        "schema": "nc.backend.atomic.host_smoke.v1",
        "status": status,
        "scope": "external host smoke for Win64 and AArch64 atomic RMW matrix rows",
        "artifact_dir": artifact_dir.display().to_string(),
        "rows_total": rows_total,
        "rows_passed": rows_passed,
        "rows_failed": rows_failed,
        "rows_missing_environment": rows_missing_environment,
        "setup_diagnostics": setup_diagnostics,
        "toolchains": backend_atomic_host_smoke_toolchain_manifest(),
        "plan": build_backend_atomic_host_smoke_plan_manifest(),
        "rows": results
    })
}

