fn backend_atomic_host_smoke_rows() -> Vec<ncc_ir::BackendAtomicRmwEncodingIR> {
    ncc_ir::backend_atomic_rmw_win64_matrix()
        .into_iter()
        .chain(ncc_ir::backend_atomic_rmw_aarch64_matrix())
        .collect()
}

fn backend_simd_host_smoke_rows() -> Vec<ncc_ir::BackendSimdInstructionEncodingIR> {
    ncc_ir::backend_simd_instruction_selection_matrix()
}

