fn ncup_managed_bin_file_name_for_platform(bin_name: &str, windows: bool) -> String {
    if windows {
        format!("{bin_name}.exe")
    } else {
        bin_name.to_string()
    }
}

fn ncup_managed_bin_file_name(bin_name: &str) -> String {
    ncup_managed_bin_file_name_for_platform(bin_name, cfg!(windows))
}

fn ncup_managed_bin_path(bin_dir: &Path, bin_name: &str) -> PathBuf {
    bin_dir.join(ncup_managed_bin_file_name(bin_name))
}

#[cfg(test)]
mod ncup_platform_bin_name_tests {
    use super::ncup_managed_bin_file_name_for_platform;

    #[test]
    fn managed_toolchain_paths_use_native_executable_names() {
        assert_eq!(ncup_managed_bin_file_name_for_platform("ncc", false), "ncc");
        assert_eq!(
            ncup_managed_bin_file_name_for_platform("ncc", true),
            "ncc.exe"
        );
    }
}

