fn build_phase10_mode_policy_manifest() -> serde_json::Value {
    serde_json::json!({
        "schema": "nc.ecosystem.mode.policy.v3",
        "version": "2.0.0",
        "state": "frozen",
        "semantic_authority": "ncc (parser+sema+ir+backend)",
        "extension_role": "ecosystem-classification-not-semantic-authority",
        "mode_rules": [
            {
                "mode_family": "root-basal",
                "contexts": ["@"],
                "official_extension": ".nb",
                "required_lane": "sovereign-core",
                "required_validation_backend": "nC.sovereign",
                "editorial_profile_min": "expert",
                "recommended_ides": ["goland", "clion", "ghidra", "vscode"]
            },
            {
                "mode_family": "machine-low-level",
                "contexts": ["@machine"],
                "official_extension": ".nm",
                "required_lane": "machine-core",
                "required_validation_backend": "nC.sovereign",
                "editorial_profile_min": "expert",
                "recommended_ides": ["goland", "clion", "ghidra", "vscode"]
            },
            {
                "mode_family": "primitive-low-level",
                "contexts": ["@primitive"],
                "official_extension": ".ncp",
                "required_lane": "primitive-core",
                "required_validation_backend": "nC.sovereign",
                "editorial_profile_min": "expert",
                "recommended_ides": ["goland", "clion", "ghidra", "vscode"]
            },
            {
                "mode_family": "rust-core-modes",
                "contexts": ["@kernel", "@inspect", "@compiler"],
                "official_extension": ".n",
                "required_lane": "rust-core",
                "required_validation_backend": "nC.sysv64|nC.win64|nC.aapcs64",
                "editorial_profile_min": "standard",
                "recommended_ides": ["rustrover", "vscode", "intellij"]
            },
            {
                "mode_family": "high-level",
                "contexts": ["@system", "@network", "@tooling", "@runtime", "@security", "@ai", "none"],
                "official_extension": ".n",
                "required_lane": "hl-core",
                "required_validation_backend": "nC.sysv64|nC.win64|nC.aapcs64|nC.portable",
                "editorial_profile_min": "novice",
                "recommended_ides": ["intellij", "vscode", "rustrover"]
            }
        ],
        "conflict_policy": "mixed mode families in a single source file are rejected",
        "enforcement_policy": {
            "semantic_truth": "compiler",
            "mixed_mode_family_same_file": "error",
            "extension_mismatch": "error_with_controlled_low_level_migration",
            "ide_mismatch": "advisory"
        },
        "migration_policy": {
            "id": "f10-p1-extension-migration",
            "legacy_source_extension": ".n",
            "low_level_targets": {
                "root-basal": ".nb",
                "machine-low-level": ".nm",
                "primitive-low-level": ".ncp"
            },
            "stages": [
                {
                    "name": "warning-first",
                    "description": "all legacy .n low-level files emit warning; no hard error"
                },
                {
                    "name": "error-by-profile",
                    "description": "legacy .n low-level files are warning for novice and error for standard/expert"
                },
                {
                    "name": "strict",
                    "description": "legacy .n low-level files are hard error for all profiles"
                }
            ],
            "default_stage": "warning-first"
        },
        "goal": "separate novice and expert flows with deterministic lane+profile constraints while keeping compiler semantic authority"
    })
}

