fn default_phase10_toolchain_id() -> String {
    let model = build_toolchain_model_manifest();
    let rows = model
        .get("toolchains")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();
    for row in &rows {
        if let Some(id) = row.get("id").and_then(|v| v.as_str()) {
            if id.starts_with("stable-") {
                return id.to_string();
            }
        }
    }
    rows.first()
        .and_then(|row| row.get("id"))
        .and_then(|v| v.as_str())
        .unwrap_or("stable-x86_64-unknown-linux-gnu")
        .to_string()
}

