fn emit_backend_object_ir_from_ast_with_profile(
    ast: &ncc_ast::Program,
    profile: ncc_ir::BackendLoweringProfileIR,
) -> Result<ncc_ir::BackendObjectIR, Box<dyn std::error::Error>> {
    let ir = lower_ir_with_backend_profile_and_contract_gate(ast, &profile)?;
    let backend = ncc_ir::emit_backend(&ir);
    Ok(ncc_ir::emit_object(&backend))
}

fn emit_backend_object_bytes_for_format(
    object: &ncc_ir::BackendObjectIR,
) -> Result<Vec<u8>, String> {
    match object.target_spec.object_format {
        ncc_ir::BackendObjectFormatIR::Elf32 => {
            Err("hosted native object emission routes ELF32 profiles through machine/clang materialization".into())
        }
        ncc_ir::BackendObjectFormatIR::Elf64 => ncc_ir::emit_object_elf64(object),
        ncc_ir::BackendObjectFormatIR::Coff => ncc_ir::emit_object_coff(object),
        ncc_ir::BackendObjectFormatIR::MachO => ncc_ir::emit_object_macho64(object),
        ncc_ir::BackendObjectFormatIR::WasmModule => {
            Err("hosted native object emission does not accept wasm modules".into())
        }
        ncc_ir::BackendObjectFormatIR::FreestandingImage => {
            Err("hosted native object emission does not accept freestanding images".into())
        }
    }
}

struct OptimizedBackendArtifact {
    object: ncc_ir::BackendObjectIR,
    ast_report: ncc_ir::OptimizationReportIR,
    backend_report: ncc_ir::OptimizationReportIR,
}

fn emit_optimized_backend_object_ir_from_ast_with_profile(
    ast: &ncc_ast::Program,
    profile: ncc_ir::BackendLoweringProfileIR,
) -> Result<OptimizedBackendArtifact, Box<dyn std::error::Error>> {
    run_sema_and_backend_lane_gate(ast, &profile)?;
    let (ir, ast_report) = ncc_ir::lower_optimized_with_backend_profile(ast.clone(), profile);
    ncc_ir::verify_type_contract_lowering(ast, &ir)
        .map_err(|err| format!("E_TYPE_CONTRACT_LOWERING_001: {err}"))?;
    let (backend, backend_report) = ncc_ir::emit_optimized_backend(&ir);
    ncc_ir::verify_type_contract_backend_enforcement(&ir, &backend)
        .map_err(|err| format!("E_TYPE_CONTRACT_BACKEND_001: {err}"))?;
    Ok(OptimizedBackendArtifact {
        object: ncc_ir::emit_object(&backend),
        ast_report,
        backend_report,
    })
}

fn emit_wasm_from_ast_with_profile(
    ast: &ncc_ast::Program,
    profile: ncc_ir::BackendLoweringProfileIR,
) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let ir = lower_ir_with_backend_profile_and_contract_gate(ast, &profile)?;
    let backend = ncc_ir::emit_backend(&ir);
    ncc_ir::emit_module_wasm32(&backend).map_err(Into::into)
}

fn emit_sovereign_from_ast_with_profile(
    ast: &ncc_ast::Program,
    profile: ncc_ir::BackendLoweringProfileIR,
) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let ir = lower_ir_with_backend_profile_and_contract_gate(ast, &profile)?;
    let backend = ncc_ir::emit_backend(&ir);
    let object = ncc_ir::emit_object(&backend);
    ncc_ir::emit_image_sovereign(&object).map_err(Into::into)
}

fn build_sovereign_from_ast_with_profile(
    ast: &ncc_ast::Program,
    profile: ncc_ir::BackendLoweringProfileIR,
    entry_symbol: Option<&str>,
) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let ir = lower_ir_with_backend_profile_and_contract_gate(ast, &profile)?;
    let backend = ncc_ir::emit_backend(&ir);
    let object = ncc_ir::emit_object(&backend);
    ncc_ir::link_image_sovereign(&object, entry_symbol).map_err(Into::into)
}

