fn workspace_repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap_or_else(|_| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../.."))
}

#[cfg(test)]
fn repo_compat_path(rel: &str) -> PathBuf {
    let root = workspace_repo_root();
    let direct = root.join(rel);
    if direct.exists() {
        return direct;
    }

    let normalized = rel.replace('\\', "/");
    if let Some(example_rel) = normalized.strip_prefix("examples/") {
        let archived = root.join("_archive").join("old_examples").join(example_rel);
        if archived.exists() {
            return archived;
        }

        let public_fixture = root
            .join("tests")
            .join("fixtures")
            .join("old_examples")
            .join(example_rel);
        if public_fixture.exists() {
            return public_fixture;
        }
    }

    direct
}

#[cfg(test)]
fn example_compat_path(rel: &str) -> PathBuf {
    repo_compat_path(&format!("examples/{rel}"))
}

#[cfg(all(test, not(ncc_public_beta)))]
fn target_debug_bin(name: &str) -> PathBuf {
    let file_name = if cfg!(windows) {
        format!("{name}.exe")
    } else {
        name.to_string()
    };
    workspace_repo_root()
        .join("target")
        .join("debug")
        .join(file_name)
}

