fn primitive_find_container(
    program: &ncc_ast::Program,
) -> Result<ncc_ast::PrimitiveAtContainer, Box<dyn std::error::Error>> {
    program
        .containers
        .iter()
        .find_map(|container| container.as_primitive_at())
        .ok_or_else(|| {
            "E_PRIMITIVE_TARGET_MATERIAL_001: source does not contain a primitive[@] container"
                .into()
        })
}

fn program_has_primitive_container(program: &ncc_ast::Program) -> bool {
    program
        .containers
        .iter()
        .any(|c| matches!(c.context, Some(ncc_ast::Context::Primitive)))
}

fn resolve_primitive_entry_link_symbol(
    program: &ncc_ast::Program,
    requested_entry: Option<&str>,
) -> Option<String> {
    let requested = requested_entry?;
    for container in &program.containers {
        let Some(primitive) = container.as_primitive_at() else {
            continue;
        };
        for section in &primitive.sections {
            if let ncc_ast::PrimitiveAtSection::Entry(entry) = section {
                let entry_name = entry.name.join(".");
                if entry_name == requested {
                    return Some(format!("{}.primitive", primitive.name));
                }
            }
        }
    }
    None
}

fn primitive_directive_word(atoms: &[ncc_ast::PrimitiveDirectiveAtom], idx: usize) -> Option<&str> {
    match atoms.get(idx) {
        Some(ncc_ast::PrimitiveDirectiveAtom::Word(value)) => Some(value.as_str()),
        _ => None,
    }
}

fn primitive_directive_number(
    atoms: &[ncc_ast::PrimitiveDirectiveAtom],
    idx: usize,
) -> Option<&str> {
    match atoms.get(idx) {
        Some(ncc_ast::PrimitiveDirectiveAtom::Number(value)) => Some(value.as_str()),
        _ => None,
    }
}

fn primitive_parse_u16_literal(raw: &str) -> Option<u16> {
    let normalized = raw.replace('_', "");
    if let Some(hex) = normalized
        .strip_prefix("0x")
        .or_else(|| normalized.strip_prefix("0X"))
    {
        u16::from_str_radix(hex, 16).ok()
    } else {
        normalized.parse::<u16>().ok()
    }
}

fn primitive_parse_u8_literal(raw: &str) -> Option<u8> {
    let normalized = raw.replace('_', "");
    if let Some(hex) = normalized
        .strip_prefix("0x")
        .or_else(|| normalized.strip_prefix("0X"))
    {
        u8::from_str_radix(hex, 16).ok()
    } else {
        normalized.parse::<u8>().ok()
    }
}

fn primitive_extract_addr_clause(item: &ncc_ast::PrimitiveDirectiveItem) -> Option<u16> {
    let atoms = item.atoms.as_slice();
    if primitive_directive_word(atoms, 0) != Some("addr") {
        return None;
    }
    if primitive_directive_word(atoms, 1) != Some("ioaddr") {
        return None;
    }
    let number = primitive_directive_number(atoms, 3)?;
    primitive_parse_u16_literal(number)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PrimitiveWindowAddrKind {
    MmioHelper,
    Other,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct PrimitiveWindowAddrContract {
    addr: u32,
    kind: PrimitiveWindowAddrKind,
}

fn primitive_extract_window_addr_clause(
    item: &ncc_ast::PrimitiveDirectiveItem,
) -> Option<PrimitiveWindowAddrContract> {
    let atoms = item.atoms.as_slice();
    if primitive_directive_word(atoms, 0) != Some("addr") {
        return None;
    }
    if primitive_directive_word(atoms, 1) == Some("mmioaddr") {
        let Ok(Some((addr, next_idx))) = primitive_parse_address_ref(atoms, 1) else {
            return None;
        };
        if next_idx != atoms.len() {
            return None;
        }
        return Some(PrimitiveWindowAddrContract {
            addr,
            kind: PrimitiveWindowAddrKind::MmioHelper,
        });
    }
    let Ok(Some((addr, next_idx))) = primitive_parse_address_ref(atoms, 1) else {
        return None;
    };
    if next_idx != atoms.len() {
        return None;
    }
    Some(PrimitiveWindowAddrContract {
        addr,
        kind: PrimitiveWindowAddrKind::Other,
    })
}

fn primitive_extract_dotted_path(
    atoms: &[ncc_ast::PrimitiveDirectiveAtom],
    mut idx: usize,
) -> Option<(Vec<String>, usize)> {
    let mut out = Vec::new();
    let first = primitive_directive_word(atoms, idx)?;
    out.push(first.to_string());
    idx += 1;

    while idx + 1 < atoms.len() {
        match (&atoms[idx], &atoms[idx + 1]) {
            (
                ncc_ast::PrimitiveDirectiveAtom::Punct(ncc_ast::PrimitiveDirectivePunct::Dot),
                ncc_ast::PrimitiveDirectiveAtom::Word(segment),
            ) => {
                out.push(segment.clone());
                idx += 2;
            }
            _ => break,
        }
    }

    Some((out, idx))
}

fn primitive_boot_entry_name(
    primitive: &ncc_ast::PrimitiveAtContainer,
    requested_entry: Option<&str>,
) -> Option<String> {
    if let Some(entry) = requested_entry {
        return Some(entry.to_string());
    }
    for section in &primitive.sections {
        if let ncc_ast::PrimitiveAtSection::Entry(entry) = section {
            if !entry.name.is_empty() {
                return Some(entry.name.join("."));
            }
        }
    }
    for section in &primitive.sections {
        if let ncc_ast::PrimitiveAtSection::Operation(operation) = section {
            if !operation.name.is_empty() {
                return Some(operation.name.join("."));
            }
        }
    }
    None
}

