#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum PrimitiveMaterialContractKind {
    Electrical,
    Timing,
    Power,
    Thermal,
    Interrupt,
    Dma,
    Cache,
    Tlb,
    Pipeline,
    FirmwareBoot,
    Controller,
    Peripheral,
    Phy,
    Lane,
    Channel,
    PhysicalFault,
}

impl PrimitiveMaterialContractKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Electrical => "electrical",
            Self::Timing => "timing",
            Self::Power => "power",
            Self::Thermal => "thermal",
            Self::Interrupt => "interrupt",
            Self::Dma => "dma",
            Self::Cache => "cache",
            Self::Tlb => "tlb",
            Self::Pipeline => "pipeline",
            Self::FirmwareBoot => "firmware_boot",
            Self::Controller => "controller",
            Self::Peripheral => "peripheral",
            Self::Phy => "phy",
            Self::Lane => "lane",
            Self::Channel => "channel",
            Self::PhysicalFault => "physical_fault",
        }
    }

    fn marker_byte(self) -> u8 {
        match self {
            Self::Electrical => 0x11,
            Self::Timing => 0x12,
            Self::Power => 0x13,
            Self::Thermal => 0x14,
            Self::Interrupt => 0x15,
            Self::Dma => 0x16,
            Self::Cache => 0x17,
            Self::Tlb => 0x18,
            Self::Pipeline => 0x19,
            Self::FirmwareBoot => 0x1A,
            Self::Controller => 0x1B,
            Self::Peripheral => 0x1C,
            Self::Phy => 0x1D,
            Self::Lane => 0x1E,
            Self::Channel => 0x1F,
            Self::PhysicalFault => 0x20,
        }
    }

    fn lowering_prefix_bytes(self) -> &'static [u8] {
        match self {
            Self::Electrical => &[0x90],        // nop
            Self::Timing => &[0x90],            // nop
            Self::Power => &[0x90],             // nop
            Self::Thermal => &[0xA8, 0x40],     // test al, 0x40
            Self::Interrupt => &[0x90],         // nop
            Self::Dma => &[0x0F, 0xAE, 0xF0],   // mfence
            Self::Cache => &[0x0F, 0xAE, 0xF0], // mfence
            Self::Tlb => &[0x90],               // nop
            Self::Pipeline => &[0x90],          // nop
            Self::FirmwareBoot => &[0x90],      // nop
            Self::Controller => &[0x90],        // nop
            Self::Peripheral => &[0x90],        // nop
            Self::Phy => &[0x90],               // nop
            Self::Lane => &[0x90],              // nop
            Self::Channel => &[0x90],           // nop
            Self::PhysicalFault => &[0x90],     // nop
        }
    }

    fn lowering_suffix_bytes(self) -> &'static [u8] {
        match self {
            Self::Electrical => &[0x24, 0x0F],    // and al, 0x0f
            Self::Timing => &[0xA8, 0x10],        // test al, 0x10
            Self::Power => &[0x0C, 0x40],         // or al, 0x40
            Self::Thermal => &[0x3C, 0x40],       // cmp al, 0x40
            Self::Interrupt => &[0xA8, 0x20],     // test al, 0x20
            Self::Dma => &[0x0C, 0x20],           // or al, 0x20
            Self::Cache => &[0xA8, 0x04],         // test al, 0x04
            Self::Tlb => &[0xA8, 0x08],           // test al, 0x08
            Self::Pipeline => &[0xA8, 0x02],      // test al, 0x02
            Self::FirmwareBoot => &[0x3C, 0x1A],  // cmp al, 0x1a
            Self::Controller => &[0x3C, 0x1B],    // cmp al, 0x1b
            Self::Peripheral => &[0x3C, 0x1C],    // cmp al, 0x1c
            Self::Phy => &[0x3C, 0x1D],           // cmp al, 0x1d
            Self::Lane => &[0x3C, 0x1E],          // cmp al, 0x1e
            Self::Channel => &[0x3C, 0x1F],       // cmp al, 0x1f
            Self::PhysicalFault => &[0x3C, 0x20], // cmp al, 0x20
        }
    }

    fn lowering_semantics(self) -> &'static [&'static str] {
        match self {
            Self::Electrical => &[
                "electrical_sampling_contract",
                "noise_voltage_current_surface_checked",
            ],
            Self::Timing => &[
                "timing_contract_probe",
                "clock_edge_watchdog_surface_checked",
            ],
            Self::Power => &["power_state_probe", "power_gate_transition_surface_checked"],
            Self::Thermal => &["thermal_state_probe", "thermal_throttle_surface_checked"],
            Self::Interrupt => &["interrupt_contract_probe", "interrupt_visibility_checked"],
            Self::Dma => &["dma_contract_probe", "dma_coherence_surface_checked"],
            Self::Cache => &["cache_contract_probe", "cache_coherence_surface_checked"],
            Self::Tlb => &["tlb_contract_probe", "translation_surface_checked"],
            Self::Pipeline => &["pipeline_contract_probe", "microarchitectural_flow_checked"],
            Self::FirmwareBoot => &["firmware_boot_probe", "boot_handoff_surface_checked"],
            Self::Controller => &["controller_contract_probe", "controller_surface_checked"],
            Self::Peripheral => &["peripheral_contract_probe", "peripheral_surface_checked"],
            Self::Phy => &["phy_contract_probe", "link_physical_surface_checked"],
            Self::Lane => &["lane_contract_probe", "lane_signal_surface_checked"],
            Self::Channel => &["channel_contract_probe", "channel_flow_surface_checked"],
            Self::PhysicalFault => &["physical_fault_probe", "rupture_path_surface_checked"],
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PrimitiveEventContractKind {
    Interrupt,
    DmaCompletion,
    WatchdogTrip,
    MmioReadClearsFlag,
    PeripheralStateChange,
    PhysicalFault,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PrimitiveEventContractConstruct {
    Legacy,
    Physical,
    AsyncHardware,
}

impl PrimitiveEventContractConstruct {
    fn as_str(self) -> &'static str {
        match self {
            Self::Legacy => "legacyEvent",
            Self::Physical => "physicalEvent",
            Self::AsyncHardware => "asyncHardwareEvent",
        }
    }

    fn is_nominal(self) -> bool {
        !matches!(self, Self::Legacy)
    }

    fn is_async_nominal(self) -> bool {
        matches!(self, Self::AsyncHardware)
    }
}

impl PrimitiveEventContractKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Interrupt => "interrupt",
            Self::DmaCompletion => "dmaCompletion",
            Self::WatchdogTrip => "watchdogTrip",
            Self::MmioReadClearsFlag => "mmioReadClearsFlag",
            Self::PeripheralStateChange => "peripheralStateChange",
            Self::PhysicalFault => "physicalFault",
        }
    }

    fn material_entity(self) -> &'static str {
        match self {
            Self::Interrupt => "interruptLine",
            Self::DmaCompletion => "dmaChannel",
            Self::WatchdogTrip => "watchdog",
            Self::MmioReadClearsFlag => "mmioWindow",
            Self::PeripheralStateChange => "peripheral",
            Self::PhysicalFault => "physicalFault",
        }
    }

    fn async_hardware_event(self) -> bool {
        true
    }

    fn marker_byte(self) -> u8 {
        match self {
            Self::Interrupt => 0xE1,
            Self::DmaCompletion => 0xE2,
            Self::WatchdogTrip => 0xE3,
            Self::MmioReadClearsFlag => 0xE4,
            Self::PeripheralStateChange => 0xE5,
            Self::PhysicalFault => 0xE6,
        }
    }

    fn lowering_prefix_bytes(self) -> &'static [u8] {
        match self {
            Self::Interrupt => &[0x90],                 // nop
            Self::DmaCompletion => &[0x0F, 0xAE, 0xF0], // mfence
            Self::WatchdogTrip => &[0x90],              // nop
            Self::MmioReadClearsFlag => &[0xA8, 0x01],  // test al, 0x01
            Self::PeripheralStateChange => &[0x90],     // nop
            Self::PhysicalFault => &[0x90],             // nop
        }
    }

    fn lowering_suffix_bytes(self) -> &'static [u8] {
        match self {
            Self::Interrupt => &[0xA8, 0x10],             // test al, 0x10
            Self::DmaCompletion => &[0x0C, 0x20],         // or al, 0x20
            Self::WatchdogTrip => &[0x3C, 0xE3],          // cmp al, 0xe3
            Self::MmioReadClearsFlag => &[0x24, 0x01],    // and al, 0x01
            Self::PeripheralStateChange => &[0x0C, 0x08], // or al, 0x08
            Self::PhysicalFault => &[0x3C, 0xE6],         // cmp al, 0xe6
        }
    }

    fn lowering_semantics(self) -> &'static [&'static str] {
        match self {
            Self::Interrupt => &["interrupt_pending_edge", "async_preemption_contract"],
            Self::DmaCompletion => &["dma_visibility_commit", "coherence_boundary_commit"],
            Self::WatchdogTrip => &["watchdog_timeout_edge", "fault_escalation_contract"],
            Self::MmioReadClearsFlag => &["mmio_read_flag_clear", "stateful_read_side_effect"],
            Self::PeripheralStateChange => &[
                "peripheral_state_transition",
                "async_device_state_observable_change",
            ],
            Self::PhysicalFault => &["physical_fault_edge", "rupture_path_mandatory"],
        }
    }
}

#[derive(Clone, Debug)]
struct PrimitiveEventContract {
    construct: PrimitiveEventContractConstruct,
    kind: PrimitiveEventContractKind,
    subject_path: Vec<String>,
}

#[derive(Clone, Copy)]
struct PrimitiveEventOpView<'a> {
    construct: PrimitiveEventContractConstruct,
    kind: PrimitiveEventContractKind,
    subject: &'a str,
}

fn primitive_event_op_view(op: &PrimitiveMaterialOp) -> Option<PrimitiveEventOpView<'_>> {
    match op {
        PrimitiveMaterialOp::LegacyEventContract { kind, subject } => Some(PrimitiveEventOpView {
            construct: PrimitiveEventContractConstruct::Legacy,
            kind: *kind,
            subject,
        }),
        PrimitiveMaterialOp::PhysicalEventContract { kind, subject } => {
            Some(PrimitiveEventOpView {
                construct: PrimitiveEventContractConstruct::Physical,
                kind: *kind,
                subject,
            })
        }
        PrimitiveMaterialOp::AsyncHardwareEventContract { kind, subject } => {
            Some(PrimitiveEventOpView {
                construct: PrimitiveEventContractConstruct::AsyncHardware,
                kind: *kind,
                subject,
            })
        }
        _ => None,
    }
}

fn primitive_event_contracts_to_json(
    events: &[PrimitiveEventContract],
    side_effect_contracts: &[String],
) -> Vec<serde_json::Value> {
    crate::commands::primitive::primitive_event_contracts_to_json_impl(
        events,
        side_effect_contracts,
    )
}

fn primitive_parse_u32_literal(raw: &str) -> Option<u32> {
    let normalized = raw.replace('_', "");
    if let Some(hex) = normalized
        .strip_prefix("0x")
        .or_else(|| normalized.strip_prefix("0X"))
    {
        u32::from_str_radix(hex, 16).ok()
    } else {
        normalized.parse::<u32>().ok()
    }
}

fn primitive_material_symbol_marker_byte(raw: &str) -> u8 {
    raw.bytes()
        .fold(0u8, |acc, b| acc.rotate_left(1).wrapping_add(b))
}

fn primitive_material_semantic_marker_byte(semantic: &str) -> u8 {
    semantic
        .bytes()
        .fold(0x5Au8, |acc, b| acc.rotate_right(1).wrapping_add(b))
}

fn primitive_material_semantic_phase(semantic: &str) -> &'static str {
    match semantic {
        "voltage" | "current" | "noise" | "metastability" => "electrical",
        "clock" | "edge" | "cycle" | "latency" | "timeout" | "watchdog" => "timing",
        "power" | "powerGate" => "power",
        "temperature" | "thermalState" | "throttleState" => "thermal",
        "interruptLine" => "interrupt",
        "dmaChannel" => "dma",
        "cacheState" => "cache",
        "tlbState" => "tlb",
        "pipelineState" | "branchPredictorState" | "reorderState" | "outOfOrder" => {
            "microarchitecture"
        }
        "firmwareRegion" | "bootRomRegion" | "biosRegion" | "uefiHandoff" | "resetVector"
        | "bootWindow" | "bootAnchor" | "firmwareTable" | "deviceTree" | "acpiTable"
        | "microcodeState" => "firmware_boot",
        "controller" => "controller",
        "peripheral" => "peripheral",
        "phy" => "phy",
        "lane" => "lane",
        "channel" => "channel",
        "physicalFault"
        | "busFault"
        | "signalLoss"
        | "timingViolation"
        | "thermalViolation"
        | "metastabilityRisk"
        | "dmaViolation"
        | "cacheCoherenceViolation"
        | "mmioSideEffectViolation" => "physical_fault",
        _ => "generic",
    }
}

