fn primitive_material_probe_semantic_prefix_bytes(semantic: &str) -> Option<&'static [u8]> {
    match semantic {
        "voltage" | "current" | "noise" | "metastability" => Some(&[0x90]), // nop
        "clock" | "edge" | "cycle" | "latency" | "timeout" | "watchdog" => Some(&[0x90]), // nop
        "power" => Some(&[0x90]),                                           // nop
        "temperature" => Some(&[0xA8, 0x40]),                               // test al, 0x40
        "interruptLine" => Some(&[0x90]),                                   // nop
        "dmaChannel" => Some(&[0x0F, 0xAE, 0xF0]),                          // mfence
        "controller" => Some(&[0x90]),                                      // nop
        "peripheral" => Some(&[0x90]),                                      // nop
        "phy" => Some(&[0x90]),                                             // nop
        "lane" => Some(&[0x90]),                                            // nop
        "channel" => Some(&[0x90]),                                         // nop
        "physicalFault"
        | "busFault"
        | "signalLoss"
        | "timingViolation"
        | "thermalViolation"
        | "metastabilityRisk"
        | "dmaViolation"
        | "cacheCoherenceViolation"
        | "mmioSideEffectViolation" => Some(&[0x90]), // nop
        "powerGate" => Some(&[0xE4, 0x61]),                                 // in al, 0x61
        "thermalState" => Some(&[0xE4, 0x62]),                              // in al, 0x62
        "throttleState" => Some(&[0xE4, 0x63]),                             // in al, 0x63
        "cacheState" => Some(&[0x0F, 0xAE, 0xF8]),                          // sfence
        "tlbState" => Some(&[0x0F, 0xAE, 0xE8]),                            // lfence-like probe
        "pipelineState" => Some(&[0x0F, 0xA2]),                             // cpuid serialize probe
        "branchPredictorState" => Some(&[0x9B, 0x90]),                      // wait+nop probe
        "reorderState" => Some(&[0xF3, 0x90]),                              // pause
        "outOfOrder" => Some(&[0xF2, 0x90]),                                // repne nop probe
        "firmwareRegion" => Some(&[0xF8]),                                  // clc
        "bootRomRegion" => Some(&[0xF9]),                                   // stc
        "biosRegion" => Some(&[0xFA]),                                      // cli
        "uefiHandoff" => Some(&[0xFB]),                                     // sti
        "resetVector" => Some(&[0x9C]),                                     // pushf
        "bootWindow" => Some(&[0x9D]),                                      // popf
        "bootAnchor" => Some(&[0x9E]),                                      // sahf
        "firmwareTable" => Some(&[0x9F]),                                   // lahf
        "deviceTree" => Some(&[0x27]),                                      // daa
        "acpiTable" => Some(&[0x2F]),                                       // das
        "microcodeState" => Some(&[0xF5]),                                  // cmc
        _ => None,
    }
}

fn primitive_material_probe_semantic_suffix_bytes(semantic: &str) -> Option<&'static [u8]> {
    match semantic {
        "voltage" | "current" | "noise" | "metastability" => Some(&[0x24, 0x0F]), // and al, 0x0f
        "clock" | "edge" | "cycle" | "latency" | "timeout" | "watchdog" => Some(&[0xA8, 0x10]), // test al, 0x10
        "power" => Some(&[0x0C, 0x40]),         // or al, 0x40
        "temperature" => Some(&[0x3C, 0x40]),   // cmp al, 0x40
        "interruptLine" => Some(&[0xA8, 0x20]), // test al, 0x20
        "dmaChannel" => Some(&[0x0C, 0x20]),    // or al, 0x20
        "controller" => Some(&[0x3C, 0x1B]),    // cmp al, 0x1b
        "peripheral" => Some(&[0x3C, 0x1C]),    // cmp al, 0x1c
        "phy" => Some(&[0x3C, 0x1D]),           // cmp al, 0x1d
        "lane" => Some(&[0x3C, 0x1E]),          // cmp al, 0x1e
        "channel" => Some(&[0x3C, 0x1F]),       // cmp al, 0x1f
        "physicalFault"
        | "busFault"
        | "signalLoss"
        | "timingViolation"
        | "thermalViolation"
        | "metastabilityRisk"
        | "dmaViolation"
        | "cacheCoherenceViolation"
        | "mmioSideEffectViolation" => Some(&[0x3C, 0x20]), // cmp al, 0x20
        "powerGate" => Some(&[0x3C, 0x50]),     // cmp al, 0x50
        "thermalState" => Some(&[0x3C, 0x54]),  // cmp al, 0x54
        "throttleState" => Some(&[0x3C, 0x55]), // cmp al, 0x55
        "cacheState" => Some(&[0xA8, 0x4C]),    // test al, 0x4c
        "tlbState" => Some(&[0xA8, 0x4D]),      // test al, 0x4d
        "pipelineState" => Some(&[0x3C, 0x71]), // cmp al, 0x71
        "branchPredictorState" => Some(&[0x3C, 0x72]), // cmp al, 0x72
        "reorderState" => Some(&[0x3C, 0x73]),  // cmp al, 0x73
        "outOfOrder" => Some(&[0x3C, 0x74]),    // cmp al, 0x74
        "firmwareRegion" => Some(&[0x3C, 0x81]), // cmp al, 0x81
        "bootRomRegion" => Some(&[0x3C, 0x82]), // cmp al, 0x82
        "biosRegion" => Some(&[0x3C, 0x83]),    // cmp al, 0x83
        "uefiHandoff" => Some(&[0x3C, 0x84]),   // cmp al, 0x84
        "resetVector" => Some(&[0x3C, 0x85]),   // cmp al, 0x85
        "bootWindow" => Some(&[0x3C, 0x86]),    // cmp al, 0x86
        "bootAnchor" => Some(&[0x3C, 0x87]),    // cmp al, 0x87
        "firmwareTable" => Some(&[0x3C, 0x88]), // cmp al, 0x88
        "deviceTree" => Some(&[0x3C, 0x89]),    // cmp al, 0x89
        "acpiTable" => Some(&[0x3C, 0x8A]),     // cmp al, 0x8a
        "microcodeState" => Some(&[0x3C, 0x8B]), // cmp al, 0x8b
        _ => None,
    }
}

