fn primitive_material_probe_kind_for_semantic(
    semantic: &str,
) -> Option<PrimitiveMaterialContractKind> {
    match semantic {
        "voltage" | "current" | "noise" | "metastability" => {
            Some(PrimitiveMaterialContractKind::Electrical)
        }
        "clock" | "edge" | "cycle" | "latency" | "timeout" | "watchdog" => {
            Some(PrimitiveMaterialContractKind::Timing)
        }
        "power" | "powerGate" => Some(PrimitiveMaterialContractKind::Power),
        "temperature" | "thermalState" | "throttleState" => {
            Some(PrimitiveMaterialContractKind::Thermal)
        }
        "interruptLine" => Some(PrimitiveMaterialContractKind::Interrupt),
        "dmaChannel" => Some(PrimitiveMaterialContractKind::Dma),
        "cacheState" => Some(PrimitiveMaterialContractKind::Cache),
        "tlbState" => Some(PrimitiveMaterialContractKind::Tlb),
        "pipelineState" | "branchPredictorState" | "reorderState" | "outOfOrder" => {
            Some(PrimitiveMaterialContractKind::Pipeline)
        }
        "firmwareRegion" | "bootRomRegion" | "biosRegion" | "uefiHandoff" | "resetVector"
        | "bootWindow" | "bootAnchor" | "firmwareTable" | "deviceTree" | "acpiTable"
        | "microcodeState" => Some(PrimitiveMaterialContractKind::FirmwareBoot),
        "controller" => Some(PrimitiveMaterialContractKind::Controller),
        "peripheral" => Some(PrimitiveMaterialContractKind::Peripheral),
        "phy" => Some(PrimitiveMaterialContractKind::Phy),
        "lane" => Some(PrimitiveMaterialContractKind::Lane),
        "channel" => Some(PrimitiveMaterialContractKind::Channel),
        "physicalFault"
        | "busFault"
        | "signalLoss"
        | "timingViolation"
        | "thermalViolation"
        | "metastabilityRisk"
        | "dmaViolation"
        | "cacheCoherenceViolation"
        | "mmioSideEffectViolation" => Some(PrimitiveMaterialContractKind::PhysicalFault),
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PrimitiveMaterialProbeProfile {
    PowerThermal,
    Microarchitecture,
    FirmwareBoot,
    FamilyFallback,
}

impl PrimitiveMaterialProbeProfile {
    fn profile_key(self) -> &'static str {
        match self {
            Self::PowerThermal => "power_thermal",
            Self::Microarchitecture => "microarchitecture",
            Self::FirmwareBoot => "firmware_boot",
            Self::FamilyFallback => "family_fallback",
        }
    }
}

fn primitive_material_probe_profile_for_semantic(semantic: &str) -> PrimitiveMaterialProbeProfile {
    match semantic {
        "powerGate" | "thermalState" | "throttleState" => {
            PrimitiveMaterialProbeProfile::PowerThermal
        }
        "cacheState"
        | "tlbState"
        | "pipelineState"
        | "branchPredictorState"
        | "reorderState"
        | "outOfOrder" => PrimitiveMaterialProbeProfile::Microarchitecture,
        "firmwareRegion" | "bootRomRegion" | "biosRegion" | "uefiHandoff" | "resetVector"
        | "bootWindow" | "bootAnchor" | "firmwareTable" | "deviceTree" | "acpiTable"
        | "microcodeState" => PrimitiveMaterialProbeProfile::FirmwareBoot,
        _ => PrimitiveMaterialProbeProfile::FamilyFallback,
    }
}

fn primitive_material_probe_profile_from_op(
    op: &PrimitiveMaterialOp,
) -> Option<PrimitiveMaterialProbeProfile> {
    let (_, semantic, _) = primitive_material_entity_hook_payload(op)?;
    Some(primitive_material_probe_profile_for_semantic(semantic))
}

fn primitive_material_entity_hook_payload(
    op: &PrimitiveMaterialOp,
) -> Option<(PrimitiveMaterialContractKind, &str, &str)> {
    match op {
        PrimitiveMaterialOp::MaterialEntityContractHook {
            kind,
            semantic,
            symbol,
        } => Some((*kind, semantic.as_str(), symbol.as_str())),
        _ => None,
    }
}

fn primitive_validate_material_entity_hook_lowering_invariants(
    hook_ops: &[PrimitiveMaterialOp],
    entry_name: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    for op in hook_ops {
        let Some((kind, semantic, symbol)) = primitive_material_entity_hook_payload(op) else {
            continue;
        };
        let Some(expected_kind) = primitive_material_probe_kind_for_semantic(semantic) else {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' for '{}' is unknown to lowering map",
                entry_name, semantic, symbol
            )
            .into());
        };
        if expected_kind != kind {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' for '{}' was tagged as '{}' but requires '{}'",
                entry_name,
                semantic,
                symbol,
                kind.as_str(),
                expected_kind.as_str()
            )
            .into());
        }
        let Some(prefix) = primitive_material_probe_semantic_prefix_bytes(semantic) else {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' requires explicit semantic prefix lowering bytes",
                entry_name, semantic
            )
            .into());
        };
        let Some(suffix) = primitive_material_probe_semantic_suffix_bytes(semantic) else {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' requires explicit semantic suffix lowering bytes",
                entry_name, semantic
            )
            .into());
        };
        if prefix.is_empty() || suffix.is_empty() {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' must expose non-empty lowering bytes",
                entry_name, semantic
            )
            .into());
        }
        let mode = primitive_material_probe_semantic_lowering_mode(semantic);
        if !mode.starts_with("entity_opcode_plan_") {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' requires entity opcode lowering mode, got '{}'",
                entry_name, semantic, mode
            )
            .into());
        }
        let cap = primitive_material_probe_semantic_required_capability(semantic);
        let diag = primitive_material_probe_semantic_unsupported_diag(semantic);
        if cap.is_some() != diag.is_some() {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' must keep capability/diag mapping in sync",
                entry_name, semantic
            )
            .into());
        }
        if primitive_material_semantic_phase(semantic) == "generic" {
            return Err(format!(
                "E_PRIMITIVE_LOWERING_UNAVAILABLE_001: operation '{}' material entity hook '{}' must map to a concrete semantic phase",
                entry_name, semantic
            )
            .into());
        }
    }
    Ok(())
}

fn primitive_bytes_to_hex(bytes: &[u8]) -> String {
    crate::commands::primitive::primitive_bytes_to_hex_impl(bytes)
}

fn primitive_material_probe_kind_for_directive(
    kind: ncc_ast::PrimitiveDirectiveKind,
) -> Option<PrimitiveMaterialContractKind> {
    use ncc_ast::PrimitiveDirectiveKind as K;
    match kind {
        K::Voltage | K::Current | K::Noise | K::Metastability => {
            Some(PrimitiveMaterialContractKind::Electrical)
        }
        K::Clock | K::Cycle | K::Latency | K::Timeout | K::Watchdog | K::Edge => {
            Some(PrimitiveMaterialContractKind::Timing)
        }
        K::Power | K::PowerGate => Some(PrimitiveMaterialContractKind::Power),
        K::Temperature | K::ThermalState | K::ThrottleState => {
            Some(PrimitiveMaterialContractKind::Thermal)
        }
        K::InterruptLine => Some(PrimitiveMaterialContractKind::Interrupt),
        K::DmaChannel => Some(PrimitiveMaterialContractKind::Dma),
        K::CacheState => Some(PrimitiveMaterialContractKind::Cache),
        K::CacheCoherenceViolation => Some(PrimitiveMaterialContractKind::PhysicalFault),
        K::TlbState => Some(PrimitiveMaterialContractKind::Tlb),
        K::PipelineState | K::BranchPredictorState | K::ReorderState | K::OutOfOrder => {
            Some(PrimitiveMaterialContractKind::Pipeline)
        }
        K::FirmwareRegion
        | K::BootRomRegion
        | K::BiosRegion
        | K::UefiHandoff
        | K::ResetVector
        | K::BootWindow
        | K::BootAnchor
        | K::FirmwareTable
        | K::DeviceTree
        | K::AcpiTable
        | K::MicrocodeState => Some(PrimitiveMaterialContractKind::FirmwareBoot),
        K::Controller => Some(PrimitiveMaterialContractKind::Controller),
        K::Peripheral => Some(PrimitiveMaterialContractKind::Peripheral),
        K::Phy => Some(PrimitiveMaterialContractKind::Phy),
        K::Lane => Some(PrimitiveMaterialContractKind::Lane),
        K::Channel => Some(PrimitiveMaterialContractKind::Channel),
        K::PhysicalFault
        | K::BusFault
        | K::SignalLoss
        | K::TimingViolation
        | K::ThermalViolation
        | K::MetastabilityRisk
        | K::DmaViolation
        | K::MmioSideEffectViolation => Some(PrimitiveMaterialContractKind::PhysicalFault),
        _ => None,
    }
}

fn primitive_collect_material_entity_contract_hook_ops(
    primitive: &ncc_ast::PrimitiveAtContainer,
) -> Vec<PrimitiveMaterialOp> {
    let mut seen: std::collections::BTreeSet<(PrimitiveMaterialContractKind, String, String)> =
        std::collections::BTreeSet::new();
    for section in &primitive.sections {
        let ncc_ast::PrimitiveAtSection::Directive(directive) = section else {
            continue;
        };
        let Some(kind) = primitive_material_probe_kind_for_directive(directive.kind.clone()) else {
            continue;
        };
        let semantic = primitive_material_semantic_name(&directive.kind)
            .unwrap_or(kind.as_str())
            .to_string();
        for item in &directive.items {
            if let Some(symbol) = primitive_scalar_symbol_from_item(item) {
                seen.insert((kind, semantic.clone(), symbol));
            }
        }
    }
    seen.into_iter()
        .map(
            |(kind, semantic, symbol)| PrimitiveMaterialOp::MaterialEntityContractHook {
                kind,
                semantic,
                symbol,
            },
        )
        .collect()
}

