fn cli_usage() -> &'static str {
    CLI_USAGE
}

fn is_help_token(arg: &str) -> bool {
    matches!(arg, "-h" | "--help" | "help")
}

fn render_release_source_diagnostic(
    diag: &ncc_diagnostics::Diagnostic,
    phase: &str,
    path: &str,
    src: &str,
) -> CliFailure {
    CliFailure::one(diag.canonical(phase).with_file(path), src)
}

fn render_release_legacy_diagnostic(
    message: &str,
    phase: &str,
    path: &str,
    src: &str,
) -> CliFailure {
    CliFailure::one(
        ncc_diagnostics::CanonicalDiagnostic::from_legacy(message, phase, 0, 0).with_file(path),
        src,
    )
}

pub(crate) fn canonical_diagnostic_to_json(
    diagnostic: &ncc_diagnostics::CanonicalDiagnostic,
) -> serde_json::Value {
    let machine = diagnostic.machine_packet().ok();
    let machine_record_hex = machine
        .as_ref()
        .map(|packet| canonical_diagnostic_bytes_hex(&packet.record.encode_le()));
    let machine_arena_hex = machine
        .as_ref()
        .map(|packet| canonical_diagnostic_bytes_hex(&packet.arena));
    serde_json::json!({
        "transport": "nc.diagnostic.jsonl.v1",
        "abi": "nc.diagnostic.machine.v2",
        "abi_version": ncc_diagnostics::DIAGNOSTIC_ABI_VERSION,
        "record_bytes": ncc_diagnostics::DIAGNOSTIC_RECORD_BYTES,
        "stable_id": format!("{:016x}", diagnostic.stable_id()),
        "severity": diagnostic.severity.label(),
        "domain": diagnostic.domain as u8,
        "code": diagnostic.code,
        "phase": diagnostic.phase,
        "message": diagnostic.message,
        "expected": diagnostic.expected,
        "found": diagnostic.found,
        "help": diagnostic.help,
        "file": diagnostic.file,
        "line": diagnostic.span.line,
        "column": diagnostic.span.column,
        "end_line": diagnostic.span.end_line,
        "end_column": diagnostic.span.end_column,
        "flags": diagnostic.flags,
        "cause_index": diagnostic.cause_index,
        "cause_count": diagnostic.cause_count,
        "machine_record_hex": machine_record_hex,
        "machine_arena_hex": machine_arena_hex,
    })
}

pub(crate) fn canonical_diagnostics_to_jsonl(
    diagnostics: &[ncc_diagnostics::CanonicalDiagnostic],
) -> Result<String, serde_json::Error> {
    let mut output = String::new();
    for diagnostic in diagnostics {
        output.push_str(&serde_json::to_string(&canonical_diagnostic_to_json(
            diagnostic,
        ))?);
        output.push('\n');
    }
    Ok(output)
}

pub(crate) fn canonical_diagnostics_to_ndiag(
    diagnostics: &[ncc_diagnostics::CanonicalDiagnostic],
) -> Result<Vec<u8>, ncc_diagnostics::DiagnosticTransportError> {
    ncc_diagnostics::encode_ndiag(diagnostics)
}

pub(crate) fn render_canonical_diagnostic_terminal(
    diagnostic: &ncc_diagnostics::CanonicalDiagnostic,
    source: &str,
    color: bool,
) -> String {
    diagnostic.render_with_style(
        source,
        if color {
            ncc_diagnostics::DiagnosticRenderStyle::Ansi
        } else {
            ncc_diagnostics::DiagnosticRenderStyle::Plain
        },
    )
}

pub(crate) fn stderr_diagnostic_color_enabled() -> bool {
    if env::var_os("NO_COLOR").is_some() {
        return false;
    }
    if env::var("NC_NO_COLOR").ok().is_some_and(|value| {
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    }) {
        return false;
    }
    if env::var("CLICOLOR_FORCE")
        .ok()
        .is_some_and(|value| value.trim() != "0" && !value.trim().is_empty())
    {
        return true;
    }
    io::stderr().is_terminal()
}

fn canonical_diagnostic_bytes_hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        use std::fmt::Write;
        let _ = write!(out, "{byte:02x}");
    }
    out
}

fn source_has_import_surface(src: &str) -> bool {
    src.lines().any(|line| {
        let trimmed = line.trim_start();
        trimmed.starts_with("use::")
            || trimmed.starts_with("use nC.")
            || trimmed.starts_with("use runtime.")
            || trimmed.starts_with("use machine.")
            || trimmed.starts_with("use Machine.")
            || trimmed.starts_with("use primitive.")
            || trimmed.starts_with("use basal.")
            || trimmed.starts_with("use kernel.")
    })
}

fn source_has_auth_surface(src: &str) -> bool {
    src.lines()
        .any(|line| line.trim_start().starts_with("use::auth::"))
}

fn source_has_auth_policy(src: &str) -> bool {
    src.lines().any(|line| {
        let trimmed = line.trim_start();
        trimmed.starts_with("risk:")
            || trimmed.starts_with("policy:")
            || trimmed.starts_with("authority:")
    })
}

fn validate_import_surface_source_gates(
    path: &str,
    src: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    if source_has_auth_surface(src) && !source_has_auth_policy(src) {
        return Err(
            "E_USE_AUTH_POLICY_REQUIRED_001: use::auth imports require explicit risk:/policy:/authority: declaration"
                .into(),
        );
    }

    let ext = Path::new(path)
        .extension()
        .and_then(|ext| ext.to_str())
        .unwrap_or("")
        .to_ascii_lowercase();
    if !source_has_import_surface(src) {
        return Ok(());
    }

    match ext.as_str() {
        "nm" => Err(
            "E_USE_FORBIDDEN_IN_MACHINE_001: Este modo no usa imports. Declare capacidades/secciones mediante la gramatica propia del modo."
                .into(),
        ),
        "ncp" => Err(
            "E_USE_FORBIDDEN_IN_PRIMITIVE_001: Este modo no usa imports. Declare capacidades/secciones mediante la gramatica propia del modo."
                .into(),
        ),
        "nb" | "nbb" => Err(
            "E_USE_FORBIDDEN_IN_BASAL_001: Este modo no usa imports. Declare capacidades/secciones mediante la gramatica propia del modo."
                .into(),
        ),
        _ => Ok(()),
    }
}

