fn import_manifest_payload(domain: Option<ncc_ast::UseDomain>) -> serde_json::Value {
    match domain {
        Some(domain) => serde_json::to_value(ncc_ast::use_import_manifest_for_domain(domain))
            .unwrap_or_else(|_| serde_json::json!({"status": "serialization_error"})),
        None => serde_json::to_value(ncc_ast::use_import_manifest_all())
            .unwrap_or_else(|_| serde_json::json!({"status": "serialization_error"})),
    }
}

fn imports_backend_payload(
    path: Option<&str>,
) -> Result<serde_json::Value, Box<dyn std::error::Error>> {
    let manifest = if let Some(path) = path {
        let src = fs::read_to_string(path)?;
        let tokens = ncc_lexer::lex(&src)?;
        let ast = ncc_parser::parse(tokens)?;
        let paths = ast
            .uses
            .iter()
            .filter(|use_decl| !use_decl.wildcard)
            .map(|use_decl| use_decl.path.join("."))
            .collect::<Vec<_>>();
        let manifest = ncc_ast::use_backend_lowering_manifest_for_paths(&paths);
        let mut payload = serde_json::to_value(manifest)?;
        payload["file"] = serde_json::json!(path);
        payload["source_import_paths"] = serde_json::json!(paths);
        payload
    } else {
        serde_json::to_value(ncc_ast::use_backend_lowering_manifest_all())?
    };
    Ok(manifest)
}

fn imports_runtime_table_payload(
    path: Option<&str>,
) -> Result<serde_json::Value, Box<dyn std::error::Error>> {
    let payload = if let Some(path) = path {
        let src = fs::read_to_string(path)?;
        let tokens = ncc_lexer::lex(&src)?;
        let ast = ncc_parser::parse(tokens)?;
        let paths = ast
            .uses
            .iter()
            .filter(|use_decl| !use_decl.wildcard)
            .map(|use_decl| use_decl.path.join("."))
            .collect::<Vec<_>>();
        let table = ncc_ast::runtime_import_closure_table_for_paths(&paths);
        let mut payload = serde_json::to_value(table)?;
        payload["file"] = serde_json::json!(path);
        payload["source_import_paths"] = serde_json::json!(paths);
        payload
    } else {
        serde_json::to_value(ncc_ast::runtime_import_closure_table_all())?
    };
    Ok(payload)
}

fn imports_closure_priority(domain: ncc_ast::UseDomain, family: &str) -> u8 {
    match (domain, family.to_ascii_lowercase().as_str()) {
        (ncc_ast::UseDomain::Core | ncc_ast::UseDomain::Alloc, _) => 0,
        (ncc_ast::UseDomain::Stoud, "io" | "memory" | "time" | "terminal" | "fs") => 1,
        (ncc_ast::UseDomain::Stoud, "collections" | "data" | "text" | "math") => 2,
        (ncc_ast::UseDomain::Stoud, "net" | "network" | "process" | "thread" | "sync" | "task") => {
            3
        }
        (ncc_ast::UseDomain::Stoud, _) => 4,
        (ncc_ast::UseDomain::Auth, _) => 5,
        (ncc_ast::UseDomain::Dom, _) => 6,
        (ncc_ast::UseDomain::LegacyBaseical, _) => 7,
    }
}

fn imports_closure_plan_payload() -> serde_json::Value {
    let table = ncc_ast::runtime_import_closure_table_all();
    let mut pending = table
        .entries
        .iter()
        .filter(|entry| entry.closure_status == "catalog_only_with_diagnostic")
        .collect::<Vec<_>>();
    pending.sort_by(|left, right| {
        imports_closure_priority(left.domain, &left.family)
            .cmp(&imports_closure_priority(right.domain, &right.family))
            .then_with(|| left.family.cmp(&right.family))
            .then_with(|| left.item.cmp(&right.item))
            .then_with(|| left.surface_import.cmp(&right.surface_import))
    });
    let queue = pending
        .iter()
        .enumerate()
        .map(|(index, entry)| {
            serde_json::json!({
                "sequence": index + 1,
                "priority": imports_closure_priority(entry.domain, &entry.family),
                "domain": entry.domain,
                "family": entry.family,
                "item": entry.item,
                "surface_import": entry.surface_import,
                "backend_symbol": entry.backend_symbol,
                "required_evidence": [
                    "catalog_signature_and_sema",
                    "native_runtime_or_compiler_intrinsic",
                    "llvm_abi_declaration_and_call",
                    "mct_or_machine_materialization",
                    "object_link_and_host_execution",
                    "negative_diagnostic_and_regression_test"
                ]
            })
        })
        .collect::<Vec<_>>();
    let mut family_groups = BTreeMap::<(u8, String, String), Vec<(usize, &str, &str, &str)>>::new();
    for (index, entry) in pending.iter().enumerate() {
        let priority = imports_closure_priority(entry.domain, &entry.family);
        family_groups
            .entry((
                priority,
                format!("{:?}", entry.domain),
                entry.family.clone(),
            ))
            .or_default()
            .push((
                index + 1,
                entry.item.as_str(),
                entry.surface_import.as_str(),
                entry.backend_symbol.as_str(),
            ));
    }
    let families = family_groups
        .into_iter()
        .map(|((priority, domain, family), entries)| {
            let first_sequence = entries.first().map(|entry| entry.0).unwrap_or_default();
            let last_sequence = entries.last().map(|entry| entry.0).unwrap_or_default();
            serde_json::json!({
                "priority": priority,
                "domain": domain,
                "family": family,
                "pending": entries.len(),
                "first_sequence": first_sequence,
                "last_sequence": last_sequence,
                "items": entries.iter().map(|entry| entry.1).collect::<Vec<_>>(),
                "surface_imports": entries.iter().map(|entry| entry.2).collect::<Vec<_>>(),
                "backend_symbols": entries.iter().map(|entry| entry.3).collect::<Vec<_>>()
            })
        })
        .collect::<Vec<_>>();
    serde_json::json!({
        "schema": "nc.imports.closure_plan.v1",
        "status": if queue.is_empty() { "closed" } else { "open" },
        "source_of_truth": "ncc_ast.runtime_import_closure_table_all",
        "strategy": "one_import_at_a_time_dependency_order",
        "counts": {
            "total": table.total_entries,
            "closed_real_backing_bytes": table.closed_real_backing_bytes,
            "closed_native_backend": table.closed_native_backend,
            "closed_interpreter_runtime": table.closed_interpreter_runtime,
            "pending": table.catalog_only_with_diagnostic
        },
        "next": queue.first(),
        "families": families,
        "queue": queue
    })
}

fn imports_expand_payload(path: &str) -> Result<serde_json::Value, Box<dyn std::error::Error>> {
    let src = fs::read_to_string(path)?;
    let tokens = ncc_lexer::lex(&src)?;
    let ast = ncc_parser::parse(tokens)?;
    let imports = ast
        .uses
        .iter()
        .map(|use_decl| {
            serde_json::json!({
                "path": use_decl.path.join("."),
                "wildcard": use_decl.wildcard,
                "alias": use_decl.alias,
            })
        })
        .collect::<Vec<_>>();
    Ok(serde_json::json!({
        "schema": "nc.imports.expansion_report.v1",
        "status": "closed",
        "file": path,
        "imports": imports,
        "legacy_use_nC_runtime": "preserved"
    }))
}

fn text_literal_bytes_payload(path: &str) -> Result<serde_json::Value, Box<dyn std::error::Error>> {
    let src = fs::read_to_string(path)?;
    let tokens = ncc_lexer::lex(&src)?;
    let mut literals = Vec::new();

    for token in tokens {
        if let ncc_lexer::TokenKind::String(text) = token.kind {
            let lowered = ncc_ir::lower_text_literal_to_bytes(&text);
            let units = lowered
                .units
                .iter()
                .map(|unit| {
                    serde_json::json!({
                        "char_index": unit.char_index,
                        "byte_offset": unit.byte_offset,
                        "byte_len": unit.byte_len,
                        "scalar": unit.scalar,
                        "codepoint": format!("U+{:04X}", unit.codepoint),
                        "role": unit.role.as_str(),
                        "function": unit.function,
                        "backend_action": unit.backend_action,
                        "bytes": unit.bytes.clone(),
                        "hex": unit.hex,
                    })
                })
                .collect::<Vec<_>>();
            let bytes_hex = backend_host_smoke_bytes_hex(&lowered.bytes);
            let nul_terminated_bytes_hex =
                backend_host_smoke_bytes_hex(&lowered.nul_terminated_bytes);
            literals.push(serde_json::json!({
                "literal_index": literals.len(),
                "line": token.line,
                "column": token.column,
                "text": lowered.text.clone(),
                "encoding": "utf8",
                "scalar_count": lowered.scalar_count,
                "byte_len": lowered.byte_len,
                "nul_terminated_byte_len": lowered.nul_terminated_byte_len,
                "bytes": lowered.bytes.clone(),
                "bytes_hex": bytes_hex,
                "nul_terminated_bytes": lowered.nul_terminated_bytes.clone(),
                "nul_terminated_bytes_hex": nul_terminated_bytes_hex,
                "units": units,
            }));
        }
    }

    let literal_count = literals.len();
    let payload_bytes = literals
        .iter()
        .filter_map(|literal| literal.get("byte_len").and_then(serde_json::Value::as_u64))
        .sum::<u64>();
    let nul_terminated_bytes = literals
        .iter()
        .filter_map(|literal| {
            literal
                .get("nul_terminated_byte_len")
                .and_then(serde_json::Value::as_u64)
        })
        .sum::<u64>();

    Ok(serde_json::json!({
        "schema": "ncc.text_bytes.report.v1",
        "status": "closed",
        "file": path,
        "encoding": "utf8",
        "literal_count": literal_count,
        "payload_bytes": payload_bytes,
        "nul_terminated_bytes": nul_terminated_bytes,
        "backend_contract": "TextLiteralBytesIR is the single lowering truth for source text, LLVM literal bytes, print literal bytes, and native .rodata.",
        "literals": literals,
    }))
}

fn run_language_spec_command(args: &[String]) -> Result<(), Box<dyn std::error::Error>> {
    let mut format = "json";
    let mut out_path: Option<&str> = None;
    let mut pointer_width = 8usize;
    let mut generate_dir: Option<&str> = None;
    let mut check_dir: Option<&str> = None;
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--format" => {
                index += 1;
                format = args
                    .get(index)
                    .ok_or("--format expects json, markdown or ebnf")?;
            }
            "--out" => {
                index += 1;
                out_path = Some(args.get(index).ok_or("--out expects a path")?);
            }
            "--pointer-width" => {
                index += 1;
                pointer_width = args
                    .get(index)
                    .ok_or("--pointer-width expects 4, 8 or 16")?
                    .parse::<usize>()?;
                if !matches!(pointer_width, 4 | 8 | 16) {
                    return Err("--pointer-width expects 4, 8 or 16".into());
                }
            }
            "--generate" => {
                index += 1;
                generate_dir = Some(args.get(index).ok_or("--generate expects a directory")?);
            }
            "--check" => {
                index += 1;
                check_dir = Some(args.get(index).ok_or("--check expects a directory")?);
            }
            unknown => return Err(format!("unknown language-spec option '{unknown}'").into()),
        }
        index += 1;
    }

    let spec = ncc_ast::canonical_language_spec(pointer_width);
    ncc_ast::validate_canonical_language_spec(&spec)?;
    if generate_dir.is_some() && check_dir.is_some() {
        return Err("--generate and --check are mutually exclusive".into());
    }
    let generated = [
        (
            "nc-language-spec.json",
            serde_json::to_string_pretty(&spec)? + "\n",
        ),
        ("nc-language.ebnf", ncc_ast::canonical_grammar_ebnf()),
        (
            "nc-language-spec.md",
            ncc_ast::canonical_spec_markdown(&spec),
        ),
    ];
    if let Some(directory) = generate_dir {
        fs::create_dir_all(directory)?;
        for (name, contents) in &generated {
            fs::write(std::path::Path::new(directory).join(name), contents)?;
        }
        return Ok(());
    }
    if let Some(directory) = check_dir {
        for (name, expected) in &generated {
            let path = std::path::Path::new(directory).join(name);
            let actual = fs::read_to_string(&path).map_err(|error| {
                format!(
                    "E_SPEC_DRIFT_001: cannot read generated artifact '{}': {error}",
                    path.display()
                )
            })?;
            if actual != *expected {
                return Err(format!(
                    "E_SPEC_DRIFT_001: '{}' differs from the canonical language manifest",
                    path.display()
                )
                .into());
            }
        }
        println!("OK: canonical language artifacts match {}", directory);
        return Ok(());
    }
    let rendered = match format {
        "json" => serde_json::to_string_pretty(&spec)? + "\n",
        "markdown" | "md" => ncc_ast::canonical_spec_markdown(&spec),
        "ebnf" => ncc_ast::canonical_grammar_ebnf(),
        other => return Err(format!("unknown language-spec format '{other}'").into()),
    };
    if let Some(path) = out_path {
        if let Some(parent) = std::path::Path::new(path).parent() {
            fs::create_dir_all(parent)?;
        }
        fs::write(path, rendered)?;
    } else {
        print!("{rendered}");
    }
    Ok(())
}

