fn high_level_compile_time_file_payload(
    command: &str,
    args: &[String],
    manifest: serde_json::Value,
) -> Result<(bool, serde_json::Value), Box<dyn std::error::Error>> {
    let mut json = false;
    let mut file: Option<String> = None;
    for arg in args.iter().skip(1) {
        match arg.as_str() {
            "--json" => json = true,
            "-h" | "--help" | "help" => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: use high-level help for syntax"),
                )
                .into());
            }
            other if is_high_level_source_path(other) && file.is_none() => {
                file = Some(other.to_string());
            }
            other => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: unknown option '{}'", other),
                )
                .into());
            }
        }
    }
    let payload = if let Some(path) = file {
        let ast = load_ast_from_path(&path)?;
        sema_check_with_warnings(&ast)?;
        serde_json::json!({
            "schema": "nc.high_level.phase13.file_report.v1",
            "component": "high-level",
            "phase": "phase13_compile_time_evaluation_model",
            "command": command,
            "file": path,
            "status": "passed",
            "has_errors": false,
            "const_eval": "validated",
            "comptime_unsafe": "validated_and_audited_when_present",
            "manifest": manifest
        })
    } else {
        manifest
    };
    Ok((json, payload))
}

