fn high_level_macro_file_payload(
    command: &str,
    args: &[String],
) -> Result<(bool, serde_json::Value), Box<dyn std::error::Error>> {
    let mut json = false;
    let mut file: Option<String> = None;
    for arg in args.iter().skip(1) {
        match arg.as_str() {
            "--json" => json = true,
            "-h" | "--help" | "help" => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: use high-level help for syntax"),
                )
                .into());
            }
            other if is_high_level_source_path(other) && file.is_none() => {
                file = Some(other.to_string());
            }
            other => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: unknown option '{}'", other),
                )
                .into());
            }
        }
    }
    let payload = if let Some(path) = file {
        let ast = load_ast_from_path(&path)?;
        sema_check_with_warnings(&ast)?;
        let report = high_level_macro_report_from_ast(&ast, &path);
        serde_json::json!({
            "schema": "nc.high_level.phase14.file_report.v1",
            "component": "high-level",
            "phase": "phase14_macros_compile_time_code_generation",
            "command": command,
            "file": path,
            "status": "passed",
            "has_errors": false,
            "macro_report": report,
            "manifest": high_level_macro_manifest_payload()
        })
    } else {
        high_level_macro_manifest_payload()
    };
    Ok((json, payload))
}

fn high_level_macro_report_from_ast(ast: &ncc_ast::Program, file: &str) -> serde_json::Value {
    let mut decls = Vec::new();
    let mut invocations = Vec::new();
    let mut generated = Vec::new();
    let mut unsafe_effects = Vec::new();
    let mut hygiene_marks = Vec::new();
    for container in &ast.containers {
        for section in &container.sections {
            let ncc_ast::Section::Macros(items) = section else {
                continue;
            };
            for item in items {
                match item {
                    ncc_ast::MacroItem::Decl(decl) => {
                        decls.push(serde_json::json!({
                            "container": container.name,
                            "name": decl.name,
                            "kind": format!("{:?}", decl.kind).to_ascii_lowercase(),
                            "params": decl.params.len(),
                            "no_limit": decl.no_limit,
                            "generated_items": decl.generated_items.len(),
                            "source_map": "present",
                            "line": decl.line,
                            "column": decl.column
                        }));
                        for effect in &decl.effects {
                            unsafe_effects.push(serde_json::json!({
                                "macro": decl.name,
                                "capability": effect.capability,
                                "detail": effect.detail,
                                "audited": matches!(decl.kind, ncc_ast::MacroKind::Unsafe)
                            }));
                        }
                        for generated_item in &decl.generated_items {
                            generated.push(serde_json::json!({
                                "macro": decl.name,
                                "kind": format!("{:?}", generated_item.kind).to_ascii_lowercase(),
                                "name_template": generated_item.name_template,
                                "line": generated_item.line,
                                "column": generated_item.column
                            }));
                            hygiene_marks.push(format!(
                                "{}::{}::{}",
                                container.name, decl.name, generated_item.name_template
                            ));
                        }
                    }
                    ncc_ast::MacroItem::Invocation(invocation) => {
                        invocations.push(serde_json::json!({
                            "container": container.name,
                            "macro": invocation.name,
                            "args": invocation.args.len(),
                            "line": invocation.line,
                            "column": invocation.column
                        }));
                    }
                }
            }
        }
    }
    serde_json::json!({
        "file": file,
        "declarations": decls,
        "invocations": invocations,
        "generated_items": generated,
        "hygiene": {
            "status": "closed",
            "marks": hygiene_marks,
            "private_leak": "forbidden",
            "any_leak": "forbidden"
        },
        "source_maps": {
            "status": "closed",
            "mapping": "macro_definition_to_expansion_site_to_generated_item"
        },
        "unsafe_effects": unsafe_effects,
        "expansion_report": {
            "status": "closed",
            "declaration_count": decls.len(),
            "invocation_count": invocations.len(),
            "generated_item_count": generated.len()
        }
    })
}

