fn high_level_json_flag_only(
    command: &str,
    args: &[String],
) -> Result<bool, Box<dyn std::error::Error>> {
    let mut json = false;
    for arg in args.iter().skip(1) {
        match arg.as_str() {
            "--json" => json = true,
            "-h" | "--help" | "help" => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: use high-level help for syntax"),
                )
                .into());
            }
            other => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: unknown option '{}'", other),
                )
                .into());
            }
        }
    }
    Ok(json)
}

