fn high_level_risk_file_payload(
    command: &str,
    args: &[String],
) -> Result<(bool, serde_json::Value), Box<dyn std::error::Error>> {
    let mut json = false;
    let mut file: Option<String> = None;
    for arg in args.iter().skip(1) {
        match arg.as_str() {
            "--json" => json = true,
            "-h" | "--help" | "help" => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: use high-level help for syntax"),
                )
                .into());
            }
            other if is_high_level_source_path(other) && file.is_none() => {
                file = Some(other.to_string());
            }
            other => {
                return Err(actionable_command_error(
                    "high-level",
                    format!("high-level {command}: unknown option '{}'", other),
                )
                .into());
            }
        }
    }
    let payload = if let Some(path) = file {
        let ast = load_ast_from_path(&path)?;
        sema_check_with_warnings(&ast)?;
        let report = high_level_risk_report_from_ast(&ast, &path);
        serde_json::json!({
            "schema": "nc.high_level.phase15.file_report.v1",
            "component": "high-level",
            "phase": "phase15_risk_authority_expert_policy_surface",
            "command": command,
            "file": path,
            "status": "passed",
            "has_errors": false,
            "risk_report": report,
            "authority_report": report["authority"].clone(),
            "manifest": high_level_risk_manifest_payload()
        })
    } else {
        high_level_risk_manifest_payload()
    };
    Ok((json, payload))
}

fn high_level_risk_item_label(item: &ncc_ast::HighRiskItem) -> &'static str {
    match item {
        ncc_ast::HighRiskItem::Allow(_) => "allow",
        ncc_ast::HighRiskItem::Accept(_) => "accept",
        ncc_ast::HighRiskItem::Bridge(_) => "bridge",
        ncc_ast::HighRiskItem::Report(_) => "report",
    }
}

fn high_level_risk_kind_cli_label(kind: &ncc_ast::HighRiskKind) -> &'static str {
    match kind {
        ncc_ast::HighRiskKind::DataRace => "data_race",
        ncc_ast::HighRiskKind::AliasMutation => "alias_mutation",
        ncc_ast::HighRiskKind::NoBackpressure => "no_backpressure",
        ncc_ast::HighRiskKind::StreamNoBackpressure => "stream_no_backpressure",
        ncc_ast::HighRiskKind::ChannelNoBackpressure => "channel_no_backpressure",
        ncc_ast::HighRiskKind::NoRollback => "no_rollback",
        ncc_ast::HighRiskKind::TransactionPartialCommit => "transaction_partial_commit",
        ncc_ast::HighRiskKind::PartialMatch => "partial_match",
        ncc_ast::HighRiskKind::UncheckedUnwrap => "unchecked_unwrap",
        ncc_ast::HighRiskKind::UncheckedCast => "unchecked_cast",
        ncc_ast::HighRiskKind::EffectErasure => "effect_erasure",
        ncc_ast::HighRiskKind::PrivateLeak => "private_metadata_leak",
        ncc_ast::HighRiskKind::AnyLeak => "any_leak",
        ncc_ast::HighRiskKind::AnyConstruction => "any_construction",
        ncc_ast::HighRiskKind::ConstructionLeak => "construction_leak",
        ncc_ast::HighRiskKind::RawPtr => "raw_ptr",
        ncc_ast::HighRiskKind::RawAddr => "raw_addr",
        ncc_ast::HighRiskKind::RawSite => "raw_site",
        ncc_ast::HighRiskKind::SilentPointer => "silent_pointer",
        ncc_ast::HighRiskKind::LowLevelBridge => "low_level_bridge",
        ncc_ast::HighRiskKind::ComptimeUnsafe => "comptime_unsafe",
        ncc_ast::HighRiskKind::UnsafeMacro => "unsafe_macro",
        ncc_ast::HighRiskKind::NoLimit => "no_limit",
        ncc_ast::HighRiskKind::UnboundedLoop => "unbounded_loop",
        ncc_ast::HighRiskKind::UnboundedRecursion => "unbounded_recursion",
        ncc_ast::HighRiskKind::LowLevelPatch => "low_level_patch",
        ncc_ast::HighRiskKind::FragileDesign => "fragile_design",
        ncc_ast::HighRiskKind::HeapRegionView => "heap_region_view",
        ncc_ast::HighRiskKind::ImpossibleLowering => "impossible_lowering",
        ncc_ast::HighRiskKind::UnresolvedSymbol => "unresolved_symbol",
        ncc_ast::HighRiskKind::InvalidType => "invalid_type",
        ncc_ast::HighRiskKind::FakeSafety => "declared_false_safety",
        ncc_ast::HighRiskKind::SilentFallback => "silent_fallback",
    }
}

fn high_level_risk_report_from_ast(ast: &ncc_ast::Program, file: &str) -> serde_json::Value {
    let mut risk_items = Vec::new();
    let mut allowances = BTreeSet::new();
    let mut accepts = Vec::new();
    let mut bridges = Vec::new();
    let mut report_decls = Vec::new();

    for container in &ast.containers {
        for section in &container.sections {
            let ncc_ast::Section::Risk(items) = section else {
                continue;
            };
            for item in items {
                risk_items.push(serde_json::json!({
                    "container": container.name,
                    "context": context_label(&container.context),
                    "kind": high_level_risk_item_label(item)
                }));
                match item {
                    ncc_ast::HighRiskItem::Allow(allow) => {
                        allowances.insert(allow.capability.clone());
                    }
                    ncc_ast::HighRiskItem::Accept(accept) => {
                        accepts.push(serde_json::json!({
                            "container": container.name,
                            "risk": high_level_risk_kind_cli_label(&accept.kind),
                            "detail": accept.detail,
                            "line": accept.line,
                            "column": accept.column,
                            "authority": "explicit_allow_checked"
                        }));
                    }
                    ncc_ast::HighRiskItem::Bridge(bridge) => {
                        bridges.push(serde_json::json!({
                            "container": container.name,
                            "target": bridge.target,
                            "reason": bridge.reason,
                            "authority": bridge.authority,
                            "line": bridge.line,
                            "column": bridge.column,
                            "status": "authorized_when_allow_and_authority_match"
                        }));
                    }
                    ncc_ast::HighRiskItem::Report(report) => {
                        report_decls.push(serde_json::json!({
                            "container": container.name,
                            "name": report.name,
                            "line": report.line,
                            "column": report.column
                        }));
                    }
                }
            }
        }
    }

    serde_json::json!({
        "file": file,
        "status": "closed",
        "item_count": risk_items.len(),
        "items": risk_items,
        "policy": {
            "allowances": allowances.into_iter().collect::<Vec<_>>(),
            "accept_count": accepts.len(),
            "bridge_count": bridges.len(),
            "report_count": report_decls.len(),
            "separate_expert_mode": "not_created",
            "authority": "integrated_high_level_policy_surface"
        },
        "accepted_risks": accepts,
        "bridges": bridges,
        "declared_reports": report_decls,
        "authority": {
            "data_race": "explicit_allow_required",
            "backpressure": "explicit_allow_required",
            "rollback": "explicit_allow_required",
            "raw_ptr_addr_site": "explicit_allow_required",
            "silent_pointer": "explicit_allow_accept_required",
            "unsafe_bridge": "explicit_allow_reason_authority_required",
            "no_limit": "explicit_allow_required",
            "silent_fallback": "forbidden"
        },
        "unification": {
            "runtime": "prepared_not_merged",
            "compiler": "prepared_not_merged",
            "phase16_plus": "not_started"
        }
    })
}

