fn levenshtein_distance(a: &str, b: &str) -> usize {
    let a_chars = a.chars().collect::<Vec<_>>();
    let b_chars = b.chars().collect::<Vec<_>>();
    if a_chars.is_empty() {
        return b_chars.len();
    }
    if b_chars.is_empty() {
        return a_chars.len();
    }

    let mut prev = (0..=b_chars.len()).collect::<Vec<_>>();
    let mut curr = vec![0usize; b_chars.len() + 1];

    for (i, ca) in a_chars.iter().enumerate() {
        curr[0] = i + 1;
        for (j, cb) in b_chars.iter().enumerate() {
            let cost = if ca == cb { 0 } else { 1 };
            curr[j + 1] = (prev[j + 1] + 1).min(curr[j] + 1).min(prev[j] + cost);
        }
        prev.clone_from(&curr);
    }

    prev[b_chars.len()]
}

fn suggest_closest_candidate<'a>(raw: &str, candidates: &'a [&str]) -> Option<&'a str> {
    let needle = raw.trim().to_ascii_lowercase();
    if needle.is_empty() {
        return None;
    }
    let mut best: Option<(&str, usize)> = None;
    for candidate in candidates {
        let dist = levenshtein_distance(&needle, &candidate.to_ascii_lowercase());
        match best {
            None => best = Some((candidate, dist)),
            Some((_, best_dist)) if dist < best_dist => best = Some((candidate, dist)),
            _ => {}
        }
    }
    let (candidate, distance) = best?;
    let max_distance = if needle.len() <= 4 {
        2
    } else if needle.len() <= 8 {
        3
    } else {
        4
    };
    if distance <= max_distance {
        Some(candidate)
    } else {
        None
    }
}

fn suggestion_suffix(raw: &str, candidates: &[&str]) -> String {
    match suggest_closest_candidate(raw, candidates) {
        Some(suggested) => format!("\nSuggestion: did you mean '{}'?", suggested),
        None => String::new(),
    }
}

fn executable_alias_to_command(exe_path: &str) -> Option<&'static str> {
    let stem = PathBuf::from(exe_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .map(|s| s.to_ascii_lowercase())?;
    match stem.as_str() {
        "nfmt" => Some("nfmt"),
        "nlint" => Some("nlint"),
        "nbuild" => Some("nbuild"),
        "npkg" => Some("npkg"),
        "nide" => Some("nide"),
        "nclsp" => Some("nclsp"),
        "ncup" => Some("ncup"),
        "ncup-init" => Some("ncup-init"),
        "ghor" => Some("ghor"),
        _ => None,
    }
}

fn load_ast_from_path(path: &str) -> Result<ncc_ast::Program, Box<dyn std::error::Error>> {
    let src = fs::read_to_string(path)?;
    load_ast_from_source_with_cache(Path::new(path), &src)
}

fn program_has_kernel_context(program: &ncc_ast::Program) -> bool {
    program
        .containers
        .iter()
        .any(|container| matches!(container.context, Some(ncc_ast::Context::Kernel)))
}

fn load_ast_from_source_with_cache(
    path: &Path,
    src: &str,
) -> Result<ncc_ast::Program, Box<dyn std::error::Error>> {
    let display_path = path.to_string_lossy();
    let tokens = ncc_lexer::lex(src).map_err(|diagnostic| {
        render_release_source_diagnostic(&diagnostic, "lexer", &display_path, src)
    })?;
    ncc_parser::validate_material_v2_surface(&tokens).map_err(|diagnostic| {
        render_release_source_diagnostic(&diagnostic, "parser", &display_path, src)
    })?;
    if let Some(ast) = content_cache::probe_ast(path, src) {
        return Ok(ast);
    }
    let ast = ncc_parser::parse_material_v2(tokens).map_err(|diagnostic| {
        render_release_source_diagnostic(&diagnostic, "parser", &display_path, src)
    })?;
    content_cache::store_ast(path, src, &ast);
    Ok(ast)
}

fn is_high_level_source_path(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    lower.ends_with(".n") || lower.ends_with(".nc")
}

fn sema_check_with_warnings(ast: &ncc_ast::Program) -> Result<(), Box<dyn std::error::Error>> {
    match sema_analyze_with_content_cache(ast) {
        Ok(result) => {
            for w in result.warnings {
                eprintln!("warning: {w}");
            }
            Ok(())
        }
        Err(e) => Err(render_release_legacy_diagnostic(&e, "sema", "<source>", "").into()),
    }
}

fn sema_analyze_with_content_cache(
    ast: &ncc_ast::Program,
) -> Result<ncc_sema::SemanticResult, String> {
    if let Some(warnings) = content_cache::probe_sema_warnings(ast) {
        return Ok(ncc_sema::SemanticResult {
            ok: true,
            warnings,
            phase_timings: Vec::new(),
        });
    }
    let result = ncc_sema::analyze(ast)?;
    content_cache::store_sema_warnings(ast, &result.warnings);
    Ok(result)
}

fn context_label(ctx: &Option<ncc_ast::Context>) -> String {
    match ctx {
        Some(ncc_ast::Context::Root) => "@".to_string(),
        Some(ncc_ast::Context::Machine) => "@machine".to_string(),
        Some(ncc_ast::Context::Runtime) => "@runtime".to_string(),
        Some(ncc_ast::Context::Primitive) => "@primitive".to_string(),
        Some(ncc_ast::Context::Inspect) => "@inspect".to_string(),
        Some(ncc_ast::Context::Security) => "@security".to_string(),
        Some(ncc_ast::Context::Network) => "@network".to_string(),
        Some(ncc_ast::Context::System) => "@system".to_string(),
        Some(ncc_ast::Context::Kernel) => "@kernel".to_string(),
        Some(ncc_ast::Context::Tooling) => "@tooling".to_string(),
        Some(ncc_ast::Context::Compiler) => "@compiler".to_string(),
        Some(ncc_ast::Context::Ai) => "@ai".to_string(),
        Some(ncc_ast::Context::Unknown(label)) => format!("@{}", label),
        None => "none".to_string(),
    }
}

