        let ast = parse_fixture("primitive_at", "primitive_at_boot_serial_short_header_ok.n");
        let asm = emit_backend_from_ast(&ast).expect("backend emission must pass sema+lowering");
        assert!(asm.contains("cap_contracts=1"));
