    #[test]
    fn machine_lea_rel_symbol_emits_pc_relative_object_relocation() {
        use std::fmt::Write as _;

        let dir = make_temp_path("machine_lea_rel", "dir");
        std::fs::create_dir_all(&dir).expect("temp dir must create");
        let nm_path = dir.join("lea_rel.nm");
        let obj_path = dir.join("lea_rel.o");
        let regs = [
            "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11",
            "r12", "r13", "r14", "r15",
        ];
        let mut instr = String::new();
        let mut data = String::new();
        for reg in regs {
            let symbol = format!("ncc_return_fmt_{reg}");
            writeln!(&mut instr, "        lea {reg}, [rel {symbol}];").unwrap();
            writeln!(&mut data, "        {symbol}:\n            db 111, 107, 0;").unwrap();
        }
        writeln!(
            &mut instr,
            "        lea rdi, [rip + ncc_return_fmt_rip];\n        lea rsi, qword [rel ncc_return_fmt_qword];"
        )
        .unwrap();
        writeln!(
            &mut data,
            "        ncc_return_fmt_rip:\n            db 114, 105, 112, 0;\n        ncc_return_fmt_qword:\n            db 113, 119, 111, 114, 100, 0;"
        )
        .unwrap();
        std::fs::write(
            &nm_path,
            format!(
                r#"leaRelBridge[@machine] {{
    target:
        arch: x86_64;
        abi: sysv64;
        object: elf64;
        endian: little;
        pointerWidth: 64;
        profile: userland;

    symbol:
        main:
            section: .text;
            binding: global;
            type: routine;

    entry:
        main;

    proc:
        main:

    instr:
{instr}
        mov rax, 0;
        ret;

    data:
{data}

    verify:
        target;
        encoding;
        object;

    seal:
        artifact: executable;
        require: verified;
}}
"#,
            )
            .as_bytes(),
        )
        .expect("machine source must write");

        commands::machine::check_machine_source_path(nm_path.to_string_lossy().as_ref())
            .expect("lea [rel symbol] source must check");
        commands::machine::emit_machine_source_object_to_path(
            nm_path.to_string_lossy().as_ref(),
            "x86_64-unknown-linux-gnu",
            obj_path.to_string_lossy().as_ref(),
        )
        .expect("lea [rel symbol] source must emit object");
        let meta_path = PathBuf::from(format!("{}.machine-link-meta.json", obj_path.display()));
        let meta = std::fs::read_to_string(&meta_path).expect("machine metadata must exist");
        let json: serde_json::Value =
            serde_json::from_str(&meta).expect("machine metadata must be json");
        let relocs = json["link_unit"]["relocations"]
            .as_array()
            .expect("relocations must be an array");
        assert_eq!(relocs.len(), 18, "{json:#?}");
        assert!(
            relocs.iter().any(|rel| {
                rel["kind"] == "pc32"
                    && rel["symbol"] == "ncc_return_fmt_rdi"
                    && rel["offset"] == 52
            }),
            "{json:#?}"
        );
        assert!(
            relocs
                .iter()
                .any(|rel| { rel["kind"] == "pc32" && rel["symbol"] == "ncc_return_fmt_rip" }),
            "{json:#?}"
        );
        assert!(
            relocs
                .iter()
                .any(|rel| { rel["kind"] == "pc32" && rel["symbol"] == "ncc_return_fmt_qword" }),
            "{json:#?}"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn ncc_run_recognizes_host_launcher_scripts() {
        let dir = make_temp_path("host_launcher_scripts", "dir");
        std::fs::create_dir_all(&dir).expect("temp dir must create");
        let ps1 = dir.join("app.ps1");
        let bat = dir.join("app.bat");
        std::fs::write(&ps1, "$exe = 'app.exe'\n& $exe @args\n").expect("ps1 must write");
        std::fs::write(&bat, "@echo off\nset \"NCC_EXE=app.exe\"\n").expect("bat must write");

        assert!(ncc_run_is_source_extension("ps1"));
        assert!(ncc_run_is_source_extension("bat"));
        ncc_validate_host_launcher_script(
            &ps1,
            &std::fs::read_to_string(&ps1).expect("ps1 must read"),
        )
        .expect("ps1 launcher must validate");
        ncc_validate_host_launcher_script(
            &bat,
            &std::fs::read_to_string(&bat).expect("bat must read"),
        )
        .expect("bat launcher must validate");

        let _ = std::fs::remove_dir_all(&dir);
    }

