    #[test]
    fn primitive_advanced_material_directives_lower_into_entity_contract_hook_markers() {
        let ast = parse_fixture("primitive", "material_advanced_contracts_ok.ncp");
        let contract = primitive_extract_boot_contract(
            &primitive_find_container(&ast).expect("primitive container"),
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced fixture should extract boot contract");
        assert!(
            contract
                .ops
                .iter()
                .any(|op| primitive_event_op_view(op).is_some()),
            "advanced lowering must materialize event contract hooks"
        );
        assert!(
            contract
                .ops
                .iter()
                .any(|op| primitive_material_probe_profile_from_op(op).is_some()),
            "advanced lowering must materialize directive material-entity contract hooks"
        );

        let image = build_primitive_boot_image_from_program(
            &ast,
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced lowering should succeed")
        .expect("advanced fixture should produce boot image");
        let hex: String = image.iter().map(|byte| format!("{byte:02x}")).collect();
        for marker in [
            "b0e134", // event: interrupt
            "b0e234", // event: dmaCompletion
            "b0e334", // event: watchdogTrip
            "b01134", // probe: electrical
            "b01934", // probe: pipeline
            "b01a34", // probe: firmware/boot
            "b02034", // probe: physical fault family
        ] {
            assert!(
                hex.contains(marker),
                "advanced material lowering should include marker '{}'",
                marker
            );
        }
    }

    #[test]
    fn primitive_advanced_material_hooks_and_probes_lower_before_terminal_halt() {
        let ast = parse_fixture("primitive", "material_advanced_contracts_ok.ncp");
        let contract = primitive_extract_boot_contract(
            &primitive_find_container(&ast).expect("primitive container"),
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced fixture should extract boot contract");
        let terminal_idx = contract
            .ops
            .iter()
            .position(primitive_material_op_is_terminal)
            .expect("advanced fixture should contain terminal op");
        let mut found_hook_or_probe = false;
        for (idx, op) in contract.ops.iter().enumerate() {
            let is_hook_or_probe = primitive_protocol_op_view(op).is_some()
                || matches!(op, PrimitiveMaterialOp::MaterialEntityContractHook { .. });
            let is_hook_or_probe = is_hook_or_probe || primitive_event_op_view(op).is_some();
            if is_hook_or_probe {
                found_hook_or_probe = true;
                assert!(
                    idx < terminal_idx,
                    "protocol/event/probe hook must be lowered before terminal halt op"
                );
            }
        }
        assert!(
            found_hook_or_probe,
            "advanced fixture should materialize hooks/probes"
        );

        let image = build_primitive_boot_image_from_program(
            &ast,
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced lowering should succeed")
        .expect("advanced fixture should produce boot image");
        let hex: String = image.iter().map(|byte| format!("{byte:02x}")).collect();
        let halt_idx = hex
            .find("faf4ebfd")
            .expect("halt loop marker must exist in lowered image");
        let hook_idx = hex
            .find("b0e134")
            .expect("event-hook marker should exist in lowered image");
        assert!(
            hook_idx < halt_idx,
            "event hook bytes must be emitted before terminal halt sequence"
        );
    }

    #[test]
    fn primitive_advanced_material_hooks_and_probes_emit_family_specific_prefixes() {
        let ast = parse_fixture("primitive", "material_advanced_contracts_ok.ncp");
        let image = build_primitive_boot_image_from_program(
            &ast,
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced lowering should succeed")
        .expect("advanced fixture should produce boot image");
        let hex: String = image.iter().map(|byte| format!("{byte:02x}")).collect();

        for needle in [
            "0faef0b0e2", // dmaCompletion event: mfence + compact marker
            "a801b0e4",   // mmioReadClearsFlag event: test + compact marker
            "0faef0b016", // dma probe family: mfence + compact marker
            "0faef8b017", // cacheState semantic probe: sfence + compact marker
            "a840b014",   // thermal probe family: test + compact marker
            "f8b01a",     // firmwareRegion semantic probe: clc + compact marker
            "fab01a",     // biosRegion semantic probe: cli + compact marker
        ] {
            assert!(
                hex.contains(needle),
                "advanced lowering should contain family-specific prefix sequence '{}'",
                needle
            );
        }
    }

    #[test]
    fn primitive_protocol_uart_contract_lowering_emits_controller_peripheral_signature() {
        let protocol = PrimitiveMaterialOp::ProtocolUart {
            controller: "uart_ctrl".to_string(),
            peripheral: Some("uart0".to_string()),
            data_port: 0x03F8,
            status_port: 0x03FD,
            ready_mask: 0x20,
            write_mask: 0x01,
        };
        let bytes = primitive_material_op_lowering_bytes(&protocol, "kernelEntry")
            .expect("protocol UART contract lowering must materialize");
        let hex = primitive_bytes_to_hex(&bytes);
        let controller_marker = primitive_material_symbol_marker_byte("uart_ctrl");
        let peripheral_marker = primitive_material_symbol_marker_byte("uart0");
        let uart_prefix_hex =
            primitive_bytes_to_hex(primitive_protocol_lowering_prefix_bytes("UART"));
        let uart_suffix_hex =
            primitive_bytes_to_hex(primitive_protocol_lowering_suffix_bytes("UART"));
        assert!(
            hex.contains(&format!(
                "{uart_prefix_hex}b03134{:02x}90{uart_suffix_hex}",
                controller_marker ^ peripheral_marker
            )),
            "UART protocol contract must encode prefix + protocol marker + controller/peripheral markers + suffix"
        );
    }

    #[test]
    fn primitive_advanced_material_lowering_contains_protocol_contract_ops() {
        let src = r#"
primitive[@]:
    controller:
        uart_ctrl;
    peripheral:
        uart0;
    capability hw:
        allow port.write;
    bus io8:
        width 8;
    port uart0.data:
        bus io8;
        addr ioaddr(0x03F8);
    operation kernelEntry():
        capability hw;
        protocol UART;
        write uart0.data <- 0x41;
        barrier io;
        haltLoop;
    anchor:
        boot0;
    bridge:
        root.policy.bind;
        root.policy.guard;
        root.memory.resolve;
        machine.machineCore;
    seal:
        primitiveClosed;
"#;
        let tokens = ncc_lexer::lex(src).expect("protocol fixture must lex");
        let ast = ncc_parser::parse(tokens).expect("protocol fixture must parse");
        let contract = primitive_extract_boot_contract(
            &primitive_find_container(&ast).expect("primitive container"),
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced fixture should extract boot contract");
        assert!(
            contract
                .ops
                .iter()
                .any(|op| primitive_protocol_op_view(op).is_some()),
            "advanced fixture should materialize protocol contract op"
        );

        let image = build_primitive_boot_image_from_program(
            &ast,
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("advanced lowering should succeed")
        .expect("advanced fixture should produce boot image");
        let hex = primitive_bytes_to_hex(&image);
        assert!(
            hex.contains("bafd03eca820b031"),
            "advanced material lowering image must include UART protocol contract marker sequence"
        );
    }

