    #[test]
    fn primitive_protocol_contract_lowering_emits_protocol_specific_sequences() {
        let pcie = PrimitiveMaterialOp::ProtocolPcie {
            controller: "pcie_ctrl".to_string(),
            lane: "pcie_lane0".to_string(),
            config_addr_port: 0x0CF8,
            config_data_port: 0x0CFC,
            config_command: 0x80,
            compare_value: 0x32,
        };
        let pcie_bytes = primitive_material_op_lowering_bytes(&pcie, "kernelEntry")
            .expect("PCIE protocol lowering must materialize");
        let pcie_hex = primitive_bytes_to_hex(&pcie_bytes);
        assert!(
            pcie_hex.contains("baf80cb080eebafc0cec"),
            "PCIE lowering must include x86 config-space cycle bytes"
        );

        let usb = PrimitiveMaterialOp::ProtocolUsb {
            controller: "xhci0".to_string(),
            peripheral: "usbdev0".to_string(),
            window: "xhci_win".to_string(),
            window_addr: 0x1100,
            status_offset: 0x04,
            command_offset: 0x00,
        };
        let usb_bytes = primitive_material_op_lowering_bytes(&usb, "kernelEntry")
            .expect("USB protocol lowering must materialize");
        let usb_hex = primitive_bytes_to_hex(&usb_bytes);
        let usb_subject_marker = primitive_material_symbol_marker_byte("xhci0")
            ^ primitive_material_symbol_marker_byte("usbdev0");
        let usb_suffix_hex =
            primitive_bytes_to_hex(primitive_protocol_lowering_suffix_bytes("USB"));
        assert!(
            usb_hex.contains("8a07a808"),
            "USB lowering must include MMIO host-controller read/test sequence"
        );
        assert!(
            usb_hex.contains(&format!("b03334{usb_subject_marker:02x}90")),
            "USB lowering must include protocol marker bytes with controller/peripheral binding"
        );
        assert!(
            usb_hex.contains(&usb_suffix_hex),
            "USB lowering must include MMIO command write/fence suffix bytes"
        );
    }

    #[test]
    fn primitive_advanced_event_and_probe_lowering_emit_suffix_contract_bytes() {
        let interrupt_subject = "irq0".to_string();
        let interrupt_subject_marker = primitive_material_symbol_marker_byte(&interrupt_subject);
        let interrupt = PrimitiveMaterialOp::LegacyEventContract {
            kind: PrimitiveEventContractKind::Interrupt,
            subject: interrupt_subject,
        };
        let interrupt_bytes = primitive_material_op_lowering_bytes(&interrupt, "kernelEntry")
            .expect("interrupt event lowering must materialize");
        let interrupt_hex = primitive_bytes_to_hex(&interrupt_bytes);
        assert!(
            interrupt_hex.contains(&format!("90b0e134{interrupt_subject_marker:02x}90a810")),
            "interrupt lowering must include prefix + marker + suffix contract bytes"
        );

        let thermal_symbol = "thermal_nominal".to_string();
        let thermal_semantic = "thermalState".to_string();
        let thermal_subject_marker = primitive_material_symbol_marker_byte(&thermal_symbol);
        let thermal_semantic_marker = primitive_material_semantic_marker_byte(&thermal_semantic);
        let thermal = PrimitiveMaterialOp::MaterialEntityContractHook {
            kind: PrimitiveMaterialContractKind::Thermal,
            semantic: thermal_semantic,
            symbol: thermal_symbol,
        };
        let thermal_bytes = primitive_material_op_lowering_bytes(&thermal, "kernelEntry")
            .expect("thermal probe lowering must materialize");
        let thermal_hex = primitive_bytes_to_hex(&thermal_bytes);
        let thermal_prefix_hex = primitive_bytes_to_hex(
            primitive_material_probe_semantic_prefix_bytes("thermalState")
                .expect("thermalState semantic prefix must exist"),
        );
        let thermal_suffix_hex = primitive_bytes_to_hex(
            primitive_material_probe_semantic_suffix_bytes("thermalState")
                .expect("thermalState semantic suffix must exist"),
        );
        assert!(
            thermal_hex.contains(&format!(
                "{}b01434{:02x}90{}",
                thermal_prefix_hex,
                thermal_semantic_marker ^ thermal_subject_marker,
                thermal_suffix_hex
            )),
            "thermal probe lowering must include prefix + marker + suffix contract bytes"
        );
    }

    #[test]
    fn primitive_nominal_event_contracts_export_construct_and_side_effect_contracts() {
        let src = r#"
primitiveNominalEventWitness[@primitive] {
    interruptLine:
        irq0;

    capability hw:
        allow port.write;

    operation kernelEntry():
        capability hw;
        sideEffect interrupt_preemption_contract;
        physicalEvent interrupt irq0;
        asyncHardwareEvent interrupt irq0;
        haltLoop;

    anchor boot0:
        addr physaddr(0x0000_7C00);

    bridge:
        root.policy.bind;
        root.policy.guard;
        root.memory.resolve;
        machine.machineCore;

    seal:
        primitiveClosed;
}
"#;
        let tokens = ncc_lexer::lex(src).expect("nominal event fixture must lex");
        let ast = ncc_parser::parse(tokens).expect("nominal event fixture must parse");
        let contract = primitive_extract_boot_contract(
            &primitive_find_container(&ast).expect("primitive container"),
            Some("kernelEntry"),
            PrimitiveLoweringPolicy::default(),
        )
        .expect("nominal event fixture should extract boot contract");
        let event_contracts = primitive_event_contracts_to_json(
            &contract.event_contracts,
            &contract.side_effect_contracts,
        );

        assert!(
            event_contracts.iter().any(|row| {
                row.get("construct_kind")
                    .and_then(|v| v.as_str())
                    .map(|kind| kind == "physicalEvent")
                    .unwrap_or(false)
            }),
            "event contracts must expose physicalEvent nominal construct"
        );
        assert!(
            event_contracts.iter().any(|row| {
                row.get("construct_kind")
                    .and_then(|v| v.as_str())
                    .map(|kind| kind == "asyncHardwareEvent")
                    .unwrap_or(false)
            }),
            "event contracts must expose asyncHardwareEvent nominal construct"
        );
        assert!(
            event_contracts.iter().any(|row| {
                row.get("async_hardware_event_construct")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(false)
            }),
            "event contracts must flag async nominal construct"
        );
        assert!(
            event_contracts.iter().all(|row| {
                row.get("side_effects")
                    .and_then(|v| v.as_array())
                    .map(|effects| {
                        effects.iter().any(|value| {
                            value
                                .as_str()
                                .map(|s| s == "interrupt_preemption_contract")
                                .unwrap_or(false)
                        })
                    })
                    .unwrap_or(false)
            }),
            "event contracts must include explicit sideEffect contract payload"
        );
    }

    #[test]
    fn primitive_advanced_lowering_metadata_is_total_for_contract_families_and_events() {
        let all_material_families = [
            PrimitiveMaterialContractKind::Electrical,
            PrimitiveMaterialContractKind::Timing,
            PrimitiveMaterialContractKind::Power,
            PrimitiveMaterialContractKind::Thermal,
            PrimitiveMaterialContractKind::Interrupt,
            PrimitiveMaterialContractKind::Dma,
            PrimitiveMaterialContractKind::Cache,
            PrimitiveMaterialContractKind::Tlb,
            PrimitiveMaterialContractKind::Pipeline,
            PrimitiveMaterialContractKind::FirmwareBoot,
            PrimitiveMaterialContractKind::Controller,
            PrimitiveMaterialContractKind::Peripheral,
            PrimitiveMaterialContractKind::Phy,
            PrimitiveMaterialContractKind::Lane,
            PrimitiveMaterialContractKind::Channel,
            PrimitiveMaterialContractKind::PhysicalFault,
        ];
        for kind in all_material_families {
            assert!(
                !kind.lowering_prefix_bytes().is_empty(),
                "material family '{}' must expose lowering prefix bytes",
                kind.as_str()
            );
            assert!(
                !kind.lowering_suffix_bytes().is_empty(),
                "material family '{}' must expose lowering suffix bytes",
                kind.as_str()
            );
            assert!(
                !kind.lowering_semantics().is_empty(),
                "material family '{}' must expose lowering semantics tags",
                kind.as_str()
            );
        }

        let all_events = [
            PrimitiveEventContractKind::Interrupt,
            PrimitiveEventContractKind::DmaCompletion,
            PrimitiveEventContractKind::WatchdogTrip,
            PrimitiveEventContractKind::MmioReadClearsFlag,
            PrimitiveEventContractKind::PeripheralStateChange,
            PrimitiveEventContractKind::PhysicalFault,
        ];
        for event in all_events {
            assert!(
                !event.lowering_prefix_bytes().is_empty(),
                "event '{}' must expose lowering prefix bytes",
                event.as_str()
            );
            assert!(
                !event.lowering_suffix_bytes().is_empty(),
                "event '{}' must expose lowering suffix bytes",
                event.as_str()
            );
            assert!(
                !event.lowering_semantics().is_empty(),
                "event '{}' must expose lowering semantics tags",
                event.as_str()
            );
        }
    }

