    #[test]
    fn ensure_output_parent_dir_creates_missing_nested_directories() {
        let base = make_temp_path("output_parent", "dir");
        let nested = base.join("deep").join("artifact.sov");
        if base.exists() {
            std::fs::remove_dir_all(&base).expect("preexisting temp base must be removable");
        }
        ensure_output_parent_dir(
            nested
                .to_str()
                .expect("temp nested path must be representable as utf-8"),
        )
        .expect("output parent directories must be created");
        let parent = nested.parent().expect("nested path must have parent");
        assert!(
            parent.exists() && parent.is_dir(),
            "nested parent directory must exist after ensure_output_parent_dir"
        );
        std::fs::remove_dir_all(&base).expect("temp base must be removable");
    }

