    fn nide_diagnostics_report_surfaces_sema_failure() {
        let src = std::fs::read_to_string(fixture_path("root_at", "root_at_missing_final_fail.n"))
            .expect("fixture must read");
        let report = build_nide_diagnostics_report("root_at_missing_final_fail.n", &src);
        let status = report
            .get("status")
            .and_then(|v| v.as_str())
            .expect("diagnostics report should expose status");
        assert_eq!(status, "error");
        let phase = report
            .get("phase")
            .and_then(|v| v.as_str())
            .expect("diagnostics report should expose phase");
        assert_eq!(phase, "sema");
        let errors = report
            .get("errors")
            .and_then(|v| v.as_array())
            .expect("diagnostics report should expose errors");
        assert!(
            !errors.is_empty(),
            "expected sema failure to produce errors"
        );
        let entries = report
            .get("error_entries")
            .and_then(|v| v.as_array())
            .expect("diagnostics report should expose structured error entries");
        assert!(!entries.is_empty(), "expected structured sema diagnostics");
        let first = &entries[0];
        assert_eq!(first.get("phase").and_then(|v| v.as_str()), Some("sema"));
    }

