    #[test]
    fn emit_elf_rejects_deferred_high_level_function_bodies() {
        let ast = parse_fixture("root_at", "root_at_mature_suite_ok.n");
        let object = emit_backend_object_ir_from_ast_with_profile(
            &ast,
            ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
        )
        .expect("backend object IR must expose deferred text before serialization");
        let deferred = object
            .sections
            .iter()
            .find(|section| {
                section.kind == ncc_ir::BackendObjectSectionKindIR::Text && section.bytes.is_none()
            })
            .expect("mature root fixture must retain at least one deferred high-level body");
        let err = emit_elf_from_ast(&ast)
            .expect_err("ELF emission must not replace deferred function bodies with ret stubs");
        let message = err.to_string();
        assert!(message.contains("has no native bytes"), "{message}");
        assert!(message.contains(&deferred.name), "{message}");
        assert!(message.contains(&deferred.unit), "{message}");
    }

