#[cfg(test)]
mod runtime_heap_event_validation_tests {
    use super::*;

    #[test]
    fn heap_address_reservation_is_sized_aligned_and_failure_atomic() {
        let mut state = ExecState::default();
        let first = next_heap_addr(&mut state, 1).expect("first allocation");
        let second = next_heap_addr(&mut state, 64).expect("second allocation");
        let third = next_heap_addr(&mut state, 7).expect("third allocation");

        assert_eq!(first, "0x1000");
        assert_eq!(second, "0x1020");
        assert_eq!(third, "0x1070");
        assert_eq!(runtime_parse_int_literal(&second).unwrap() % 16, 0);
        assert_eq!(runtime_parse_int_literal(&third).unwrap() % 16, 0);

        state.heap_next_addr = usize::MAX - 7;
        let before = state.heap_next_addr;
        let err = next_heap_addr(&mut state, 64).expect_err("address overflow must fail");
        assert!(err.to_string().contains("E_HEAP_ADDRESS_OVERFLOW_001"));
        assert_eq!(
            state.heap_next_addr, before,
            "failed allocation mutated heap"
        );
    }

    fn ev(
        event_id: usize,
        kind: HeapEventKind,
        addr: &str,
        root_addr: &str,
        parent_addr: Option<&str>,
        generation: usize,
    ) -> HeapEventRecord {
        HeapEventRecord {
            event_id,
            kind,
            actor_symbol: None,
            addr: addr.into(),
            root_addr: root_addr.into(),
            parent_addr: parent_addr.map(str::to_string),
            generation,
        }
    }

    fn block(
        addr: &str,
        root_addr: &str,
        parent_addr: Option<&str>,
        generation: usize,
        event_id: usize,
        live: bool,
        death_reason: Option<HeapDeathReason>,
        last_mutation: &str,
    ) -> HeapBlock {
        HeapBlock {
            addr: addr.into(),
            size: 64,
            live,
            zeroed: false,
            death_reason,
            origin_op: "alloc".into(),
            creator_symbol: None,
            last_binder_symbol: None,
            parent_addr: parent_addr.map(str::to_string),
            root_addr: root_addr.into(),
            lineage_path: if let Some(parent) = parent_addr {
                format!("{}->{}", parent, addr)
            } else {
                addr.into()
            },
            generation,
            event_id,
            alloc_seq: None,
            realloc_seq: None,
            free_seq: None,
            last_mutation: last_mutation.into(),
            last_actor_symbol: None,
            event_trace: vec![format!("{}#-#{}", last_mutation, event_id)],
            trace_total_len: 1,
            trace_dropped_count: 0,
        }
    }

    #[test]
    fn heap_event_validator_accepts_realloc_pair_with_same_event_id() {
        let mut state = ExecState::default();
        state.heap_events = vec![
            ev(1, HeapEventKind::Alloc, "0x1010", "0x1010", None, 0),
            ev(2, HeapEventKind::ReallocOut, "0x1010", "0x1010", None, 0),
            ev(
                2,
                HeapEventKind::ReallocIn,
                "0x1020",
                "0x1010",
                Some("0x1010"),
                1,
            ),
            ev(
                3,
                HeapEventKind::Zero,
                "0x1020",
                "0x1010",
                Some("0x1010"),
                1,
            ),
        ];
        state.heap_blocks.insert(
            "0x1010".into(),
            block(
                "0x1010",
                "0x1010",
                None,
                0,
                2,
                false,
                Some(HeapDeathReason::Reallocated),
                "realloc-out",
            ),
        );
        state.heap_blocks.insert(
            "0x1020".into(),
            block("0x1020", "0x1010", Some("0x1010"), 1, 3, true, None, "zero"),
        );

        assert!(
            validate_heap_events(&state).is_ok(),
            "expected realloc out/in pair to be a valid duplicate-id shape"
        );
    }

    #[test]
    fn heap_event_validator_rejects_duplicate_event_id_outside_realloc_pair() {
        let mut state = ExecState::default();
        state.heap_events = vec![
            ev(1, HeapEventKind::Alloc, "0x1010", "0x1010", None, 0),
            ev(1, HeapEventKind::Zero, "0x1010", "0x1010", None, 0),
        ];
        state.heap_blocks.insert(
            "0x1010".into(),
            block("0x1010", "0x1010", None, 0, 1, true, None, "alloc"),
        );

        let result = validate_heap_events(&state);
        assert!(result.is_err(), "expected duplicate non-realloc id to fail");
        let msg = result.unwrap_err();
        assert!(
            msg.contains("duplicate event_id"),
            "unexpected validator error: {}",
            msg
        );
    }

    #[test]
    fn heap_event_validator_rejects_use_after_free_sequence() {
        let mut state = ExecState::default();
        state.heap_events = vec![
            ev(1, HeapEventKind::Alloc, "0x1010", "0x1010", None, 0),
            ev(2, HeapEventKind::Free, "0x1010", "0x1010", None, 0),
            ev(3, HeapEventKind::Zero, "0x1010", "0x1010", None, 0),
        ];
        state.heap_blocks.insert(
            "0x1010".into(),
            block(
                "0x1010",
                "0x1010",
                None,
                0,
                2,
                false,
                Some(HeapDeathReason::Freed),
                "free",
            ),
        );

        let result = validate_heap_events(&state);
        assert!(result.is_err(), "expected zero after free to fail");
        let msg = result.unwrap_err();
        assert!(
            msg.contains("is not live"),
            "unexpected validator error: {}",
            msg
        );
    }

    #[test]
    fn heap_event_validator_accepts_alloc_zero_free_with_fresh_event_ids() {
        let mut state = ExecState::default();
        state.heap_events = vec![
            ev(1, HeapEventKind::Alloc, "0x1010", "0x1010", None, 0),
            ev(2, HeapEventKind::Zero, "0x1010", "0x1010", None, 0),
            ev(3, HeapEventKind::Free, "0x1010", "0x1010", None, 0),
        ];
        state.heap_blocks.insert(
            "0x1010".into(),
            block(
                "0x1010",
                "0x1010",
                None,
                0,
                3,
                false,
                Some(HeapDeathReason::Freed),
                "free",
            ),
        );

        assert!(
            validate_heap_events(&state).is_ok(),
            "expected alloc/zero/free timeline with fresh event ids to be valid"
        );
    }
}

#[cfg(test)]
mod runtime_import_alt_net_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_alt_net_connect_send_ok() {
        let src = r#"
use alt.net.core;

entry[@network] {
    stc:
        connected >> bool : false;
        listening >> bool : false;
        lastError >> str : "none";

    fn:
        public boot() -> bool {
            public:
                alt.net.core.connect("127.0.0.1", 8080);
                alt.net.core.send("payload");
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("alt.net.core connect/send should run coherently");
        assert!(matches!(result, RuntimeValue::Bool(true)));
    }

    #[test]
    fn runtime_alt_net_send_without_connect_fails_with_alt_path() {
        let src = r#"
use alt.net.core;

entry[@network] {
    stc:
        connected >> bool : false;
        listening >> bool : false;
        lastError >> str : "none";

    fn:
        public boot() -> bool {
            public:
                alt.net.core.send("payload");
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast);
        assert!(
            result.is_err(),
            "expected alt.net.core.send without connect to fail"
        );
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("alt.net.core.send requires active connection"),
            "unexpected runtime error: {}",
            msg
        );
    }

    #[test]
    fn runtime_import_path_casing_is_officialized_for_execution() {
        let src = r#"
use System.net.core;

entry[@network] {
    stc:
        connected >> bool : false;
        listening >> bool : false;
        lastError >> str : "none";

    fn:
        public boot() -> bool {
            public:
                System.net.core.connect("127.0.0.1", 8080);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("System.net.core connect should run coherently");
        assert!(matches!(result, RuntimeValue::Bool(true)));
    }

    #[test]
    fn runtime_unqualified_network_calls_resolve_from_visible_import() {
        let src = r#"
use system.net.core;

entry[@network] {
    stc:
        connected >> bool : false;
        listening >> bool : false;
        lastError >> str : "none";

    fn:
        public boot() -> bool {
            public:
                listen();
                accept();
                send("payload");
                recv();
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("network unqualified import fixture must pass sema");
        let result = run_main(&ast).expect("unqualified imported network calls should execute");
        assert!(matches!(result, RuntimeValue::Bool(true)));
    }

    #[test]
    fn runtime_legacy_family_alias_import_executes_unqualified_runtime_call() {
        let src = r#"
use runtime.format;
use runtime.output;

entry[@runtime] {
    stc:
        out >> str : "";

    to main {
        @out >> str : format("id={}", 7);
        print(@out);
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("legacy runtime.format import must pass sema");
        let result = run_main(&ast).expect("legacy runtime.format import should execute");
        assert!(
            !matches!(result, RuntimeValue::Bool(false)),
            "legacy runtime.format import must not fail runtime main result, got {:?}",
            result
        );
    }
}

