#[cfg(test)]
mod runtime_f13_security_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_security_policy_evaluate_tracks_decision_and_audit_state() {
        let src = r#"
use security.policy.strict;

securityCore[@security] {
    stc:
        defaultAction >> action : deny;
        audit >> bool : true;

    fn:
        enforce() -> bool {
            public:
                security.policy.strict.evaluate(@defaultAction);
                return true;
        }

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("security fixture must pass sema");
        let mut state = ExecState::default();
        let result = exec_function(&ast, "securityCore", "enforce", &[], &mut state)
            .expect("security policy evaluation should execute");

        assert!(matches!(result, RuntimeValue::Bool(true)));
        assert_eq!(state.security_last_action, Some(SecurityDecision::Deny));
        assert_eq!(state.security_deny_count, 1);
        assert_eq!(state.security_audit_count, 1);
    }

    #[test]
    fn runtime_security_attack_simulate_tracks_attack_and_audit_state() {
        let src = r#"
use security.intel.attack;

securityAttackLab[@security] {
    stc:
        defaultAction >> action : deny;
        audit >> bool : true;
        allowOffensive >> bool : true;

    fn:
        run() -> bool {
            public:
                security.intel.attack.simulate("mailbox");
                return true;
        }

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("security attack fixture must pass sema");
        let mut state = ExecState::default();
        let result = exec_function(&ast, "securityAttackLab", "run", &[], &mut state)
            .expect("security attack simulation should execute");

        assert!(matches!(result, RuntimeValue::Bool(true)));
        assert_eq!(state.security_attack_count, 1);
        assert_eq!(state.security_audit_count, 1);
        assert_eq!(state.security_last_attack.as_deref(), Some("mailbox"));
    }

    #[test]
    fn runtime_security_deny_enforcement_blocks_subsequent_network_send() {
        let src = r#"
use security.policy.strict;
use system.net.core;

entry[@] {
    fn:
        boot() -> bool {
            public:
                policy >> action : deny;
                system.net.core.connect("127.0.0.1", 8080);
                security.policy.strict.evaluate(@policy);
                system.net.core.send("payload");
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("root security/network enforcement fixture must pass sema");
        let result = run_main(&ast);
        assert!(
            result.is_err(),
            "deny enforcement should close network flow"
        );
        let msg = result.err().unwrap().to_string();
        assert!(
            msg.contains("system.net.core.send requires active connection"),
            "unexpected runtime error: {}",
            msg
        );
    }

    #[test]
    fn runtime_security_quarantine_and_escalate_update_counters_and_enforce_cutoff() {
        let src = r#"
use security.policy.strict;
use system.net.core;

entry[@] {
    fn:
        boot() -> bool {
            public:
                quarantinePolicy >> action : quarantine;
                escalatePolicy >> action : escalate;
                audit >> bool : true;

                system.net.core.connect("127.0.0.1", 8080);
                security.policy.strict.evaluate(@quarantinePolicy);

                system.net.core.connect("127.0.0.1", 8080);
                security.policy.strict.evaluate(@escalatePolicy);
                system.net.core.send("blocked");
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("quarantine/escalate enforcement fixture must pass sema");
        let result = run_main(&ast);
        assert!(
            result.is_err(),
            "escalate enforcement should close network flow"
        );
        let msg = result.err().unwrap().to_string();
        assert!(
            msg.contains("system.net.core.send requires active connection"),
            "unexpected runtime error: {}",
            msg
        );

        let mut state = ExecState::default();
        let exec_err = exec_function(&ast, "entry", "boot", &[], &mut state)
            .expect_err("direct execution should also fail on blocked send");
        let exec_msg = exec_err.to_string();
        assert!(
            exec_msg.contains("system.net.core.send requires active connection"),
            "unexpected runtime exec error: {}",
            exec_msg
        );
        assert_eq!(state.security_quarantine_count, 1);
        assert_eq!(state.security_escalate_count, 1);
        assert_eq!(state.security_audit_count, 2);
        assert_eq!(state.security_last_action, Some(SecurityDecision::Escalate));
    }

    #[test]
    fn runtime_security_inspect_paths_render_observable_state() {
        let src = r#"
use security.policy.strict;
use system.net.core;

entry[@] {
    fn:
        boot() -> bool {
            public:
                allowPolicy >> action : allow;
                quarantinePolicy >> action : quarantine;
                escalatePolicy >> action : escalate;
                audit >> bool : true;

                system.net.core.connect("127.0.0.1", 8080);
                security.policy.strict.evaluate(@allowPolicy);

                system.net.core.connect("127.0.0.1", 8080);
                security.policy.strict.evaluate(@quarantinePolicy);

                system.net.core.connect("127.0.0.1", 8080);
                security.policy.strict.evaluate(@escalatePolicy);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("security inspect fixture must pass sema");
        let mut state = ExecState::default();
        let result =
            exec_function(&ast, "entry", "boot", &[], &mut state).expect("runtime should execute");
        assert!(matches!(result, RuntimeValue::Bool(true)));

        let inspect = |segments: &[&str], state: &mut ExecState| -> String {
            let expr = ncc_ast::Expr::ContextRef(ncc_ast::ContextRef::plain(
                segments.iter().map(|s| (*s).to_string()).collect(),
            ));
            render_inspect(&ast, "entry", &expr, state)
        };

        assert_eq!(
            inspect(&["security", "last_action"], &mut state),
            "[inspect] security.last_action=escalate"
        );
        assert_eq!(
            inspect(&["security", "allow", "count"], &mut state),
            "[inspect] security.allow.count=1"
        );
        assert_eq!(
            inspect(&["security", "deny", "count"], &mut state),
            "[inspect] security.deny.count=0"
        );
        assert_eq!(
            inspect(&["security", "quarantine", "count"], &mut state),
            "[inspect] security.quarantine.count=1"
        );
        assert_eq!(
            inspect(&["security", "escalate", "count"], &mut state),
            "[inspect] security.escalate.count=1"
        );
        assert_eq!(
            inspect(&["security", "audit", "count"], &mut state),
            "[inspect] security.audit.count=3"
        );
        assert_eq!(
            inspect(&["security", "attack", "count"], &mut state),
            "[inspect] security.attack.count=0"
        );
        assert_eq!(
            inspect(&["security", "last_attack"], &mut state),
            "[inspect] security.last_attack=-"
        );
    }
}

#[cfg(test)]
mod runtime_f13_security_fixture_matrix_tests {
    use super::*;
    use std::path::PathBuf;

    fn fixture_path(name: &str) -> PathBuf {
        super::example_compat_path(&format!("security_at/{name}"))
    }

    fn load_program(name: &str) -> ncc_ast::Program {
        let src = std::fs::read_to_string(fixture_path(name)).expect("fixture read");
        let tokens = ncc_lexer::lex(&src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_f13_check_ok_fixtures_run_successfully() {
        for fixture in [
            "security_at_runtime_allow_ok.n",
            "security_at_runtime_inspect_paths_ok.n",
        ] {
            let ast = load_program(fixture);
            let sema = ncc_sema::analyze(&ast);
            assert!(
                sema.is_ok(),
                "expected fixture '{}' to pass sema before runtime, got {:?}",
                fixture,
                sema
            );
            let result = run_main(&ast);
            assert!(
                result.is_ok(),
                "expected fixture '{}' to run successfully, got {:?}",
                fixture,
                result
            );
        }
    }

    #[test]
    fn runtime_f13_enforcement_failures_are_observable_in_runtime() {
        let cases = [
            "security_at_runtime_deny_blocks_send_fail.n",
            "security_at_runtime_quarantine_blocks_send_fail.n",
            "security_at_runtime_escalate_blocks_send_fail.n",
        ];

        for fixture in cases {
            let ast = load_program(fixture);
            let sema = ncc_sema::analyze(&ast);
            assert!(
                sema.is_ok(),
                "expected fixture '{}' to pass sema before runtime, got {:?}",
                fixture,
                sema
            );
            let result = run_main(&ast);
            assert!(
                result.is_err(),
                "expected fixture '{}' to fail in runtime by enforcement",
                fixture
            );
            let msg = result.err().unwrap().to_string();
            assert!(
                msg.contains("system.net.core.send requires active connection"),
                "fixture '{}' expected connection enforcement diagnostic, got {:?}",
                fixture,
                msg
            );
        }
    }

    #[test]
    fn runtime_f13_check_fail_fixtures_stay_blocked_by_sema() {
        let cases = [
            (
                "security_at_attack_import_without_lab_fail.n",
                "SEC047: offensive security imports require 'allowOffensive >> bool : true' in [@security] stc",
            ),
            (
                "security_at_inspect_contract_missing_import_fail.n",
                "requires security runtime contract import",
            ),
        ];

        for (fixture, expected) in cases {
            let ast = load_program(fixture);
            let sema = ncc_sema::analyze(&ast);
            assert!(sema.is_err(), "expected fixture '{}' to fail sema", fixture);
            let msg = sema.err().unwrap();
            assert!(
                msg.contains(expected),
                "fixture '{}' expected diagnostic containing {:?}, got {:?}",
                fixture,
                expected,
                msg
            );
        }
    }
}

