#[cfg(test)]
mod runtime_f15_system_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_system_service_flow_updates_observable_state_and_inspect_paths() {
        let src = r#"
use system.service.core;
use system.proc.core;
use system.io.core;

entry[@system] {
    stc:
        systemOpen >> bool : false;
        healthy >> bool : true;
        degraded >> bool : false;
        lastEvent >> str : "boot";

    fn:
        boot() -> bool {
            public:
                register("auth");
                open("auth");
                spawn("auth-worker");
                write("auth-online");
                wait();
                degrade("auth-down");
                recover("auth-up");
                reconcile();
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("system fixture must pass sema");
        let mut state = ExecState::default();
        let result = exec_function(&ast, "entry", "boot", &[], &mut state)
            .expect("system service runtime flow must execute");

        assert!(matches!(result, RuntimeValue::Bool(true)));
        assert!(state.system_open);
        assert!(state.system_healthy);
        assert!(!state.system_degraded);
        assert!(state.system_recovered);
        assert!(!state.system_waiting);
        assert_eq!(state.system_services.len(), 1);
        assert_eq!(state.system_events.len(), 8);
        assert_eq!(state.system_last_service.as_deref(), Some("auth-worker"));
        assert_eq!(
            state.system_last_event.as_deref(),
            Some("reconcile:healthy")
        );

        let inspect = |segments: &[&str], state: &mut ExecState| -> String {
            let expr = ncc_ast::Expr::ContextRef(ncc_ast::ContextRef::plain(
                segments.iter().map(|s| (*s).to_string()).collect(),
            ));
            render_inspect(&ast, "entry", &expr, state)
        };

        assert_eq!(
            inspect(&["system", "open"], &mut state),
            "[inspect] system.open=true"
        );
        assert_eq!(
            inspect(&["system", "healthy"], &mut state),
            "[inspect] system.healthy=true"
        );
        assert_eq!(
            inspect(&["system", "degraded"], &mut state),
            "[inspect] system.degraded=false"
        );
        assert_eq!(
            inspect(&["system", "recovered"], &mut state),
            "[inspect] system.recovered=true"
        );
        assert_eq!(
            inspect(&["system", "events", "count"], &mut state),
            "[inspect] system.events.count=8"
        );
        assert_eq!(
            inspect(&["system", "services", "count"], &mut state),
            "[inspect] system.services.count=1"
        );
        assert_eq!(
            inspect(&["system", "last_event"], &mut state),
            "[inspect] system.last_event=reconcile:healthy"
        );
        assert_eq!(
            inspect(&["system", "last_service"], &mut state),
            "[inspect] system.last_service=auth-worker"
        );
    }

    #[test]
    fn runtime_system_service_open_requires_registered_service() {
        let src = r#"
use system.service.core;

entry[@system] {
    stc:
        systemOpen >> bool : false;
        healthy >> bool : true;
        degraded >> bool : false;
        lastEvent >> str : "boot";

    fn:
        boot() -> bool {
            public:
                open("orphan");
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("runtime failure fixture must pass sema first");
        let result = run_main(&ast);
        assert!(result.is_err(), "open without registration must fail");
        let msg = result.err().unwrap().to_string();
        assert!(
            msg.contains("system.service.core.open requires registered service 'orphan'"),
            "unexpected runtime diagnostic: {}",
            msg
        );
    }
}

