        let src = r#"
use tooling.build.core;
use tooling.lint.core;
use tooling.fmt.core;
use tooling.pkg.core;

entry[@tooling] {
    stc:
        buildReady >> bool : false;
        lintReady >> bool : false;
        formatReady >> bool : false;
        packageReady >> bool : false;
        publishReady >> bool : false;
        lastArtifact >> str : "none";

    fn:
        boot() -> bool {
            public:
                plan("workspace");
                apply("workspace");
                tooling.lint.core.run("workspace");
                tooling.fmt.core.run("workspace");
                tooling.pkg.core.pack("workspace");
                tooling.pkg.core.publish("workspace");
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("tooling fixture must pass sema");
        let mut state = ExecState::default();
