#[cfg(test)]
mod runtime_f18_kernel_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_kernel_flow_updates_observable_state_and_inspect_paths() {
        let src = r#"
use kernel.task.core;
use kernel.schedule.core;
use kernel.control.core;

entry[@kernel] {
    stc:
        schedulerOpen >> bool : false;
        panicState >> bool : false;
        quarantineCount >> int : 0;
        lastTask >> str : "none";
        lastEvent >> str : "boot";

    fn:
        boot() -> bool {
            public:
                register(7, "idle");
                open();
                next();
                quarantine(7);
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("kernel fixture must pass sema");
        let mut state = ExecState::default();
        let result = exec_function(&ast, "entry", "boot", &[], &mut state).expect("kernel runtime");
        assert!(matches!(result, RuntimeValue::Bool(true)));

        assert!(state.kernel_scheduler_open);
        assert!(!state.kernel_panic_state);
        assert_eq!(state.kernel_quarantine_count, 1);
        assert_eq!(state.kernel_events.len(), 4);
        assert_eq!(state.kernel_last_task.as_deref(), Some("pid:7"));
        assert_eq!(state.kernel_last_event.as_deref(), Some("quarantine:7"));

        let inspect = |segments: &[&str], state: &mut ExecState| -> String {
            let expr = ncc_ast::Expr::ContextRef(ncc_ast::ContextRef::plain(
                segments.iter().map(|s| (*s).to_string()).collect(),
            ));
            render_inspect(&ast, "entry", &expr, state)
        };

        assert_eq!(
            inspect(&["kernel", "scheduler", "open"], &mut state),
            "[inspect] kernel.scheduler.open=true"
        );
        assert_eq!(
            inspect(&["kernel", "panic", "state"], &mut state),
            "[inspect] kernel.panic.state=false"
        );
        assert_eq!(
            inspect(&["kernel", "quarantine", "count"], &mut state),
            "[inspect] kernel.quarantine.count=1"
        );
        assert_eq!(
            inspect(&["kernel", "events", "count"], &mut state),
            "[inspect] kernel.events.count=4"
        );
        assert_eq!(
            inspect(&["kernel", "last_task"], &mut state),
            "[inspect] kernel.last_task=pid:7"
        );
        assert_eq!(
            inspect(&["kernel", "last_event"], &mut state),
            "[inspect] kernel.last_event=quarantine:7"
        );
    }

    #[test]
    fn runtime_kernel_panic_disables_scheduler_and_blocks_next() {
        let src = r#"
use kernel.schedule.core;
use kernel.control.core;

entry[@kernel] {
    stc:
        schedulerOpen >> bool : false;
        panicState >> bool : false;
        quarantineCount >> int : 0;
        lastTask >> str : "none";
        lastEvent >> str : "boot";

    fn:
        boot() -> bool {
            public:
                open();
                panic("fatal");
                return true;
        }

        afterPanic() -> bool {
            public:
                open();
                next();
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("panic fixture must pass sema");

        let mut state = ExecState::default();
        let boot_result =
            exec_function(&ast, "entry", "boot", &[], &mut state).expect("boot must execute");
        assert!(matches!(boot_result, RuntimeValue::Bool(true)));
        assert!(state.kernel_panic_state);
        assert!(!state.kernel_scheduler_open);

        let after = exec_function(&ast, "entry", "afterPanic", &[], &mut state);
        assert!(after.is_err(), "next after panic must fail at runtime");
        let msg = after.err().unwrap().to_string();
        assert!(
            msg.contains("kernel.schedule.core.open requires non-panic kernel state"),
            "unexpected runtime diagnostic: {}",
            msg
        );
    }

    #[test]
    fn runtime_kernel_profile_normal_n_without_imports_executes() {
        let src = r#"
entry[@] {
    stc:
        schedulerOpen >> bool : false;
        panicState >> bool : false;
        quarantineCount >> int : 0;
        lastTask >> str : "none";
        lastEvent >> str : "boot";

    fn:
        boot() -> bool {
            public:
                register(7, "idle");
                open();
                next();
                quarantine(7);
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("kernel profile .n fixture must pass sema");

        let mut state = ExecState::default();
        let result =
            exec_function(&ast, "entry", "boot", &[], &mut state).expect("kernel profile runtime");
        assert!(matches!(result, RuntimeValue::Bool(true)));
        assert!(state.kernel_scheduler_open);
        assert!(!state.kernel_panic_state);
        assert_eq!(state.kernel_quarantine_count, 1);
        assert_eq!(state.kernel_events.len(), 4);
        assert_eq!(state.kernel_last_task.as_deref(), Some("pid:7"));
        assert_eq!(state.kernel_last_event.as_deref(), Some("quarantine:7"));
    }
}

