#[cfg(test)]
mod runtime_f19_ai_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_ai_flow_updates_observable_state_and_inspect_paths() {
        let src = r#"
use ai.session.core;
use ai.model.core;
use ai.agent.core;
use ai.chat.core;
use ai.memory.core;

entry[@ai] {
    stc:
        sessionActive >> bool : false;
        modelReady >> bool : false;
        plannerReady >> bool : false;
        criticReady >> bool : false;
        executorReady >> bool : false;
        memoryCount >> int : 0;
        lastProvider >> str : "none";
        lastModel >> str : "none";
        lastGoal >> str : "none";
        lastPrompt >> str : "none";
        lastResponse >> str : "none";

    fn:
        boot() -> bool {
            public:
                open("assistant");
                select("openai", "gpt-5.5");
                plan("assist-user");
                critique("policy-check");
                execute("respond");
                @lastResponse >> str : complete("hola");
                remember("memo", @lastResponse);
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("ai fixture must pass sema");
        let mut state = ExecState::default();
        let result = exec_function(&ast, "entry", "boot", &[], &mut state).expect("ai runtime");
        assert!(matches!(result, RuntimeValue::Bool(true)));

        assert!(state.ai_session_active);
        assert!(state.ai_model_ready);
        assert!(state.ai_planner_ready);
        assert!(state.ai_critic_ready);
        assert!(state.ai_executor_ready);
        assert_eq!(state.ai_memory_count, 1);
        assert_eq!(state.ai_last_provider.as_deref(), Some("openai"));
        assert_eq!(state.ai_last_model.as_deref(), Some("gpt-5.5"));
        assert_eq!(state.ai_last_goal.as_deref(), Some("assist-user"));
        assert_eq!(state.ai_last_prompt.as_deref(), Some("hola"));
        assert_eq!(
            state.ai_last_response.as_deref(),
            Some("[openai:gpt-5.5] hola")
        );

        let inspect = |segments: &[&str], state: &mut ExecState| -> String {
            let expr = ncc_ast::Expr::ContextRef(ncc_ast::ContextRef::plain(
                segments.iter().map(|s| (*s).to_string()).collect(),
            ));
            render_inspect(&ast, "entry", &expr, state)
        };

        assert_eq!(
            inspect(&["ai", "session", "active"], &mut state),
            "[inspect] ai.session.active=true"
        );
        assert_eq!(
            inspect(&["ai", "model", "ready"], &mut state),
            "[inspect] ai.model.ready=true"
        );
        assert_eq!(
            inspect(&["ai", "planner", "ready"], &mut state),
            "[inspect] ai.planner.ready=true"
        );
        assert_eq!(
            inspect(&["ai", "critic", "ready"], &mut state),
            "[inspect] ai.critic.ready=true"
        );
        assert_eq!(
            inspect(&["ai", "executor", "ready"], &mut state),
            "[inspect] ai.executor.ready=true"
        );
        assert_eq!(
            inspect(&["ai", "memory", "count"], &mut state),
            "[inspect] ai.memory.count=1"
        );
        assert_eq!(
            inspect(&["ai", "last_provider"], &mut state),
            "[inspect] ai.last_provider=openai"
        );
        assert_eq!(
            inspect(&["ai", "last_response"], &mut state),
            "[inspect] ai.last_response=[openai:gpt-5.5] hola"
        );
    }

    #[test]
    fn runtime_ai_complete_requires_non_empty_prompt() {
        let src = r#"
use ai.session.core;
use ai.model.core;
use ai.chat.core;

entry[@ai] {
    stc:
        sessionActive >> bool : false;
        modelReady >> bool : false;
        plannerReady >> bool : false;
        criticReady >> bool : false;
        executorReady >> bool : false;
        memoryCount >> int : 0;
        lastProvider >> str : "none";
        lastModel >> str : "none";
        lastGoal >> str : "none";
        lastPrompt >> str : "none";
        lastResponse >> str : "none";

    fn:
        boot() -> bool {
            public:
                open("assistant");
                select("openai", "gpt-5.5");
                complete("");
                return true;
        }

    ref main ->> @fn(boot);

    final:
        return true;
}
"#;
        let ast = parse_src(src);
        ncc_sema::analyze(&ast).expect("runtime failure fixture must pass sema first");
        let result = run_main(&ast);
        assert!(result.is_err(), "empty prompt must fail at runtime");
        let msg = result.err().unwrap().to_string();
        assert!(
            msg.contains("ai.chat.core.complete requires non-empty prompt:str"),
            "unexpected runtime diagnostic: {}",
            msg
        );
    }
}

