#[cfg(test)]
mod runtime_main_entry_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_single_profiled_main_runs_without_explicit_profile() {
        let src = r#"
profiled[@] {
    to main@<secure.boot> {
        return true;
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("single profiled main should run by default");
        assert!(matches!(result, RuntimeValue::Bool(true)));
    }

    #[test]
    fn runtime_multiple_profiled_main_without_profile_fails() {
        let src = r#"
profiled[@] {
    to main@<safe> {
        return true;
    }

    to main@<fast> {
        return false;
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast);
        assert!(
            result.is_err(),
            "multiple profiled main entries without requested profile must fail"
        );
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("multiple profiled main entries found; select a profile explicitly"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn runtime_profiled_main_selection_picks_requested_profile() {
        let src = r#"
profiled[@] {
    to main@<safe> {
        return true;
    }

    to main@<fast> {
        return false;
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main_with_profile(&ast, Some("fast"))
            .expect("requested profile must pick matching main entry");
        assert!(matches!(result, RuntimeValue::Bool(false)));
    }

    #[test]
    fn runtime_profiled_main_selection_fails_when_profile_missing() {
        let src = r#"
profiled[@] {
    to main@<safe> {
        return true;
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main_with_profile(&ast, Some("fast"));
        assert!(
            result.is_err(),
            "missing requested profile should fail with official diagnostic"
        );
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("requested profile 'fast' has no valid main entry"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn runtime_to_main_non_integer_number_return_fails_main_contract() {
        let src = r#"
entry[@] {
    to main {
        return 3.14;
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast);
        assert!(result.is_err(), "non-integer return in main must fail");
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("entry target has invalid return contract for to main"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn runtime_to_main_string_return_fails_main_contract() {
        let src = r#"
entry[@] {
    to main {
        return "done";
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast);
        assert!(result.is_err(), "string return in main must fail");
        let msg = result.unwrap_err().to_string();
        assert!(
            msg.contains("entry target has invalid return contract for to main"),
            "unexpected error: {}",
            msg
        );
    }

    #[test]
    fn runtime_to_main_void_return_is_valid_contract() {
        let src = r#"
entry[@] {
    to main {
        print("boot");
    }

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("void main should be valid");
        assert!(matches!(result, RuntimeValue::Void));
    }

    #[test]
    fn runtime_ref_main_int_return_is_valid_contract() {
        let src = r#"
entry[@] {
    fn:
        boot() -> int {
            public:
                return 7;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("int-returning main target should be valid");
        assert!(matches!(result, RuntimeValue::Number(ref n) if n == "7"));
    }

    #[test]
    fn runtime_ref_main_direct_qualified_path_executes_target_function() {
        let src = r#"
worker[@] {
    fn:
        public boot() -> bool {
            public:
                return true;
        }

    fa:
        return true;
}

entry[@] {
    ref main ->> worker.boot;

    fa:
        return false;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("direct path ref main should execute target function");
        assert!(matches!(result, RuntimeValue::Bool(true)));
    }

    #[test]
    fn runtime_ref_main_direct_import_path_executes_runtime_import_call() {
        let src = r#"
use system.proc.core;

entry[@system] {
    ref main ->> system.proc.core.wait;

    fa:
        return false;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast)
            .expect("direct import path ref main should execute imported runtime call");
        assert!(matches!(result, RuntimeValue::Bool(true)));
    }
}

