    #[test]
    fn stdlib_model_manifest_contains_time_trace_and_inspect_contracts() {
        let model = build_runtime_stdlib_manifest();
        let contracts = model
            .get("contracts")
            .and_then(|v| v.as_object())
            .expect("stdlib model must expose contracts object");

        let time_api = contracts
            .get("time")
            .and_then(|v| v.get("stable_api"))
            .and_then(|v| v.as_array())
            .expect("time contract must expose stable_api array");
        assert!(
            time_api
                .iter()
                .any(|v| v.as_str() == Some("runtime.time.now()->int")),
            "time contract must include runtime.time.now()->int"
        );
        assert!(
            time_api
                .iter()
                .any(|v| v.as_str() == Some("runtime.time.monotonic()->int")),
            "time contract must include runtime.time.monotonic()->int"
        );
        assert!(
            time_api
                .iter()
                .any(|v| v.as_str() == Some("runtime.time.sleep(int)->bool")),
            "time contract must include runtime.time.sleep(int)->bool"
        );
    }

