        run_stdlib_model_command(&[]).expect("stdlib-model default mode must pass");
        run_stdlib_model_command(&["--json".into()]).expect("stdlib-model --json mode must pass");
        run_stdlib_model_command(&["--list".into()]).expect("stdlib-model --list mode must pass");
