    #[test]
    fn mct_cli_emit_llvm_writes_debug_dwarf_metadata() {
        let tmp = workspace_repo_root()
            .join("target")
            .join("tmp")
            .join("mct-cli-test");
        fs::create_dir_all(&tmp).expect("test temp dir must be creatable");
        let fixture = tmp.join("llvm_cli_debug_dwarf_fixture.n");
        fs::write(
            &fixture,
            r#"llvmCliDebugDwarfFixture {
    stc:
        x: int;
        y: int;

    fn:
        boot() -> int {
            public:
                @x >> int : 40;
                @y >> int : @x + 2;
                return @y;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#,
        )
        .expect("test fixture must be writable");
        let out = tmp.join("llvm_cli_debug_dwarf_fixture.ll");
        run_mct_command(&[
            "emit-llvm".into(),
            fixture.to_string_lossy().into_owned(),
            "--out".into(),
            out.to_string_lossy().into_owned(),
            "--cc".into(),
            "nC.sysv64".into(),
            "--opt-level".into(),
            "2".into(),
        ])
        .expect("mct emit-llvm must pass on debug DWARF fixture");
        let text = fs::read_to_string(&out).expect("LLVM IR output must be readable");
        assert!(text.contains("!DICompileUnit"));
        assert!(text.contains("!DISubprogram"));
        assert!(text.contains("!DILocation"));
        assert!(text.contains("llvm.dbg.declare"));
        assert!(text.contains("Dwarf Version"));

        let parsed = load_ast_from_path(&fixture.to_string_lossy())
            .expect("fixture must load through the parser pipeline");
        sema_check_with_warnings(&parsed).expect("fixture must pass sema");
        let source = fs::read_to_string(&fixture).expect("fixture source must be readable");
        let ir = ncc_ir::lower_with_backend_profile_and_source(
            parsed,
            ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
            fixture.to_string_lossy(),
            &source,
        );
        let module = ncc_ir::mct_emit_llvm_module_with_debug_config(
            &ir,
            ncc_ir::mct_llvm_pass_pipeline(ncc_ir::MctLlvmOptimizationLevelIR::O2),
            mct_llvm_debug_config_for_path(&fixture.to_string_lossy()),
        );
        let json = mct_llvm_module_to_json(&module, false, Some(&out));
        assert_eq!(
            json.get("debug_metadata")
                .and_then(|value| value.get("status"))
                .and_then(|value| value.as_str()),
            Some("mct_llvm_debug_metadata_dwarf_closed")
        );
        assert_eq!(
            json.get("source_map")
                .and_then(|value| value.get("status"))
                .and_then(|value| value.as_str()),
            Some("exact_source_span_parity")
        );
        assert_eq!(
            json.get("debug_metadata")
                .and_then(|value| value.get("source_span_parity"))
                .and_then(|value| value.as_bool()),
            Some(true)
        );
        assert_eq!(
            json.get("debug_metadata")
                .and_then(|value| value.get("enabled"))
                .and_then(|value| value.as_bool()),
            Some(true)
        );
    }

