    #[test]
    fn mct_cli_emit_llvm_reports_construct_coverage() {
        let tmp = workspace_repo_root()
            .join("target")
            .join("tmp")
            .join("mct-cli-test");
        fs::create_dir_all(&tmp).expect("test temp dir must be creatable");
        let fixture = tmp.join("llvm_cli_construct_coverage_fixture.n");
        fs::write(
            &fixture,
            r#"llvmCliConstructCoverageFixture {
    type:
        Mode enum {
            Ready;
            Done;
        }

    fn:
        boot() -> int {
            public:
                @values >> array<int, 2> : [1, 2];
                return @values[0];
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#,
        )
        .expect("test fixture must be writable");
        let out = tmp.join("llvm_cli_construct_coverage_fixture.ll");
        run_mct_command(&[
            "emit-llvm".into(),
            fixture.to_string_lossy().into_owned(),
            "--out".into(),
            out.to_string_lossy().into_owned(),
            "--json".into(),
            "--cc".into(),
            "nC.sysv64".into(),
        ])
        .expect("mct emit-llvm must report construct coverage even with enum gap");

        let parsed = load_ast_from_path(&fixture.to_string_lossy())
            .expect("fixture must load through the parser pipeline");
        sema_check_with_warnings(&parsed).expect("fixture must pass sema");
        let ir = ncc_ir::lower_with_backend_profile(
            parsed,
            ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
        );
        let module = ncc_ir::mct_emit_llvm_module(&ir);
        let json = mct_llvm_module_to_json(&module, false, Some(&out));
        let coverage = json
            .get("construct_coverage")
            .expect("construct coverage JSON must be present");
        assert_eq!(
            coverage.get("schema").and_then(|value| value.as_str()),
            Some("nc.mct.llvm.construct_coverage.v1")
        );
        assert_eq!(
            coverage.get("status").and_then(|value| value.as_str()),
            Some("llvm_construct_coverage_closed")
        );
        assert_eq!(
            coverage
                .get("present_not_represented_count")
                .and_then(|value| value.as_u64()),
            Some(0)
        );
        let rows = coverage
            .get("rows")
            .and_then(|value| value.as_array())
            .expect("construct coverage rows must be present");
        assert!(rows.iter().any(|row| {
            row.get("construct").and_then(|value| value.as_str()) == Some("type.enum")
                && row.get("status").and_then(|value| value.as_str()) == Some("represented")
                && row
                    .get("present_in_module")
                    .and_then(|value| value.as_bool())
                    == Some(true)
        }));
        assert!(rows.iter().any(|row| {
            row.get("construct").and_then(|value| value.as_str()) == Some("statement.scalar_return")
                && row.get("status").and_then(|value| value.as_str()) == Some("represented")
        }));
    }

    #[test]
    fn mct_cli_json_reports_surface_descriptor_bytes() {
        let tmp = workspace_repo_root()
            .join("target")
            .join("tmp")
            .join("mct-cli-test");
        fs::create_dir_all(&tmp).expect("test temp dir must be creatable");
        let fixture = tmp.join("mct_cli_surface_descriptor_fixture.n");
        fs::write(
            &fixture,
            r#"mctCliSurfaceDescriptorFixture[@runtime] {
    stc:
        first: int;
        strictly locked: int;

    fn:
        public:
            run() -> bool {
                @first >> int : 7;
                return true;
            }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#,
        )
        .expect("test fixture must be writable");

        run_mct_command(&[
            "translate".into(),
            fixture.to_string_lossy().into_owned(),
            "--json".into(),
        ])
        .expect("mct translate --json must accept surface descriptor fixture");

        let parsed = load_ast_from_path(&fixture.to_string_lossy())
            .expect("fixture must load through the parser pipeline");
        sema_check_with_warnings(&parsed).expect("fixture must pass sema");
        let ir = ncc_ir::lower_with_backend_profile(
            parsed,
            ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
        );
        let report = ncc_ir::mct_translate_program(&ir);
        let json = mct_report_to_json(&report);
        assert!(
            json.get("surface_descriptor_count")
                .and_then(|value| value.as_u64())
                .unwrap_or_default()
                > 0
        );
        assert!(
            json.get("surface_descriptor_bytes")
                .and_then(|value| value.as_u64())
                .unwrap_or_default()
                > 0
        );
        let descriptors = json
            .get("surface_descriptors")
            .and_then(|value| value.as_array())
            .expect("surface descriptors must be serialized");
        for construct in [
            "section.stc",
            "stc.symbol",
            "section.fn",
            "function.fn",
            "visibility.public",
            "modifier.strictly",
        ] {
            assert!(
                descriptors.iter().any(|descriptor| {
                    descriptor.get("construct").and_then(|value| value.as_str()) == Some(construct)
                }),
                "missing {construct}"
            );
        }
        assert!(descriptors.iter().any(|descriptor| {
            descriptor
                .get("bytes_hex")
                .and_then(|value| value.as_str())
                .is_some_and(|bytes_hex| bytes_hex.starts_with("4e435344"))
                && descriptor
                    .get("fingerprint")
                    .and_then(|value| value.as_str())
                    .is_some_and(|fingerprint| fingerprint.len() == 16)
        }));
    }

    #[test]
    fn mct_cli_llvm_toolchain_matrix_manifest_covers_f6_tools() {
        let manifest = mct_llvm_toolchain_matrix_manifest();
        assert_eq!(
            manifest.get("status").and_then(|value| value.as_str()),
            Some("mct_llvm_toolchain_matrix_defined")
        );
        let pipeline = manifest
            .get("pipeline")
            .and_then(|value| value.as_array())
            .expect("F6 pipeline must be present");
        for stage in ["llvm-as", "opt", "llc", "lld-compatible-link"] {
            assert!(
                pipeline.iter().any(|value| value.as_str() == Some(stage)),
                "F6 pipeline missing {stage}"
            );
        }
        let tools = manifest
            .get("tools")
            .and_then(|value| value.as_array())
            .expect("F6 tool manifest must be present");
        for tool in [
            "llvm-as", "opt", "llc", "ld.lld", "lld-link", "ld64.lld", "wasm-ld",
        ] {
            assert!(
                tools
                    .iter()
                    .any(|row| row.get("stage").and_then(|value| value.as_str()) == Some(tool)),
                "F6 tool manifest missing {tool}"
            );
        }
        let profiles = manifest
            .get("profiles")
            .and_then(|value| value.as_array())
            .expect("F6 profile matrix must be present");
        assert!(
            profiles.len() >= 4,
            "F6 must cover sysv64, win64, aapcs64 and portable LLVM lanes"
        );
        assert_eq!(
            manifest
                .get("truth_boundary")
                .and_then(|value| value.get("missing_tools_are_not_counted_as_pass"))
                .and_then(|value| value.as_bool()),
            Some(true)
        );
    }

