    #[test]
    fn mct_cli_emit_llvm_lowers_dinarray_growth_api() {
        let tmp = workspace_repo_root()
            .join("target")
            .join("tmp")
            .join("mct-cli-test");
        fs::create_dir_all(&tmp).expect("test temp dir must be creatable");
        let source_fixture = example_compat_path("backend/mct_llvm_dinarray_growth.n");
        let source = fs::read_to_string(&source_fixture).expect("growth fixture must read");
        let fixture = tmp.join("mct_llvm_dinarray_growth_raw.n");
        fs::write(
            &fixture,
            format!("package dinarray_growth {{ profile: raw; }}\n{source}"),
        )
        .expect("raw growth fixture must be writable");
        let out = tmp.join("mct_llvm_dinarray_growth.ll");
        run_mct_command(&[
            "emit-llvm".into(),
            fixture.to_string_lossy().into_owned(),
            "--out".into(),
            out.to_string_lossy().into_owned(),
            "--cc".into(),
            "nC.sysv64".into(),
        ])
        .expect("mct emit-llvm must pass on dinArray growth fixture");
        let text = fs::read_to_string(&out).expect("LLVM IR output must be readable");
        assert!(text.contains("%nC.dinarray_i32 = type { ptr, i64, i64 }"));
        assert!(text.contains("declare ptr @malloc(i64)"));
        assert!(text.contains("declare ptr @realloc(ptr, i64)"));
        assert!(text.contains("declare void @free(ptr)"));
        assert!(
            !text.contains("call ptr @malloc"),
            "raw dinArray reservation must not perform an additional hidden allocation"
        );
        assert!(text.contains("call ptr @realloc"));
        assert!(
            !text.contains("alloca i8, i64"),
            "dinArray growth must be heap-backed"
        );
        assert!(
            !text.contains("dinarray_push_grow"),
            "raw push must never synthesize a growth branch"
        );
        assert!(text.contains("dinarray_pop_value"));
        assert!(text.contains("load i64"));
        assert!(text.contains("store i64"));

        let manifest = build_mct_contract_manifest_json();
        let not_claimed = manifest
            .get("llvm_adapter")
            .and_then(|value| value.get("not_yet_claimed"))
            .and_then(|value| value.as_array())
            .expect("not_yet_claimed must be present");
        assert!(
            !not_claimed.iter().any(|value| value.as_str()
                == Some("complete dynamic array grow/realloc/push/pop runtime API")),
            "F7 removes the dinArray growth API gap from the MCT manifest"
        );
        assert!(
            !not_claimed.iter().any(|value| value.as_str()
                == Some("complete cross-target dynamic descriptor ABI closure")),
            "F7 removes the hosted dinArray descriptor ABI gap from the MCT manifest"
        );
        let descriptor_abi = manifest
            .get("dinarray_descriptor_abi")
            .expect("dinArray descriptor ABI manifest must be present");
        assert_eq!(
            descriptor_abi
                .get("status")
                .and_then(|value| value.as_str()),
            Some("closed_for_hosted_64_bit_targets")
        );
        assert_eq!(
            descriptor_abi
                .get("descriptor")
                .and_then(|value| value.get("official_llvm_type"))
                .and_then(|value| value.as_str()),
            Some("%nC.dinarray_<element> = type { ptr, i64, i64 }")
        );
        assert_eq!(
            descriptor_abi
                .get("descriptor")
                .and_then(|value| value.get("descriptor_size_bytes"))
                .and_then(|value| value.as_u64()),
            Some(24)
        );
        let closed_profiles = descriptor_abi
            .get("closed_profiles")
            .and_then(|value| value.as_array())
            .expect("dinArray descriptor ABI must list closed profiles");
        for expected in ["nC.sysv64", "nC.win64", "nC.aapcs64"] {
            assert!(
                closed_profiles.iter().any(|profile| {
                    profile.get("id").and_then(|value| value.as_str()) == Some(expected)
                        && profile.get("status").and_then(|value| value.as_str()) == Some("closed")
                }),
                "missing closed dinArray descriptor ABI profile {expected}"
            );
        }
        assert_eq!(
            manifest
                .get("truth_boundary")
                .and_then(|value| value.get("full_llvm_parity"))
                .and_then(|value| value.as_bool()),
            Some(false),
            "F7 must not claim total LLVM parity"
        );
    }

