#[cfg(test)]
#[cfg(not(ncc_public_beta))]
mod release_train_model_cli_tests {
    use super::*;

    #[test]
    fn release_train_model_manifest_contains_channels_and_governance_blocks() {
        let model = build_release_train_model_manifest();
        assert_eq!(
            model.get("version").and_then(|v| v.as_str()),
            Some("1.0.1"),
            "release-train model version must be 1.0.1"
        );
        assert_eq!(
            model.get("state").and_then(|v| v.as_str()),
            Some("frozen"),
            "release-train model must be frozen"
        );
        assert_eq!(
            model.get("phase").and_then(|v| v.as_str()),
            Some("phase9_governance_release"),
            "release-train model must bind to phase9_governance_release"
        );

        let channels = model
            .get("release_train")
            .and_then(|v| v.get("channels"))
            .and_then(|v| v.as_array())
            .expect("release-train model must expose release_train.channels array");
        for channel in ["stable", "beta", "nightly"] {
            assert!(
                channels
                    .iter()
                    .any(|row| row.get("name").and_then(|v| v.as_str()) == Some(channel)),
                "release-train model must include channel '{}'",
                channel
            );
        }
        assert!(
            model.get("governance").is_some(),
            "release-train model must expose governance object"
        );
        assert!(
            model.get("operations_hardening").is_some(),
            "release-train model must expose operations_hardening object"
        );
    }

    #[test]
    fn release_train_model_cli_command_accepts_json_and_list_modes() {
        run_release_train_model_command(&[]).expect("release-train-model default mode must pass");
        run_release_train_model_command(&["--json".into()])
            .expect("release-train-model --json mode must pass");
        run_release_train_model_command(&["--list".into()])
            .expect("release-train-model --list mode must pass");
    }

    #[test]
    fn release_train_model_cli_rejects_unknown_option() {
        let err = run_release_train_model_command(&["--weird".into()])
            .expect_err("release-train-model unknown option must fail");
        assert!(err.to_string().contains("unknown option"));
    }

    #[test]
    fn release_train_model_is_advertised_in_cli_usage() {
        let usage = cli_usage();
        assert!(
            usage.contains("release-train-model") && usage.contains("release-train"),
            "cli usage must advertise release-train-model command and alias"
        );
    }
}

