    #[test]
    fn nbuild_wasm32_wasi_target_generates_wasm_os_launcher_lane() {
        let clean_dir = make_temp_path("nbuild_wasm32_wasi_lane", "dir");
        std::fs::create_dir_all(&clean_dir).expect("wasm lane temp dir must be created");
        let source_path = clean_dir.join("wasm_lane.n");
        std::fs::write(
            &source_path,
            r#"
wasmLane[@runtime] {
    fn:
        run() -> bool {
            public:
                return true;
        }

    ref main ->> @fn(run);

    fa:
        return true;
}
"#,
        )
        .expect("wasm lane fixture must be writable");

        let artifact_root = clean_dir.join(".ncc");
        let wasm_out = clean_dir.join("wasm_lane.wasm");
        run_nbuild_command(&[
            source_path.to_string_lossy().to_string(),
            wasm_out.to_string_lossy().to_string(),
            "--target".to_string(),
            "wasm32-wasi".to_string(),
            "--out-dir".to_string(),
            artifact_root.to_string_lossy().to_string(),
        ])
        .expect("nbuild wasm32-wasi lane must build a wasm module and OS launchers");

        let wasm_bytes = std::fs::read(&wasm_out).expect("wasm output must exist");
        assert!(
            wasm_bytes.len() >= 8 && &wasm_bytes[0..4] == b"\0asm",
            "wasm output must carry real wasm magic/version bytes"
        );

        let manifest_path = artifact_root.join("run").join("wasm_lane.wasm-build.json");
        let manifest: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&manifest_path).expect("wasm manifest must exist"),
        )
        .expect("wasm manifest must be valid json");
        assert_eq!(
            manifest.get("status").and_then(|value| value.as_str()),
            Some("wasm_os_lane_passed")
        );
        assert_eq!(
            manifest
                .pointer("/truth_boundary/wasm_magic_and_version_emitted")
                .and_then(|value| value.as_bool()),
            Some(true)
        );
        for rel in [
            "bin/wasm_lane.wasm.ps1",
            "bin/wasm_lane.wasm.bat",
            "bin/wasm_lane.wasm.sh",
            "code/wasm_lane_wasm_launcher.n",
        ] {
            assert!(
                artifact_root.join(rel).is_file(),
                "expected wasm OS lane artifact {rel}"
            );
        }
    }

    #[test]
    fn text_bytes_cli_payload_reports_real_utf8_literal_bytes() {
        let path = super::example_compat_path("backend/text_byte_lowering_utf8.n");
        let path = path.to_string_lossy().to_string();
        let payload = text_literal_bytes_payload(&path).expect("text bytes payload");
        assert_eq!(
            payload.get("status").and_then(|value| value.as_str()),
            Some("closed")
        );
        let literals = payload
            .get("literals")
            .and_then(|value| value.as_array())
            .expect("literals array");
        let utf8_literal = literals
            .iter()
            .find(|literal| literal.get("text").and_then(|value| value.as_str()) == Some("Añe🙂"))
            .expect("Añe🙂 literal report");
        assert_eq!(
            utf8_literal
                .get("bytes_hex")
                .and_then(|value| value.as_str()),
            Some("41c3b165f09f9982")
        );
        assert_eq!(
            utf8_literal
                .get("nul_terminated_bytes_hex")
                .and_then(|value| value.as_str()),
            Some("41c3b165f09f998200")
        );
    }

    #[test]
    fn text_bytes_cli_payload_reports_decoded_escape_bytes() {
        let path = super::example_compat_path("backend/text_byte_escape_sequences.n");
        let path = path.to_string_lossy().to_string();
        let payload = text_literal_bytes_payload(&path).expect("text bytes payload");
        let literals = payload
            .get("literals")
            .and_then(|value| value.as_array())
            .expect("literals array");
        let escaped_literal = literals
            .iter()
            .find(|literal| {
                literal
                    .get("text")
                    .and_then(|value| value.as_str())
                    .map(|text| text.starts_with("line\nquote\""))
                    .unwrap_or(false)
            })
            .expect("decoded escape literal report");
        assert_eq!(
            escaped_literal
                .get("bytes_hex")
                .and_then(|value| value.as_str()),
            Some("6c696e650a71756f74652220736c6173685c206e756c00206865784120736d696c65f09f9982")
        );
    }

    #[test]
    fn text_bytes_cli_payload_reports_character_roles_and_functions() {
        let path = super::example_compat_path("backend/text_byte_weird_characters.n");
        let path = path.to_string_lossy().to_string();
        let payload = text_literal_bytes_payload(&path).expect("text bytes payload");
        let units = payload
            .get("literals")
            .and_then(|value| value.as_array())
            .and_then(|literals| literals.iter().find_map(|literal| literal.get("units")))
            .and_then(|value| value.as_array())
            .expect("unit array");

        for role in [
            "non_ascii_letter",
            "currency_symbol",
            "math_symbol",
            "arrow_symbol",
            "emoji_or_pictograph",
            "combining_mark",
            "separator",
        ] {
            assert!(
                units
                    .iter()
                    .any(|unit| unit.get("role").and_then(|value| value.as_str()) == Some(role)),
                "expected text-bytes report to include role {role}"
            );
        }

        let euro = units
            .iter()
            .find(|unit| unit.get("scalar").and_then(|value| value.as_str()) == Some("€"))
            .expect("euro unit");
        assert_eq!(
            euro.get("hex").and_then(|value| value.as_str()),
            Some("E2 82 AC")
        );
        assert_eq!(
            euro.get("backend_action").and_then(|value| value.as_str()),
            Some("emit_utf8_payload_bytes")
        );
        assert!(euro
            .get("function")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .contains("currency"));
    }

    #[test]
    fn optimize_cli_payload_reports_debugger_ux_parity() {
        let path = super::example_compat_path("backend/debugger_ux_optimized_transformations.n");
        let path = path.to_string_lossy().to_string();
        let args: Vec<String> = Vec::new();
        let payload = build_optimizer_payload_from_source(&path, &args).expect("optimizer payload");
        let ast_debugger = payload
            .pointer("/internal_optimizer/ast/debugger_ux")
            .expect("ast debugger UX report");
        assert_eq!(
            ast_debugger.get("schema").and_then(|value| value.as_str()),
            Some("ncc.optimizer.debugger_ux.v1")
        );
        assert_eq!(
            ast_debugger.get("status").and_then(|value| value.as_str()),
            Some("debugger_ux_parity_closed")
        );
        assert_eq!(
            ast_debugger.get("parity").and_then(|value| value.as_bool()),
            Some(true)
        );
        let transforms = ast_debugger
            .get("transformations")
            .and_then(|value| value.as_array())
            .expect("debugger UX transformations");
        assert!(transforms.iter().any(|row| {
            row.get("transform").and_then(|value| value.as_str())
                == Some("constant_fold_or_pure_simplification")
                && row
                    .get("source_span_policy")
                    .and_then(|value| value.as_str())
                    .map(|text| text.contains("ProgramSourceMapIR"))
                    .unwrap_or(false)
        }));
        assert!(transforms.iter().any(|row| {
            row.get("transform").and_then(|value| value.as_str())
                == Some("dead_control_flow_or_unreachable_statement_elimination")
                && row
                    .get("breakpoint_policy")
                    .and_then(|value| value.as_str())
                    .map(|text| text.contains("optimized-out"))
                    .unwrap_or(false)
        }));
    }

