#[cfg(test)]
#[cfg(not(ncc_public_beta))]
mod release_f21_acceptance_gate_tests {
    use super::*;
    use std::path::PathBuf;

    struct ModeOkCase {
        mode: &'static str,
        fixture_rel: &'static str,
        runnable: bool,
    }

    struct ModeFailCase {
        mode: &'static str,
        fixture_rel: &'static str,
        expected_diag: &'static str,
    }

    fn load_program(rel: &str) -> ncc_ast::Program {
        let path = super::example_compat_path(rel);
        let src = std::fs::read_to_string(&path).expect("fixture read");
        let tokens = ncc_lexer::lex(&src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    fn assert_mode_ok_case(case: &ModeOkCase) {
        let ast = load_program(case.fixture_rel);
        let sema = ncc_sema::analyze(&ast);
        assert!(
            sema.is_ok(),
            "mode '{}' fixture '{}' must pass sema, got {:?}",
            case.mode,
            case.fixture_rel,
            sema
        );

        let backend =
            emit_backend_from_ast_with_profile(&ast, ncc_ir::BackendLoweringProfileIR::nc_sysv64())
                .expect("backend emission must pass");
        assert!(
            backend.contains("; ncc backend emission target="),
            "mode '{}' fixture '{}' must emit typed backend header",
            case.mode,
            case.fixture_rel
        );

        let object = emit_backend_object_ir_from_ast_with_profile(
            &ast,
            ncc_ir::BackendLoweringProfileIR::nc_sysv64(),
        )
        .expect("object emission must pass");
        let deferred_text = object
            .sections
            .iter()
            .filter(|section| {
                section.kind == ncc_ir::BackendObjectSectionKindIR::Text && section.bytes.is_none()
            })
            .collect::<Vec<_>>();
        if deferred_text.is_empty() {
            let elf = ncc_ir::emit_object_elf64(&object).expect("ELF64 materialization must pass");
            assert!(
                elf.len() > 64,
                "mode '{}' fixture '{}' must materialize non-trivial ELF output",
                case.mode,
                case.fixture_rel
            );
        } else {
            assert!(
                deferred_text
                    .iter()
                    .all(|section| section
                        .lines
                        .first()
                        .is_some_and(|line| line.contains("route=deferred")
                            && line.contains("complete=false"))),
                "mode '{}' fixture '{}' must expose explicit deferred lowering coverage: {:?}",
                case.mode,
                case.fixture_rel,
                deferred_text
                    .iter()
                    .map(|section| (&section.unit, section.lines.first()))
                    .collect::<Vec<_>>()
            );
            let err = ncc_ir::emit_object_elf64(&object)
                .expect_err("deferred high-level text must never become an executable ret stub");
            assert!(err.contains("has no native bytes"), "{err}");
        }

        if case.runnable {
            let result = run_main(&ast);
            assert!(
                matches!(result, Ok(RuntimeValue::Bool(true))),
                "mode '{}' fixture '{}' must run and return true, got {:?}",
                case.mode,
                case.fixture_rel,
                result
            );
        }
    }

    #[test]
    fn f21_mode_matrix_ok_cases_cover_active_modes_end_to_end() {
        let cases = [
            ModeOkCase {
                mode: "[@]",
                fixture_rel: "root_at/root_at_materialized_run_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@machine]",
                fixture_rel: "machine/legacy_at/machine_at_strict_ok.n",
                runnable: false,
            },
            ModeOkCase {
                mode: "primitive[@]",
                fixture_rel: "primitive_at/primitive_at_boot_serial_material_ok.n",
                runnable: false,
            },
            ModeOkCase {
                mode: "linking soberano",
                fixture_rel: "linking_l9_full_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@inspect]",
                fixture_rel: "inspect_at/inspect_at_runtime_contract_ok.n",
                runnable: false,
            },
            ModeOkCase {
                mode: "[@security]",
                fixture_rel: "security_at/security_at_runtime_allow_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@network]",
                fixture_rel: "network_at/network_at_flow_contract_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@system]",
                fixture_rel: "system_at/system_at_lifecycle_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@tooling]",
                fixture_rel: "tooling_at/tooling_at_lifecycle_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@compiler]",
                fixture_rel: "compiler_at/compiler_at_lifecycle_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@kernel]",
                fixture_rel: "kernel_at/kernel_at_lifecycle_ok.n",
                runnable: true,
            },
            ModeOkCase {
                mode: "[@ai]",
                fixture_rel: "ai_at/ai_at_lifecycle_ok.n",
                runnable: true,
            },
        ];

        for case in &cases {
            assert_mode_ok_case(case);
        }
    }

    #[test]
    fn f21_mode_matrix_fail_cases_keep_official_diagnostics() {
        let cases = [
            ModeFailCase {
                mode: "[@]",
                fixture_rel: "root_at/root_at_missing_final_fail.n",
                expected_diag: "missing fa/final section in [@] root container",
            },
            ModeFailCase {
                mode: "[@machine]",
                fixture_rel: "machine/legacy_at/machine_at_missing_final_fail.n",
                expected_diag: "missing final section in [@machine] container",
            },
            ModeFailCase {
                mode: "primitive[@]",
                fixture_rel: "primitive_at/primitive_at_seal_without_bridge_fail.n",
                expected_diag: "seal section requires at least one bridge section",
            },
            ModeFailCase {
                mode: "linking soberano",
                fixture_rel: "linking_l9_fail_container.n",
                expected_diag: "container 'ghost' not found",
            },
            ModeFailCase {
                mode: "[@inspect]",
                fixture_rel: "inspect_at/inspect_at_heap_contract_missing_fail.n",
                expected_diag: "inspect path 'heap.events.count' requires heap runtime contract import",
            },
            ModeFailCase {
                mode: "[@security]",
                fixture_rel: "security_at/security_at_attack_import_without_lab_fail.n",
                expected_diag: "SEC047: offensive security imports require 'allowOffensive >> bool : true' in [@security] stc",
            },
            ModeFailCase {
                mode: "[@network]",
                fixture_rel: "network_at/network_at_missing_baseline_stc_fail.n",
                expected_diag: "missing stc declaration 'connected >> bool : ...' in [@network] container",
            },
            ModeFailCase {
                mode: "[@system]",
                fixture_rel: "system_at/system_at_missing_baseline_stc_fail.n",
                expected_diag: "missing stc declaration 'systemOpen >> bool : ...' in [@system] container",
            },
            ModeFailCase {
                mode: "[@tooling]",
                fixture_rel: "tooling_at/tooling_at_missing_baseline_stc_fail.n",
                expected_diag: "missing stc declaration 'lintReady >> bool : ...' in [@tooling] container",
            },
            ModeFailCase {
                mode: "[@compiler]",
                fixture_rel: "compiler_at/compiler_at_missing_baseline_stc_fail.n",
                expected_diag: "missing stc declaration 'parseReady >> bool : ...' in [@compiler] container",
            },
            ModeFailCase {
                mode: "[@kernel]",
                fixture_rel: "kernel_at/kernel_at_missing_baseline_stc_fail.n",
                expected_diag: "missing stc declaration 'schedulerOpen >> bool : ...' in kernel profile",
            },
            ModeFailCase {
                mode: "[@ai]",
                fixture_rel: "ai_at/ai_at_missing_baseline_stc_fail.n",
                expected_diag: "missing stc declaration 'sessionActive >> bool : ...' in [@ai] container",
            },
        ];

        for case in cases {
            let ast = load_program(case.fixture_rel);
            let sema = ncc_sema::analyze(&ast);
            assert!(
                sema.is_err(),
                "mode '{}' fixture '{}' must fail in sema",
                case.mode,
                case.fixture_rel
            );
            let msg = sema.err().unwrap();
            assert!(
                msg.contains(case.expected_diag),
                "mode '{}' fixture '{}' expected diagnostic {:?}, got {:?}",
                case.mode,
                case.fixture_rel,
                case.expected_diag,
                msg
            );
        }
    }

    #[test]
    fn f21_release_matrix_document_tracks_closed_rows_as_si() {
        let matrix_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../docs/spec/release/v1_0_acceptance_matrix.md");
        let matrix = std::fs::read_to_string(matrix_path).expect("matrix doc read");

        for expected_line in [
            "| `[@]` (F1 base + endurecimiento v1) | SI | SI | SI | SI | SI | SI | SI | SI | SI |",
            "| `[@machine]` (F2 + expansión ISA v1) | SI | SI | SI | SI | SI | SI | SI | SI | SI |",
            "| Linking soberano (F4) | SI | SI | SI | SI | SI | SI | SI | SI | SI |",
            "| Backend material defendible (F20) | SI | SI | SI | SI | SI | SI | SI | SI | SI |",
        ] {
            assert!(
                matrix.contains(expected_line),
                "matrix doc must contain exact closure row: {}",
                expected_line
            );
        }
    }
}

#[cfg(test)]
#[cfg(not(ncc_public_beta))]
mod release_f22_documentation_gate_tests {
    use std::path::PathBuf;

    fn repo_doc(rel: &str) -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../")
            .join(rel)
    }

    fn read_doc(rel: &str) -> String {
        std::fs::read_to_string(repo_doc(rel)).expect("documentation file must be readable")
    }

    #[test]
    fn f22_required_documentation_bundle_exists_and_is_non_empty() {
        let required = [
            "docs/spec/release/v1_0_spec_maestra.md",
            "docs/spec/release/v1_0_roadmap_master_sync.md",
            "docs/spec/release/v1_0_binary_closure_acta.md",
            "docs/spec/release/v1_0_install_usage_guide.md",
            "docs/spec/release/v1_0_modes_guide.md",
            "docs/spec/release/v1_0_build_run_guide.md",
            "docs/spec/release/v1_0_tooling_guide.md",
            "docs/spec/release/v1_0_handoff_third_parties.md",
            "docs/spec/release/v1_0_features_table.md",
            "docs/spec/release/v1_0_compatibility_table.md",
            "docs/spec/release/v1_0_stability_scope_table.md",
        ];

        for rel in required {
            let path = repo_doc(rel);
            let meta = std::fs::metadata(&path)
                .unwrap_or_else(|_| panic!("required doc '{}' must exist", rel));
            assert!(
                meta.is_file() && meta.len() > 0,
                "required doc '{}' must be a non-empty regular file",
                rel
            );
        }
    }

    #[test]
    fn f22_spec_maestra_contains_release_documentation_contract() {
        let spec = read_doc("docs/spec/release/v1_0_spec_maestra.md");
        for required_phrase in [
            "Spec maestra",
            "Jerarquía canónica",
            "Superficie oficial incluida en v1.0.0",
            "Documentación de versión mayor (F22)",
            "v1_0_binary_closure_acta.md",
            "v1_0_install_usage_guide.md",
            "v1_0_modes_guide.md",
            "v1_0_build_run_guide.md",
            "v1_0_tooling_guide.md",
            "v1_0_handoff_third_parties.md",
            "v1_0_features_table.md",
            "v1_0_compatibility_table.md",
            "v1_0_stability_scope_table.md",
        ] {
            assert!(
                spec.contains(required_phrase),
                "spec maestra must contain phrase {:?}",
                required_phrase
            );
        }
    }

    #[test]
    fn f22_acceptance_matrix_marks_documentation_row_as_closed() {
        let matrix = read_doc("docs/spec/release/v1_0_acceptance_matrix.md");
        assert!(
            matrix.contains(
                "| Documentación de versión (F22) | N/A | N/A | N/A | N/A | N/A | N/A | N/A | SI | SI |"
            ),
            "acceptance matrix must mark F22 docs row as SI/SI"
        );
        assert!(
            matrix.contains("Referencia de evidencia F22:"),
            "acceptance matrix must include F22 evidence anchor"
        );
        assert!(
            matrix.contains("docs/spec/release/v1_0_spec_maestra.md"),
            "acceptance matrix must reference F22 evidence documents"
        );
    }

    #[test]
    fn f22_roadmap_marks_phase_as_closed() {
        let roadmap = read_doc("docs/spec/release/v1_0_roadmap_obligatorio.md");
        assert!(
            roadmap.contains("SI` F22")
                || roadmap.contains("`SI` F22")
                || roadmap.contains("F22 Documentación mayor. (`SI`"),
            "roadmap must mark F22 as closed"
        );
    }
}

