    fn repo_path(rel: &str) -> PathBuf {
        super::repo_compat_path(rel)
    }

    fn read_text(rel: &str) -> String {
        std::fs::read_to_string(repo_path(rel))
            .unwrap_or_else(|_| panic!("required file '{}' must be readable", rel))
    }

    struct CurrentDirGuard {
        previous: PathBuf,
    }

    impl CurrentDirGuard {
        fn enter(path: &Path) -> Self {
            let previous = env::current_dir().expect("current dir must be readable");
            env::set_current_dir(path).expect("test must switch cwd");
            Self { previous }
        }
    }

    impl Drop for CurrentDirGuard {
        fn drop(&mut self) {
            let _ = env::set_current_dir(&self.previous);
        }
    }

