    #[cfg(unix)]
    fn make_fake_linker_script() -> PathBuf {
        let script = make_temp_path("phase7_fake_linker", "sh");
        let body = r#"#!/usr/bin/env sh
set -eu
out=""
while [ "$#" -gt 0 ]; do
  if [ "$1" = "-o" ]; then
    out="$2"
    shift 2
    continue
  fi
  shift
done
if [ -z "$out" ]; then
  echo "missing -o output path" >&2
  exit 2
fi
printf 'NCC-PHASE7-LINK' > "$out"
exit 0
"#;
        std::fs::write(&script, body).expect("fake linker script must write");
        let mut perms = std::fs::metadata(&script)
            .expect("fake linker script metadata must be readable")
            .permissions();
        perms.set_mode(0o755);
        std::fs::set_permissions(&script, perms).expect("fake linker script must be executable");
        script
    }

