    #[test]
    fn phase7_resolve_lock_and_verify_lock_are_deterministic() {
        let work_dir = make_temp_path("phase7_npkg", "dir");
        std::fs::create_dir_all(&work_dir).expect("phase7 temp dir must be created");

        let source = write_import_fixture(&work_dir)
            .to_string_lossy()
            .to_string();
        let registry = write_registry_fixture(&work_dir)
            .to_string_lossy()
            .to_string();
        let resolve_a = work_dir
            .join("resolve_a.json")
            .to_string_lossy()
            .to_string();
        let resolve_b = work_dir
            .join("resolve_b.json")
            .to_string_lossy()
            .to_string();
        let lock_a = work_dir
            .join("phase7_a.lock.json")
            .to_string_lossy()
            .to_string();
        let lock_b = work_dir
            .join("phase7_b.lock.json")
            .to_string_lossy()
            .to_string();

        run_npkg_command(&[
            "resolve".to_string(),
            source.clone(),
            "--registry".to_string(),
            registry.clone(),
            "--out".to_string(),
            resolve_a.clone(),
        ])
        .expect("npkg resolve A must pass");
        run_npkg_command(&[
            "resolve".to_string(),
            source.clone(),
            "--registry".to_string(),
            registry.clone(),
            "--out".to_string(),
            resolve_b.clone(),
        ])
        .expect("npkg resolve B must pass");

        let resolve_a_text =
            std::fs::read_to_string(&resolve_a).expect("resolve A output must be readable");
        let resolve_b_text =
            std::fs::read_to_string(&resolve_b).expect("resolve B output must be readable");
        assert_eq!(
            resolve_a_text, resolve_b_text,
            "phase7 resolve output must be byte-deterministic"
        );
        let resolve_json: serde_json::Value =
            serde_json::from_str(&resolve_a_text).expect("resolve output must be valid JSON");
        assert_eq!(
            resolve_json.get("schema").and_then(|v| v.as_str()),
            Some("npkg.resolve.v1"),
            "phase7 resolve schema must stay official"
        );
        let deps = resolve_json
            .get("dependencies")
            .and_then(|v| v.as_array())
            .expect("resolve dependencies must be array");
        assert_eq!(
            deps.len(),
            3,
            "phase7 resolve should dedup and resolve imports"
        );

        run_npkg_command(&[
            "lock".to_string(),
            source.clone(),
            "--registry".to_string(),
            registry.clone(),
            "--lock".to_string(),
            lock_a.clone(),
        ])
        .expect("npkg lock A must pass");
        run_npkg_command(&[
            "lock".to_string(),
            source.clone(),
            "--registry".to_string(),
            registry.clone(),
            "--lock".to_string(),
            lock_b.clone(),
        ])
        .expect("npkg lock B must pass");

        let lock_a_text = std::fs::read_to_string(&lock_a).expect("lock A must be readable");
        let lock_b_text = std::fs::read_to_string(&lock_b).expect("lock B must be readable");
        assert_eq!(
            lock_a_text, lock_b_text,
            "phase7 lock output must be deterministic"
        );

        run_npkg_command(&[
            "verify-lock".to_string(),
            source.clone(),
            "--registry".to_string(),
            registry.clone(),
            "--lock".to_string(),
            lock_a.clone(),
        ])
        .expect("npkg verify-lock must pass when lock is official");

        let mut lock_json: serde_json::Value =
            serde_json::from_str(&lock_a_text).expect("lock must be valid JSON");
        if let Some(first_dep) = lock_json
            .get_mut("dependencies")
            .and_then(|v| v.as_array_mut())
            .and_then(|deps| deps.first_mut())
        {
            first_dep["selected"] = serde_json::json!("9.9.9");
        }
        std::fs::write(
            &lock_a,
            serde_json::to_string_pretty(&lock_json).expect("tampered lock JSON serialize"),
        )
        .expect("tampered lock must be writable");
        let drift = run_npkg_command(&[
            "verify-lock".to_string(),
            source,
            "--registry".to_string(),
            registry,
            "--lock".to_string(),
            lock_a,
        ]);
        assert!(drift.is_err(), "verify-lock must fail on lock drift");
    }

