    #[test]
    fn phase8_dx_profile_reports_pipeline_trace_for_check_and_run() {
        let check_fixture = repo_path("examples/root_at/root_at_minimal_ok.n")
            .to_string_lossy()
            .to_string();
        let run_fixture_path = make_temp_path("phase8_dx_run_fixture", "n");
        let run_fixture_src = r#"
dxProfileRunFixture[@] {
    to main {
        print("ok");
    }

    fa:
        return true;
}
"#;
        std::fs::write(&run_fixture_path, run_fixture_src)
            .expect("phase8 dx run fixture must be writable");
        let run_fixture = run_fixture_path.to_string_lossy().to_string();
        let out_check = make_temp_path("phase8_dx_check", "json")
            .to_string_lossy()
            .to_string();
        let out_run = make_temp_path("phase8_dx_run", "json")
            .to_string_lossy()
            .to_string();

        run_dx_profile_command(&[
            "check".to_string(),
            check_fixture,
            "--out".to_string(),
            out_check.clone(),
        ])
        .expect("dx-profile check must pass");
        run_dx_profile_command(&[
            "run".to_string(),
            run_fixture,
            "--out".to_string(),
            out_run.clone(),
        ])
        .expect("dx-profile run must pass");

        let check_raw =
            std::fs::read_to_string(&out_check).expect("dx-profile check report must read");
        let run_raw = std::fs::read_to_string(&out_run).expect("dx-profile run report must read");
        let check_json: serde_json::Value =
            serde_json::from_str(&check_raw).expect("dx-profile check report must be JSON");
        let run_json: serde_json::Value =
            serde_json::from_str(&run_raw).expect("dx-profile run report must be JSON");

        for value in [&check_json, &run_json] {
            assert_eq!(
                value.get("mode").and_then(|v| v.as_str()),
                Some("ncc.dx.profile.v1"),
                "dx-profile mode must stay official"
            );
            assert_eq!(
                value.get("status").and_then(|v| v.as_str()),
                Some("ok"),
                "dx-profile check/run should be OK for minimal fixture"
            );
            let durations = value
                .get("durations_ms")
                .and_then(|v| v.as_object())
                .expect("dx-profile durations_ms must be object");
            assert!(
                durations.contains_key("read_source_ms")
                    && durations.contains_key("lex_ms")
                    && durations.contains_key("parse_ms")
                    && durations.contains_key("source_conventions_ms")
                    && durations.contains_key("sema_ms"),
                "dx-profile report must include official compile stages"
            );
        }

        let run_durations = run_json
            .get("durations_ms")
            .and_then(|v| v.as_object())
            .expect("dx-profile run durations must be object");
        assert!(
            run_durations.contains_key("main_entry_validation_ms")
                && run_durations.contains_key("runtime_ms"),
            "dx-profile run must include runtime stages"
        );
        assert!(
            run_json.get("return_value").is_some(),
            "dx-profile run should include return_value field"
        );
    }

