#[cfg(test)]
mod runtime_pointer_generic_tests {
    use super::*;

    fn parse_src(src: &str) -> ncc_ast::Program {
        let tokens = ncc_lexer::lex(src).expect("lex");
        ncc_parser::parse(tokens).expect("parse")
    }

    #[test]
    fn runtime_ptr_generic_null_projection_roundtrip() {
        let src = r#"
entry[@] {
    stc:
        p: ptr<int>;

    fn:
        public boot() -> text {
            public:
                @p >> ptr<int> | null : null;
                return @p;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast).expect("ptr<T> null projection should run coherently");
        assert!(matches!(
            result,
            RuntimeValue::Pointer(RuntimePointer::Null)
        ));
    }

    #[test]
    fn runtime_ptr_generic_alloc_projection_updates_heap_actor_and_alias_metadata() {
        let src = r#"
use memory.heap.manager;

entry[@] {
    stc:
        p: ptr<int>;

    fn:
        public boot() -> bool {
            public:
                @p !> ptr<int> : memory.heap.manager.alloc(64);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let container = ast
            .containers
            .first()
            .expect("expected one container")
            .name
            .clone();
        let mut state = ExecState::default();
        let result = exec_function(&ast, &container, "boot", &[], &mut state)
            .expect("runtime ptr<T> alloc projection should run");
        assert!(matches!(result, RuntimeValue::Bool(true)));

        assert_eq!(state.heap_blocks.len(), 1, "expected one live heap block");
        let block = state
            .heap_blocks
            .values()
            .next()
            .expect("expected heap block after alloc");
        assert_eq!(block.creator_symbol.as_deref(), Some("p"));
        assert_eq!(block.last_binder_symbol.as_deref(), Some("p"));
        assert_eq!(block.last_actor_symbol.as_deref(), Some("p"));

        let last_event = state.heap_events.last().expect("expected alloc heap event");
        assert_eq!(last_event.actor_symbol.as_deref(), Some("p"));
    }

    #[test]
    fn runtime_ptr_generic_interprocedural_free_propagates_through_addr_cast_alias() {
        let src = r#"
use memory.heap.manager;

entry[@] {
    stc:
        p: ptr<int>;
        q: ptr<int>;
        pa: addr;
        qa: addr;

    fn:
        public cleanup(a: addr) -> bool {
            public:
                memory.heap.manager.free(@a);
                return true;
        }

        public boot() -> bool {
            public:
                @p !> ptr<int> : memory.heap.manager.alloc(64);
                @q >> ptr<int> : @p;
                @pa !> addr : @p;
                cleanup(@pa);
                @qa !> addr : @q;
                memory.heap.manager.zero(@qa, 64);
                return true;
        }

    ref main ->> @fn(boot);

    fa:
        return true;
}
"#;
        let ast = parse_src(src);
        let result = run_main(&ast);
        assert!(result.is_err(), "expected stale/freed alias use to fail");
        let msg = result.err().unwrap().to_string();
        assert!(
            msg.contains("E_PTR_STALE_SITE_001")
                || msg.contains("memory.heap.manager.zero cannot use freed block")
                || msg.contains("memory.heap.manager.zero cannot use stale block"),
            "unexpected runtime error: {}",
            msg
        );
    }
}

