    #[test]
    fn runtime_control_flow_surface_v1_0_1_executes_end_to_end() {
        let src = r#"
phaseAFlow[@] {
    stc:
        items: list<int>;
        run: bool;
        i: int;
        sum: int;

    fn:
        flow() -> bool {
            public:
                @run >> bool : true;
                @i >> int : 0;
                @sum >> int : 0;

                @items.push(1);
                @items.push(2);
                @items.push(3);

                while (@run) {
                    @sum >> int : @sum + 1;
                    break;
                }

                do {
                    @i >> int : @i + 1;
                } while (@i < 2);

                for (@i >> int : 0; @i < 3; @i >> int : @i + 1) {
                    if (@i == 1) {
                        continue;
                    }
                    @sum >> int : @sum + @i;
                }

                for item in @items {
                    @sum >> int : @sum + @item;
                }

                same in v : @items {
                    @sum >> int : @sum + @v;
                }

                for j in 0..2 {
                    @sum >> int : @sum + 1;
                }

                for k in 0..=2 step 1 {
                    @sum >> int : @sum + 1;
                }

                loop {
                    break;
                }

                repeat {
                    @i >> int : @i + 1;
                } until (@i > 3);

                same for (2) {
                    @sum >> int : @sum + 2;
                }

                each e in @items do {
                    @sum >> int : @sum + @e;
                } while (@run);

                switch (@i) {
                    case 4 {
                        @sum >> int : @sum + 10;
                    }
                    default {
                        @sum >> int : @sum + 100;
                    }
                }

                match (@i) {
                    case 4 => {
                        @sum >> int : @sum + 20;
                    }
                    default => {
                        @sum >> int : @sum + 200;
                    }
                }

                guard (@run) else {
                    return false;
                }

                select {
                    when (@sum > 50) {
                        @sum >> int : @sum + 1;
                    }
                    default {
                        @sum >> int : 0;
                    }
                }

                Notif (@run) {
                    @sum >> int : 0;
                } else {
                    @sum >> int : @sum + 1;
                }

                @sum >> int : if (@run) { @sum + 1 } else { 0 };
                return @sum == 63;
        }

    ref main ->> @fn(flow);

    fa:
        return true;
}
"#;
        assert!(matches!(run_src(src), RuntimeValue::Bool(true)));
    }

