    #[test]
    fn phase10_jetbrains_ncup_which_and_router_flow_are_actionable() {
        let home = make_temp_path("ncup-phase10-p10-home", "dir");
        let home_raw = home.to_string_lossy().to_string();
        let project = make_temp_path("ncup-phase10-p10-project", "dir");
        let _ = std::fs::remove_dir_all(&home);
        let _ = std::fs::remove_dir_all(&project);
        std::fs::create_dir_all(&project).expect("phase10 p10 project dir must exist");

        if !prebuilt_toolchain() {
        let build = Command::new("cargo")
            .arg("build")
            .arg("-p")
            .arg("ncc-cli")
            .arg("--bin")
            .arg("ncup")
            .current_dir(repo_root())
            .status()
            .expect("phase10 p10 cargo build --bin ncup must execute");
        assert!(
            build.success(),
            "phase10 p10 cargo build --bin ncup must succeed"
        );
        }
        let ncup_bin = super::target_debug_bin("ncup");

        let init = Command::new(&ncup_bin)
            .args(["init", "--home", &home_raw, "--profile", "default", "--force"])
            .current_dir(repo_root())
            .output()
            .expect("phase10 p10 native ncup init must execute");
        assert!(
            init.status.success(),
            "phase10 p10 ncup init must pass: {}",
            String::from_utf8_lossy(&init.stderr)
        );
        let which = Command::new(&ncup_bin)
            .args(["which", "ncc", "--home", &home_raw, "--json"])
            .current_dir(repo_root())
            .output()
            .expect("phase10 p10 native ncup which must execute");
        assert!(
            which.status.success(),
            "phase10 p10 ncup which ncc must pass: {}",
            String::from_utf8_lossy(&which.stderr)
        );
        let which_json: serde_json::Value =
            serde_json::from_slice(&which.stdout).expect("ncup which output must be JSON");
        assert_eq!(which_json["schema"], "ncup.which.v1");
        assert_eq!(which_json["bin"], "ncc");
        assert!(
            PathBuf::from(which_json["path"].as_str().expect("ncc path must be a string"))
                .is_file(),
            "resolved ncc must be an actual installed file"
        );

        let high_level = project.join("jetbrains_high_level.n");
        std::fs::write(&high_level, "demo { to main { print(1); } }\n")
            .expect("phase10 p10 high-level fixture must be writable");
        let low_level = project.join("jetbrains_low_level.nb");
        std::fs::write(
            &low_level,
            "[@] rootX { stc: a:int; to main { @a >> int : 1; } }\n",
        )
        .expect("phase10 p10 low-level fixture must be writable");

        let router = native_tool();
        let high = Command::new(&router)
            .arg("route-jetbrains")
            .arg("--file")
            .arg(high_level.to_string_lossy().to_string())
            .arg("--ncup")
            .arg(ncup_bin.to_string_lossy().to_string())
            .arg("--json")
            .env("NCUP_HOME", home_raw.clone())
            .current_dir(repo_root())
            .output()
            .expect("phase10 p10 high-level router invocation must execute");
        assert!(
            high.status.success(),
            "phase10 p10 high-level router must pass; stderr={}",
            String::from_utf8_lossy(&high.stderr)
        );
        let high_json: serde_json::Value = serde_json::from_slice(&high.stdout)
            .expect("phase10 p10 high-level router output must be valid JSON");
        assert_eq!(
            high_json.get("backend").and_then(|v| v.as_str()),
            Some("nclsp"),
            "phase10 p10 high-level file must route to nclsp"
        );
        assert_eq!(
            high_json.get("low_level").and_then(|v| v.as_bool()),
            Some(false),
            "phase10 p10 high-level file must not be low-level"
        );

        let low = Command::new(&router)
            .arg("route-jetbrains")
            .arg("--file")
            .arg(low_level.to_string_lossy().to_string())
            .arg("--ncup")
            .arg(ncup_bin.to_string_lossy().to_string())
            .arg("--json")
            .env("NCUP_HOME", home_raw.clone())
            .current_dir(repo_root())
            .output()
            .expect("phase10 p10 low-level router invocation must execute");
        assert!(
            low.status.success(),
            "phase10 p10 low-level router must pass; stderr={}",
            String::from_utf8_lossy(&low.stderr)
        );
        let low_json: serde_json::Value = serde_json::from_slice(&low.stdout)
            .expect("phase10 p10 low-level router output must be valid JSON");
        assert_eq!(
            low_json.get("backend").and_then(|v| v.as_str()),
            Some("nc-sys-lsp"),
            "phase10 p10 low-level file must route to nc-sys-lsp"
        );
        assert_eq!(
            low_json.get("low_level").and_then(|v| v.as_bool()),
            Some(true),
            "phase10 p10 low-level file must be detected as low-level"
        );

        let _ = std::fs::remove_dir_all(&home);
        let _ = std::fs::remove_dir_all(&project);
    }

